const ENTRIES=[{"id":"livestock-1","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":1,"title":"OGUN IDAGBASOKE NKAN OSIN","subtitle":"(CHARM FOR GROWTH OF LIVESTOCK)","preview":"CHARM FOR GROWTH OF LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Ewuro- Bitter leaves\n-Ewe Tete egun- Amaranthus spinosus\n-Ewe Ugwu - Telfairia occidentalis\n-Epa- groundnut leaves\n-Agbado- maize leaves\n-Ekuro- palm kernel 1\n-1 ataare\nPreparation:\nWe will pound all the materials separately and\nthen we will mix them together, then we will\nsundry it and turn them into fine powder. Then\nwe will pour it in a white bottle. We will mix\nthis powder in the feeds we give to our life-stock\nto make them grow very fast."},{"id":"livestock-2","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":2,"title":"OOGUN KI NKAN OSIN SANRA DAADAA","subtitle":"(CHARM TO MAKE OUR LIVESTOCKS GROW VERY FAT)","preview":"CHARM TO MAKE OUR LIVESTOCKS GROW VERY FAT · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe ugwu- Telfairia occidentalis\n-Ewe Iyeye- Spondias mombin\n-Ewe Ogede- banana leaves\n-Ogede- 3 banana fruit\n-Agbado- maize\n-koro ibepe- seeds of papaya\nPreparation:\nWe will grind all the materials together and we\nwill make it into a fine powder. Then we will\nmix the powder together with the feed we give\nto our animals."},{"id":"livestock-3","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":3,"title":"AABO NKAN OSIN","subtitle":"(CHARM TO PROTECT OUR LIVESTOCKS FROM DEATH)","preview":"CHARM TO PROTECT OUR LIVESTOCKS FROM DEATH · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Purpose:\nTraditional-style Yoruba livestock protection\ncharm for protecting animals against theft, loss,\nmisfortune, harmful influences, and for helping\nthem return safely.\nMaterials needed:\n-Ewe Akoko- Akoko leaves\n-Ewe Imi Esu / Rerinkomi - Imi esu leaves\n-Mariwo Ope - Young palm frond\n-1 Atare\n-Aridan - Tetrapleura tetraptera\n-Owu Dudu - Black thread\n-Owu Funfun - White thread\n-Small clean cloth or leather pouch\nPREPARATION\nDry the Akoko and Imi Esu leaves naturally.\nTake:\n-7 pieces of dried Akoko leaf\n-7 pieces of dried Imi Esu leaf\n-7 Atare seeds\n-1 small piece of Aridan\nPlace everything inside a small clean cloth or\nleather pouch.\nTie or wrap the pouch securely with black and\nwhite cotton thread.\nThis is prepared as a protective amulet and not\nas medicine for the animals to drink.\nPLACEMENT\nFor the whole herd:\nPlace the charm securely above the entrance of\nthe livestock pen where the animals cannot\nchew or swallow it.\nPlace Mariwo Ope around or above the\nentrance as a traditional boundary and\nprotection symbol.\nFor an individual animal:\nThe protective pouch may traditionally be\nattached around the animal, but it must be\npositioned safely so it cannot choke, tighten, or\ninjure the animal."},{"id":"livestock-4","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":4,"title":"OGUN AABO NKAN OSIN","subtitle":"(LIVESTOCK PROTECTION)","preview":"LIVESTOCK PROTECTION · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Iroko- iroko leaves\n-Ewe Ogede- plantain leaves\n-Elemi- Dacryodes edulis resin\n-Obi Abata oloju merin- 1 kolanut with 4 lobes\n-Owo Eyo- 3 Cowrie shells\n-Igi Iroko to jabo- Small naturally fallen piece of\nIroko wood\n-Igba kekere- Small calabash\n-Oka gbigbe- Dried maize grains\nPREPARATION\nAllow the Iroko and Ogede leaves to dry\nnaturally.\nBreak the dried leaves into small pieces.\nPlace the dried leaves inside a small calabash.\nAdd a small quantity of Elemi.\nAdd one Obi Abata.\nAdd several cowrie shells.\nAdd a small naturally fallen piece of Iroko\nwood.\nAdd a handful of dried maize grains to\nrepresent abundance and continuity of the\nherd.\nClose the calabash securely.\nPLACEMENT\nPlace the prepared calabash securely above or\nbeside the entrance of the livestock pen.\nIt should be positioned where goats, sheep,\ncattle, or poultry cannot reach, chew, break, or\nswallow any of the materials."},{"id":"livestock-5","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":5,"title":"OGUN IDAABOBO ERAN","subtitle":"(PROTECTION OF LIVESTOCKS)","preview":"PROTECTION OF LIVESTOCKS · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Ajeobale - AJeobale leaves\n-Eso Igi Eru - eru alamo\n-Ewe Odundun - odundun leaves\n-Eeru igi iroko - iroko tree ash\n-Aso funfun kekere - Small piece of plain white\ncloth\n-Ikoko Amo Kekere - Small clay pot\nPREPARATION\nDry the leaves naturally.\nPound the dried leaves and a small piece of the\ndried fruit separately.\nMix the powdered plant materials with a little\nwood ash.\nPlace the mixture inside the white cloth and tie\nit securely.\nPut the wrapped preparation inside the small\nclay pot.\nKeep the clay pot securely at the entrance or\ncorner of the livestock pen where the animals\ncannot reach it."},{"id":"livestock-6","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":6,"title":"OGUN IRORUN IBIMO ERAN","subtitle":"(CHARM FOR SAFE DELIVERY OF ANIMALS)","preview":"CHARM FOR SAFE DELIVERY OF ANIMALS · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Iyeye - iyeye leaves\n-Atare - Aframomum melegueta\n-Ila - okra fruits\n-Ekuro Ope - palm kernel\n-Obi - 3 kolanut with 4 lobes\n-Igba kekere - Small calabash\nPREPARATION\nDry the Ewe Iyeye naturally.\nDry the Ila material and pound it lightly.\nBreak the Atare and Obi into small pieces.\nAdd the Ewe Iyeye, Ila, Atare, Obi and Ekuro\nOpe into the small calabash.\nClose the calabash securely.\nKeep it near the livestock birthing pen where\nthe animal cannot eat or reach the materials."},{"id":"livestock-7","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":7,"title":"OGUN AABO ASESEBI ERAN","subtitle":"(CHARM TO PROTECT NEWLY BORN ANIMAL)","preview":"CHARM TO PROTECT NEWLY BORN ANIMAL · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Gbagodo - gbagado leaves\n-Ewe Abamoda - abamoda leaves\n-Ewe Ogede - banana leaves\n-Owo Eyo - Cowrie shells\n-Owu Funfun - White thread\n-Ikoko Amo Kekere - Small clay pot\nPREPARATION\nAllow the Gbagodo and Abamoda leaves to dry\nnaturally.\nCut a small piece of dried Ogede leaf.\nPlace the three plant materials inside the clay\npot.\nAdd the cowrie shells.\nTie white cotton thread around the outside of\nthe pot.\nKeep the preparation securely at the entrance\nor corner of the birthing pen."},{"id":"livestock-8","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":8,"title":"OGUN KI IBIMO MA LE","subtitle":"(CHARM TO MAKE BIRTHING MORE EASY)","preview":"CHARM TO MAKE BIRTHING MORE EASY · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Ipa - esinsin leaves\n-Ewe Bomubomu - bomubomu leaves\n-Igi Orogbo - the bark of bitter kola\n-Orogbo - 3 bitter kola\n-Aso Funfun - Small white cloth\n-Apo Awure Kekere - Small protective pouch\nPREPARATION\nDry the Ewe Ipa completely.\nUse only a symbolic dried piece of Bomubomu\nleaf.\nPlace the Ewe Ipa, dried Bomubomu and\nOrogbo materials inside the white cloth.\nFold the cloth and place it inside the small\nprotective pouch.\nHang the pouch securely outside the livestock\nbirthing enclosure.\nKeep it completely beyond the reach of the\nanimals."},{"id":"livestock-9","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":9,"title":"OGUN IBIMO","subtitle":"(CHARM FOR ANIMALS TO GIVE BIRTH TO PLENTY OFFSPRING)","preview":"CHARM FOR ANIMALS TO GIVE BIRTH TO PLENTY OFFSPRING · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Efinrin - scent leaves\n-Ewe Akoko - akoko leaves\n-Ewe Odundun - odundun leaves\n-Orogbo - 3 bitter kola\n-Owu Pupa - Red thread\n-Owu Funfun - White cotton thread\n-Igba - Small calabash\nPREPARATION\nShade-dry the three leaves.\nBreak them into small pieces without reducing\nthem completely to powder.\nPlace them inside the calabash.\nAdd one piece of Orogbo.\nBind the calabash with red and white cotton\nthread.\nKeep it securely beside the birthing enclosure\nwhere the animal cannot reach it."},{"id":"livestock-10","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":10,"title":"OGUN IBI IRORUN","subtitle":"(EASY BIRTH FOR ANIMALS)","preview":"EASY BIRTH FOR ANIMALS · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Tete - Amaranthus leaves\n-Ewe Oju Oro - oju oro leaves\n-Ewe Atori - atori leaves\n-Aidan - aidan with 3 sides\n-koro agbado- Dried maize grains\n-Owo Eyo - Cowries\n-Ikoko Amo - Small clay pot\nPREPARATION\nDry the plant materials separately.\nBreak the Aidan into a small piece.\nPlace the leaves, Aidan, maize grains and\ncowries inside the clay container.\nClose it securely.\nPlace it close to the livestock enclosure but\ncompletely outside the animal's reach."},{"id":"livestock-11","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":11,"title":"OGUN OGBE NKAN OSIN","subtitle":"(CHARM FOR LIVESTOCK WOUND)","preview":"CHARM FOR LIVESTOCK WOUND · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Tete-Egun - Amaranthus leaves\n-Ewe eti erin- Aloe vera\n-Epo Pupa - Palm oil\n-Ewe Atori - Glyphaea brevis leaves\n-Aso tuntun- Clean cloth\nPREPARATION\nWash the plant materials.\nPound the Tete-Egun and Atori leaves.\nAdd fresh Aloe gel and a little palm oil.\nMix into a soft paste.\nTo be used around the wounds."},{"id":"livestock-12","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":12,"title":"OGUN INU NKAN OSIN","subtitle":"(CHARM FOR LIVESTOCK INTESTINE)","preview":"CHARM FOR LIVESTOCK INTESTINE · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Koro Ibepe - papaya seeds\n-Ewe Ewuro - bitter leaves\n-Ewe Dogoyaro - neem leaves\n-Eso Osan Wewe - lime leaves\n-Ewe ejinrin- ejinrin leaves\nPREPARATION\nDry the pawpaw seeds and leaves separately.\nPound everything separately into powder.\nThe powder will be added to the feed of the\nlivestocks."},{"id":"livestock-13","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":13,"title":"OGUN IGBE GBUURU NKAN OSIN","subtitle":"(CHARM TO MAKE LIVESTOCK PASS FAECES EASILY)","preview":"CHARM TO MAKE LIVESTOCK PASS FAECES EASILY · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Iyeye - iyeye leaves\n-Ewe Efinrin - scent leaves\n-Ewe Guava - guava leaves\n-Ewe ugwu- Telfairia occidentalis leaves\n-Ewe kooko oba- Cymbopogon citratus leaves\nPREPARATION\nWash the leaves thoroughly.\nCrush the leaves together.\nSoak them in clean water.\nStrain the preparation.\nWe will give the water to our animals to drink\nearly in the morning."},{"id":"livestock-14","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":14,"title":"OGUN INA ATI KOKORO NKAN OSIN","subtitle":"(CHARM TO PREVENT LICE AND MITES ON LIVESTOCK)","preview":"CHARM TO PREVENT LICE AND MITES ON LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Eepin - sandpaper leaves\n-Lapalapa Funfun - white iyalode leaves\n-ororo Agbon - Coconut oil\n-Igi iroko- iroko stick\n-Ewe Ogede Gbigbe - Dried banana leaves\nPREPARATION\nWe will pound all the materials together and we\nwill pour it in the coconut oil. Then we will\nleave it to soak for 3 days. We will use the\npreparation to rub the body of the livestock\nafter."},{"id":"livestock-15","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":15,"title":"OGUN ARA NKAN OSIN","subtitle":"(SKIN CONDITION)","preview":"SKIN CONDITION · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Basil - scent leaves\n-Ewe kaju- cashew leaves\n-Ewe Iru - locust beans leaves\n-Ewe Odan - Ficus thonningii\n-Adin dudu- Palm-kernel oil\nPREPARATION\nWash the leaves.\nShade-dry and pound them.\nMix a small amount of the powdered leaves\nwith palm-kernel oil to make paste.\nThen we will use the paste to rub the body of\nthe animal."},{"id":"livestock-16","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":16,"title":"OGUN FUN AGBARA ATI ILERA NKAN OSIN","subtitle":"(CHARM FOR POWER AND GOOD HEALTH OF LIVESTOCK)","preview":"CHARM FOR POWER AND GOOD HEALTH OF LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe gbogbonise- Moringa leaves\n-Ewe Odundun - odundun leaves\n-Ewe Ogede - banana leaves\n-Epa - Arachis hypogaea\n-Ekuro - alot of palm kernel\nPREPARATION\nWe will burn the materials together with 1\nataare and we will grind it to powder. We will\npour the powder in a cotton wool and then we\nwill put it in a snail shell. We will tie a rope to it\nand we will wrap it around our animal neck."},{"id":"livestock-17","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":17,"title":"OGUN ENU NKAN OSIN","subtitle":"(MEDICINE FOR LIVESTOCK MOUTH TREATMENT FOR THEM TO EAT VERY WELL)","preview":"MEDICINE FOR LIVESTOCK MOUTH TREATMENT FOR THEM TO EAT VERY WELL · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ata - green pepper\n-Obi Abata - 2 kolanut with 3 lobes\n-Orogbo - 2 bitter kola\n-Ewe Abamoda - abamoda leaves\n-Epo Orogbo die- small bitter kola bark\nPREPARATION\nDry the leaves.\nPound separately into fine powder and then\nmix them together.\nWe will add the powder in the feed of our\nlivestocks."},{"id":"livestock-18","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":18,"title":"OGUN TI NKAN OSIN BA BIMO","subtitle":"(CHARM TO USE FOR LIVESTOCK AFTER BIRTH)","preview":"CHARM TO USE FOR LIVESTOCK AFTER BIRTH · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Akoko - akoko leaves\n-Ewe Gbagodo - Commelina africana leaves\n-Ewe Oju Oro - oju oro leaves\n-Atale - ginger roots\n-Aridan - 2 aidan fruits\n-Igba Kekere - Small calabash\nPREPARATION\nClean the materials and arrange it in the\ncalabash.\nBreak the Aridan into a small piece.\nPlace everything inside the calabash.\nKeep the preparation beside the livestock\nenclosure."},{"id":"livestock-19","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":19,"title":"OGUN OYAN NKAN OSIN","subtitle":"(CHARM TO MAKE OUR LIVESTOCK PRODUCE GOOD BREAST MILK)","preview":"CHARM TO MAKE OUR LIVESTOCK PRODUCE GOOD BREAST MILK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Ogede - Musa sapientum\n-Ewe Aloe - Aloe vera\n-Ewe Aje - Trichilia monadelpha\n-Ewe Atori - Glyphaea brevis\n-Epo Agbon - Coconut oil\nPREPARATION\nWash the leaves properly.\nPound the plant materials together.\nMix a small portion with coconut oil to form a\nsoft paste.\nApply only externally around breast skin."},{"id":"livestock-20","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":20,"title":"OGUN KOKORO ARA NKAN OSIN","subtitle":"(CHARM TO PREVENT SKIN PARASITE OR SKIN DISEASES FOR LIVESTOCKS)","preview":"CHARM TO PREVENT SKIN PARASITE OR SKIN DISEASES FOR LIVESTOCKS · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Efinrin - Ocimum basilicum\n-Ewe Dogonyaro - neem leaves\n-Ewe Eepin - sandpaper leaves\n-Adin dudu - Palm-kernel oil\nPREPARATION\nShade-dry the Efinrin and Dogonyaro leaves.\nPound them into powder.\nMix with a little palm-kernel oil.\nWe will use the palm kernel oil to rub the body\nof the animal.\nDo not allow the animals to consume the\npreparation."},{"id":"livestock-21","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":21,"title":"OGUN OGBE FUN NKAN OSIN","subtitle":"(CHARM TO TREAT OR PREVENT WOUND FOR OUR LIVESTOCK)","preview":"CHARM TO TREAT OR PREVENT WOUND FOR OUR LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Ewe Tete-Egun - Amaranthus spinosus\n-Ewe Abamoda - abamoda leaves\n-Ewe Odan - odan leaves\n-Ewe Akintola - Chromolaena odorata lleaves\n-Omi - Clean water\nPREPARATION\nWash the leaves thoroughly.\nPound the leaves.\nExtract the liquid using clean water.\nWe will use the water to wash the body of our\nlivestock from time to time."},{"id":"livestock-22","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":22,"title":"OGUN ILERA FUN AWON NKAN OSIN","subtitle":"(MEDICINE FOR GOOD HEALTH FOR OUR LIVESTOCK)","preview":"MEDICINE FOR GOOD HEALTH FOR OUR LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-koro Ibepe - papaya seeds\n-Ewe iroko- iroko leaves\n-Ewe ejinrin- ejinrin leaves\n-Ewe asunwon- asunwon leaves\n-Ewe dagunro- dagunro leaves\nPREPARATION\nShade-dry the plant materials separately.\nPound them together and add to the feed of the\nanimal."},{"id":"livestock-23","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":23,"title":"OGUN ARUN ENU NKAN OSIN","subtitle":"(CHARM TO TREAT AND PREVENT MOUTH DISEASES FOR OUR LIVESTOCK)","preview":"CHARM TO TREAT AND PREVENT MOUTH DISEASES FOR OUR LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Guava leaves\n-Ewe kaju- cashew leaves\n-Ewe Iru - locust beans leaves\n-Ewe Orogbo - bitter kola leaves\nPREPARATION\nShade-dry the leaves.\nPound them separately.\nThen we will combine the powder together.\nWe will add some of the powder to the feeds of\nour livestocks."},{"id":"livestock-24","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":24,"title":"OGUN ARA FUN NKAN OSIN","subtitle":"(MEDICINE TO TREAT AND PREVENT SKIN PROBLEMS IN ANIMAL LIVESTOCK)","preview":"MEDICINE TO TREAT AND PREVENT SKIN PROBLEMS IN ANIMAL LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Material needed:\n-Ewe koriko oba- Lemongrass\n-Ewe ada- Lophira lanceolata leaves\n-Ewe idi odan- Terminalia glaucescens\n-Epo Pupa - Palm oil\n-Ororo Agbon - Coconut oil\nPREPARATION\nDry the leaves and pound them finely.\nWe will pour the paste in coconut oil and leave\nit for 3 day.\nWe will then use the oil to rub the body of our\nlivestocks"},{"id":"livestock-25","source":"livestock","sourceName":"OGUN IDAGBASOKE NKAN OSIN","number":25,"title":"OGUN AABO AARUN ATI IKU NKAN OSIN","subtitle":"(CHARM TO PREVENT DEATH AND DISEASES OF LIVESTOCK)","preview":"CHARM TO PREVENT DEATH AND DISEASES OF LIVESTOCK · OGUN IDAGBASOKE NKAN OSIN","restricted":false,"content":"Materials needed:\n-Efun - white chalk\n-Osun - Camwood\n-Owo Eyo - Cowrie shells\n-Owu Funfun - White cotton\n-Omi alagbede - blacksmith water\n-Ikoko Amo Kekere - Small clay pot\n-edun ara- thunderstone\nPREPARATION\nPlace the edun ara inside the clay pot.\nAdd the cowrie shells.\nPlace a small piece of Efun and Osun inside.\nWrap a little white cotton around the mouth of\nthe pot.\nAdd in the blacksmith water.\nClose the pot securely.\nKeep it at a protected location near the livestock\ncompound where neither people nor animals\nwill disturb it."},{"id":"awise-1","source":"awise","sourceName":"OOGUN AWISE","number":1,"title":"OOGUN AWISE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO MAKE ALL YOUR WORDS COME THROUGH)"},{"id":"awise-2","source":"awise","sourceName":"OOGUN AWISE","number":2,"title":"OOGUN AWISE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO MAKE ALL YOUR WORDS COME THROUGH)"},{"id":"awise-3","source":"awise","sourceName":"OOGUN AWISE","number":3,"title":"OOGUN AFOHUNSE","subtitle":"(CHARM TO MAKE ALL YOUR UTTERANCES BECOME REALITY)","preview":"CHARM TO MAKE ALL YOUR UTTERANCES BECOME REALITY · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO MAKE ALL YOUR UTTERANCES BECOME REALITY)"},{"id":"awise-4","source":"awise","sourceName":"OOGUN AWISE","number":4,"title":"OOGUN AWISE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-the tail of okete\n-irawo ile leaves\n-jeminiho leaves\n-7 seeds of ataare\nWe will pound all the materials together and we\nwill put it into cotton wool and then we will\nwrap the cotton wool with a peice of red cloth\nfrom an egungun costume. Then we will tie it\ntogether with black and white thread. Then we\nwill soap this in the sap of oro agogo for 3 days\nthen we will dry it under the shade of the house.\nThen we will make a skin pouch for it. We will\nput this to the corner of the mouth while\nspeaking."},{"id":"awise-5","source":"awise","sourceName":"OOGUN AWISE","number":5,"title":"OOGUN AFOOGBA","subtitle":"(TALK AND DO)","preview":"TALK AND DO · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-the bone of fox\n-1 big oka head\n-3 pepper\n-1 ataare\nWe will burn all the materials together and we\nwill grind it to powder, then we will pour the\npowder in original wild honey. Then we will\nmix everything together in a white ceramic with\ncover. Then we will cover it for 7 days before\nwe lick time to time."},{"id":"awise-6","source":"awise","sourceName":"OOGUN AWISE","number":6,"title":"OOGUN APAASE","subtitle":"(COMMANDING SPELL)","preview":"COMMANDING SPELL · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (COMMANDING SPELL)"},{"id":"awise-7","source":"awise","sourceName":"OOGUN AWISE","number":7,"title":"OOGUN AWISE ASOBA","subtitle":"(CHARM TO MAKE ALL YOUR STATEMENTS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR STATEMENTS COME THROUGH · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-fresh dog tongue\n-fresh okete tongue\n-the tail of okete\n-the teeth of oka\n-the tail of oka\n-the ase of oka\n-the tail of scorpion\n-the tail of chameleon\n-abamoda leaves\n-akerejupon root\n-1 ataare\nWe will burn the materials together. Then we\nwill grind\nit to powder, we will pour it in a gourd and we\nwill kill 3\nmale lizards for the gourd. We will go bury the\nlizards. Then we will pour the powder on the\nleft palm and we will lick it from time to time.\nThis medicine is very useful for babalawo, woli\nor alfas. If you use it and a client come to see\nyou, if you tell them they will ave accident they\nwill have it, you will be able to use your words\nto predict what next will happen to them."},{"id":"awise-8","source":"awise","sourceName":"OOGUN AWISE","number":8,"title":"OOGUN ASORIBE","subtitle":"(CHARM TO MANIFEST ALL COMMANDS FOR BABALAWOS, ONISEGUN AND LIKES)","preview":"CHARM TO MANIFEST ALL COMMANDS FOR BABALAWOS, ONISEGUN AND LIKES · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-a little bit of palm oil\n-201 seeds of akese wool\n-unperforated leaves of akese 201\n-unripe ata ijosin 201\n-the head of a chameleon\n-the tail of the chameleon\n-the legs\n-3 bitter kola\n-3 kolanut with 4 lobes\n-awo ijimere\nWe will put the materials in the pot and we will\nput 1 oko ataare in it. Then we will burn them\ntogether and we will grind it to powder. In the\nmidnight, we will rub the palm oil on the body\nand we will squeeze two paps in a plate and we\nwill call the ofore on the powder:\nI become akese because it is the akese wishes that\ncome to pass in the midst of wools,\nI become ijimere, because it is the wish of ijimere\nthat comes to paass in the midst of the animals,\nWhen a pepper hurts someone they will never\nlisten to any other things,\nIt is the wish of alagemo that the heavenly orisha\nlisten to,\nIt is the wishes of okete that the ground listen to,\nSango doesnt refuse the wishes of bitter kola,\nNo orisha refuses the voice of kolanut,\nI become orisha from today on,\nWhatever i say should become ase.\nThen we will use the left hand to squeeze the\npap and pour the powder in it, then we will also\nuse the left hand to drink up the pap. Then we\nwill go and sleep without washing the palmoil.\nWhen we wake up we will wash away the palm\noil on the body.\nDo not eat okro again after doing the medicine."},{"id":"awise-9","source":"awise","sourceName":"OOGUN AWISE","number":9,"title":"OOGUN ASE INU","subtitle":"(CHARM FOR INNER COMMAND)","preview":"CHARM FOR INNER COMMAND · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-1 oka head with ase\n-ere snake head with ase\n-1 monamona head with ase\n-fresh akese leaves\n-seeds of akese\n-root of akese\n-awo iji mere\n-root of ina leaves\n-root of esisi leaves\n-eera insects\n-1 ataare\nWe will burn the materials together at night.\nWe will then grind it to powder and pour it in\nijamo gourd.\nWe can use this medicine in two ways:\n1\nst way: we will use the charm in the night with\nalcohol schnapp every 7 days till it is finished.\n2\nnd way: we will buy 3 tongues of sheep and we\nwill use it to cook the powder all at once.\nWe will pray on it."},{"id":"awise-10","source":"awise","sourceName":"OOGUN AWISE","number":10,"title":"OOGUN AWISE EPE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO MAKE ALL YOUR WORDS COME THROUGH)"},{"id":"awise-11","source":"awise","sourceName":"OOGUN AWISE","number":11,"title":"OOGUN MAYEHUN ETO GBIGBA","subtitle":"(DO NOT REFUSE MY VOICE CHARM USED TO COLLECT OUR RIGHT AND PROPERTIES OR MONEY FROM SOMEONE)","preview":"DO NOT REFUSE MY VOICE CHARM USED TO COLLECT OUR RIGHT AND PROPERTIES OR MONEY FROM SOMEONE · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-7 seeds of ataare\n-1 leaf of lime tree\nWe will go to a lime tree in the morning before\ntalking to anybody, then we will look for any of\nits leaves and we will use the mouth to pluck\none of it, and we will put it in the corner of our\nmouth till we get home, then we will remove it\nand we will put the 7 seeds of ataare on it and\nwe will pound them together. Then we will use\nblack soap to pack them together. We will put\nthe soap in a small horn and we will tie a red\ncloth on it. We will use the tip of the tongue to\ntouch it and we will say the following,\nWhatever the hand plucks can fall,\nWhatever the leg plucks can fall,\nWhatever the mouth plucks cannever fall,\nI command ..... the son of .... to give me my ....\nWithout any resistance.\nThen we wll go speak to them face to face or on\nphone, when they hear our voice they cant\nrestrict."},{"id":"awise-12","source":"awise","sourceName":"OOGUN AWISE","number":12,"title":"OOGUN OLUGBOHUN AJAGBOHUN","subtitle":"(CHARM TO MAKE ALL YOUR WISHES AND WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WISHES AND WORDS COME THROUGH · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO MAKE ALL YOUR WISHES AND WORDS COME THROUGH)"},{"id":"awise-13","source":"awise","sourceName":"OOGUN AWISE","number":13,"title":"OOGUN AFOSE APASE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO MAKE ALL YOUR WORDS COME THROUGH)"},{"id":"awise-14","source":"awise","sourceName":"OOGUN AWISE","number":14,"title":"OOGUN OLUGBOHUN AGBOOJO","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO MAKE ALL YOUR WORDS COME THROUGH)"},{"id":"awise-15","source":"awise","sourceName":"OOGUN AWISE","number":15,"title":"OOGUN AWIMAYEUN","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-chameleon\n-red ata ijosin\n-menstrual cloth of a woman\n-1 tongue of a cow\nWe will pound the materials together, but as we\nwill grind it our leg must not touch the floor.\nThen we will mix it together with the soap that\nwill fit the horn of a cow. Then we will put the\nsoap in it and we will put 3 oko oka on it and we\nwill cover it with red piece of cloth and we will\ncover it in a claypot for 9 days. After the 9th day\nwe will remove the red cloth and we will use\nthe tip of the tongue to touch it and we will start\nusing it for all we want. It is a multipurpose."},{"id":"awise-16","source":"awise","sourceName":"OOGUN AWISE","number":16,"title":"OOGUN IFOWO AJIWO AJEEGUN","subtitle":"","preview":"Traditional knowledge document · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-grass from a grave\n-we will pluck a leaf from the left hand side\n-we will pluck a leaf from the right hand side\n-alupaida leaves\n-1 chameleon\nWe will pound all the materials together with\nblack soap and we will pack the soap in a white\ncontainer with cover and we will use it to wash\nthe hand before we use any medicines. We will\ncan also give it to our client to use to wash the\nhand before they use any of the medicine we\ngive to them."},{"id":"awise-17","source":"awise","sourceName":"OOGUN AWISE","number":17,"title":"OOGUN ASE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME TO PASS)","preview":"CHARM TO MAKE ALL YOUR WORDS COME TO PASS · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-ram horn\n-bitter leaves 9/7\n-3 bitter kola\n-black soap\nWe will pound all the materials together and we\nwill pound it with black soap and we will make\nsure the soap is enough to fit the horn, we will\nthen pack it in the horn and we will leave it for\n7 days. After the ninth day it has become potent.\nWe will not use the mouth to touch it, we will\njust breath on it 3 times and we will say what\nwe want to happen."},{"id":"awise-18","source":"awise","sourceName":"OOGUN AWISE","number":18,"title":"OOGUN AWISE AFOSE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-7 cobra head\n-yanrin leaves with roots\n-1 ataare\nWe willl get isaasun and we will put the snake\nhead in it and we will put the leaves on it with\nroots with the ataare. Then we will burn them\ntogether and we will grind it to powder, and we\nwill mix it together with black soap and we will\nget agogo and we will put the soap in it. But\nbefore we put the soap we will start beating the\nagogo for a minute, then we will put the soap in\nit. Then we will put brass needle, iron needle\nand silver needle on it. Then we will tie red\npiece of cloth on it. To use it we will take the\nneedles one by one and we will say what we\nwant to happen and we will put it back in it."},{"id":"awise-19","source":"awise","sourceName":"OOGUN AWISE","number":19,"title":"OOGUN AWISE ALASE","subtitle":"(CHARM TO MAKE ALL YOUR WORDS COME THROUGH)","preview":"CHARM TO MAKE ALL YOUR WORDS COME THROUGH · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-the tail of chameleon 9\n-the tail of okete 1\n-river toad (small)\n-gun powder\n-oko oka 1\nWe will grind all the materials together with\nblack soap and we will pack it inside horn. Then\nwe will put the oka teeth on the soap. Then we\nwill use the tongue to touch the soap and we\nSAY ALL WE WANT to happen to someone. It\nwill come to pass. We will lick palm oil after\nsaying it to neutralize the effect and potency of\nthe charm."},{"id":"awise-20","source":"awise","sourceName":"OOGUN AWISE","number":20,"title":"OOGUN ASE AGBETO","subtitle":"(CHARM TO COLLECT THINGS YOU NEED)","preview":"CHARM TO COLLECT THINGS YOU NEED · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (CHARM TO COLLECT THINGS YOU NEED)"},{"id":"awise-21","source":"awise","sourceName":"OOGUN AWISE","number":21,"title":"OOGUN AFOSE AGBOOJO","subtitle":"(COMMAND TONE)","preview":"COMMAND TONE · OOGUN AWISE","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (COMMAND TONE)"},{"id":"awise-22","source":"awise","sourceName":"OOGUN AWISE","number":22,"title":"OOGUN TI OMO FIN JA FAFA","subtitle":"(TO MAKE A CHILD SHARP AND INTELLIGENT)","preview":"TO MAKE A CHILD SHARP AND INTELLIGENT · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-broom tips\n-1 ataare\nWe will burn the broom tips together with the\nataare, and we will grind it to powder. We will\npour it in original wild honey and we will give\nthe child to lick morning and night."},{"id":"awise-23","source":"awise","sourceName":"OOGUN AWISE","number":23,"title":"OOGUN TI OMO FIN JA FAFA","subtitle":"(TO MAKE A CHILD SHARP AND INTELLIGENT)","preview":"TO MAKE A CHILD SHARP AND INTELLIGENT · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-1 kolanut with 3 lobes\n-3 seeds of ataare\n-iyeye leaves\nWe will split the kolanut into 3, then we will put\none kolanut and 1 ataare on each leaves, the\nchild will eat one while lying down, another one\nwhile sitting, and another one while standing\nup. And the child will drink coconut water on it."},{"id":"awise-24","source":"awise","sourceName":"OOGUN AWISE","number":24,"title":"OOGUN TI OMO FIN JA FAFA","subtitle":"(TO MAKE A CHILD SHARP AND INTELLIGENT)","preview":"TO MAKE A CHILD SHARP AND INTELLIGENT · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-3 beans cake\n-3 kuluso\n-3 iyeye leaves\nThen we will open the beanscake and we will\nput the materials in each of the beans cake and\nthe child will eat one while lying down, another\none while sitting, and another one while\nstanding up. And the child will drink coconut\nwater on it."},{"id":"awise-25","source":"awise","sourceName":"OOGUN AWISE","number":25,"title":"OOGUN TI OMO FIN JA FAFA","subtitle":"(TO MAKE A CHILD SHARP AND INTELLIGENT)","preview":"TO MAKE A CHILD SHARP AND INTELLIGENT · OOGUN AWISE","restricted":false,"content":"Materials needed:\n-oniyemiye leaves\n-akoko leaves\n-adun leaves\n-3 bitterkola.\nWe will burn these materials together and the\nchild will take the powder with coconut water."},{"id":"baba-1","source":"baba","sourceName":"OOGUN BABA OGUN","number":1,"title":"AKABA","subtitle":"","preview":"Traditional knowledge document · OOGUN BABA OGUN","restricted":false,"content":"A complete formula remains unverified.\nThe description located mentions two prepared\nsticks and string but does not identify the wood\nor explain how the sticks are prepared."},{"id":"baba-2","source":"baba","sourceName":"OOGUN BABA OGUN","number":2,"title":"AGADAGODO","subtitle":"(PADLOCK CHARM)","preview":"PADLOCK CHARM · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ileke itun — itun beads\n- Ileke Ifa — Ifa beads\n- Ewe ina pupa\n- Ewe ina funfun\n- Eggshell\n- Ipanumo abo — unopened young abo leaves\n- Ipanumo abafe — unopened young abafe\nleaves\n- Cotton wool\n- Black thread\n- White thread\n- A padlock\n- White animal skin — species not specified\nPREPARATION\nWe will burn the beads, leaves and eggshell\ntogether.\nWe will wrap the resulting material in cotton\nwool.\nWe will bind the packet to the back of the\npadlock with black and white thread.\nWe will cover the packet with the white skin.\nUSAGE\nThe recorded ritual involves reciting its\nassociated invocation and closing the padlock.\nQuantities are not specified. The skin\nidentification remains incomplete."},{"id":"baba-3","source":"baba","sourceName":"OOGUN BABA OGUN","number":3,"title":"AJIDEWE — GBEGI VARIANT","subtitle":"(TRADITIONAL REJUVENATION BATH)","preview":"TRADITIONAL REJUVENATION BATH · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe gbegi — Eleusine indica leaves\n- Ose dudu — black soap\nPREPARATION\nWe will grind the leaves and mix them\nthoroughly into the black soap.\nUSAGE\nWe will use the prepared soap for bathing daily.\nThe publication provides no ingredient\nquantities."},{"id":"baba-4","source":"baba","sourceName":"OOGUN BABA OGUN","number":4,"title":"IRIRAN","subtitle":"(POISON-DETECTION CHARM)","preview":"POISON-DETECTION CHARM · OOGUN BABA OGUN","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (POISON-DETECTION CHARM)"},{"id":"baba-5","source":"baba","sourceName":"OOGUN BABA OGUN","number":5,"title":"ISUJU","subtitle":"(TRADITIONAL CONCEALMENT AMULET)","preview":"TRADITIONAL CONCEALMENT AMULET · OOGUN BABA OGUN","restricted":false,"content":"Materials recorded:\n- Ewe ijokun\n- Ewe ibo\n- One whole atare fruit\n- Awo ijimere — monkey skin\n- One whole aparo — partridge\n- A rooster\n- Obi — kola nut\n- Orogbo — bitter kola\n- Clothing belonging to the intended wearer\n- A small ado gourd\n- Waji — blue cloth\n- Leather for the outer covering\nPREPARATION AND USAGE\nThe recorded sequence includes an Osanyin\noffering using the rooster, kola, bitter kola and\nclothing.\nThe leaves, atare, monkey skin and partridge\nare burned together.\nIrete Obara is marked using the preparation,\nwith an accompanying invocation.\nAt night, the material is placed inside the small\ngourd, covered with blue cloth and wrapped in\nleather with its inner surface facing outward.\nThe gourd is worn around the neck.\nThis records an invisibility belief; it does not\nmake a person invisible.\nSeveral quantities and the outer leather species\nare unspecified."},{"id":"baba-6","source":"baba","sourceName":"OOGUN BABA OGUN","number":6,"title":"MADARIKAN","subtitle":"","preview":"Traditional knowledge document · OOGUN BABA OGUN","restricted":false,"content":"A complete, safely usable alternative remains\nunverified.\nAn ethnobotanical publication mentions dried\nbanana leaves and latex alongside unspecified\nadditional ingredients.\nThat is not a complete materials list.\nOther located versions involve swallowing\nburned mixtures or rubbing preparations into\ncuts; I cannot recommend those instructions."},{"id":"baba-7","source":"baba","sourceName":"OOGUN BABA OGUN","number":7,"title":"EBE-AGBA","subtitle":"(TRADITIONAL FAVOUR CHARM)","preview":"TRADITIONAL FAVOUR CHARM · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe oorungo, also written oloorungo\n- Eedu oju aro — charcoal from a hearth\n- Soap\nPREPARATION\nWe will pound the leaves and charcoal together.\nWe will mix the pounded materials thoroughly\ninto the soap.\nUSAGE\nThe recorded use is bathing with the\npreparation; no particular bathing time is\nspecified.\nIngredient quantities and a reliable botanical\nidentification for oorungo are not supplied."},{"id":"baba-8","source":"baba","sourceName":"OOGUN BABA OGUN","number":8,"title":"AGBELEPOTA","subtitle":"(TRADITIONAL PROTECTIVE HORN CHARM)","preview":"TRADITIONAL PROTECTIVE HORN CHARM · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- A cow horn\n- One large snail\n- A little salt\n- Ose dudu — black soap\nPREPARATION\nWe will grind the snail into the black soap.\nWe will incorporate the salt.\nWe will pack the mixture into the cow horn.\nUSAGE\nWe will keep the prepared horn concealed.\nThe recorded ritual includes an accompanying\nspoken invocation.\nThis preparation is not described as a drink or\nbathing soap."},{"id":"baba-9","source":"baba","sourceName":"OOGUN BABA OGUN","number":9,"title":"ISOYE — ATARE, MAIZE AND HONEY VARIANT","subtitle":"(TRADITIONAL MEMORY PREPARATION)","preview":"TRADITIONAL MEMORY PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials recorded:\n- Atare seeds — Aframomum melegueta\n- Maize grains — Zea mays\n- Honey\nPREPARATION\nWe will grind the atare seeds and maize grains\ninto powder.\nWe will mix the powder with honey.\nUSAGE\nThe traditional administration recorded is\nlicking the mixture.\nThe publication gives no proportions, serving\nsize or frequency, so a usable dosing instruction\ncannot be supplied."},{"id":"baba-10","source":"baba","sourceName":"OOGUN BABA OGUN","number":10,"title":"AWURE — JEKAJERA","subtitle":"(TRADITIONAL PROSPERITY RITUAL)","preview":"TRADITIONAL PROSPERITY RITUAL · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe gbure — Talinum triangulare leaves\n- Water\n- Iyerosun — Ifa divination powder\n- A container\nPREPARATION\nWe will place the gbure leaves in water inside\nthe container.\nWe will mark Ose Otura in the iyerosun.\nWe will add that powder to the water.\nWe will place the container beneath the roof,\nnear the ceiling.\nUSAGE\nWe will recite the following each morning:\n“Gbure\nEti mi gbo re\nGbure\nEti mi gbo re.”\nThe liquid is not instructed to be swallowed or\nused for bathing.\nIngredient quantities are not specified."},{"id":"baba-11","source":"baba","sourceName":"OOGUN BABA OGUN","number":11,"title":"AFEERI","subtitle":"(TRADITIONAL DISAPPEARANCE AMULET)","preview":"TRADITIONAL DISAPPEARANCE AMULET · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Iye agbe — 1 feather\n- Iye aluko — 1 feather\n- Iye ayan — identification unclear in the\navailable text\n- Ikode — 1 red parrot-tail feather\n- Ekuro inu ogan — 1 palm kernel taken from a\ntermite mound\n- Ado ijamo — a small gourd\n- Black leather\nPREPARATION\nWe will burn the feathers and palm kernel\ntogether.\nWe will put the resulting material inside the\ngourd.\nWe will have the gourd enclosed in black\nleather.\nUSAGE\nThe recorded use is wearing the gourd around\nthe neck, accompanied by an invocation.\nThe “iye ayan” ingredient needs clarification\nbefore this can count as a fully identified\nformula."},{"id":"baba-12","source":"baba","sourceName":"OOGUN BABA OGUN","number":12,"title":"OKIGBE — ONIFUNPA","subtitle":"(TRADITIONAL ARM AMULET)","preview":"TRADITIONAL ARM AMULET · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe ajeobale — 16 leaves\n- Atare — 16 seeds\n- Black thread\n- White thread\n- Black leather\nPREPARATION\nWe will arrange the leaves and pepper seeds\ntogether, placing one seed with each leaf.\nWe will bind the arrangement with black and\nwhite thread.\nWe will enclose it in black leather as an arm\namulet.\nUSAGE\nWe will wear the finished amulet on the arm as\na traditional ritual object."},{"id":"baba-13","source":"baba","sourceName":"OOGUN BABA OGUN","number":13,"title":"AYOTA","subtitle":"(TRADITIONAL BULLET-REMOVAL CLAIM)","preview":"TRADITIONAL BULLET-REMOVAL CLAIM · OOGUN BABA OGUN","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (TRADITIONAL BULLET-REMOVAL CLAIM)"},{"id":"baba-14","source":"baba","sourceName":"OOGUN BABA OGUN","number":14,"title":"OOGUN IFE — IFERAN ENIYAN","subtitle":"(TRADITIONAL SOAP FOR GENERAL AFFECTION)","preview":"TRADITIONAL SOAP FOR GENERAL AFFECTION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe eti ologbo — Ipomoea hederifolia leaves\n- Ewe jiwinni — Acalypha ciliata leaves\n- Ose dudu — black soap\nPREPARATION\nWe will pound both leaves together.\nWe will mix them thoroughly into the black\nsoap.\nUSAGE\nWe will use the preparation for bathing, with\nthe accompanying invocation.\nNo quantities or bathing schedule are specified.\nThis variant concerns general affection, rather\nthan a named romantic partner."},{"id":"baba-15","source":"baba","sourceName":"OOGUN BABA OGUN","number":15,"title":"OOGUN IJAKADI","subtitle":"(TRADITIONAL WRESTLING RINGS)","preview":"TRADITIONAL WRESTLING RINGS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ose dudu — black soap\n- Alubosa elewe — leafy onion\n- Hair from the back of an entirely black cat\n- Oruka ogun — 2 iron rings\n- Atare — 7 seeds\n- A piece of rag\nPREPARATION\nWe will pound the soap, onion, cat hair and\npepper seeds together.\nWe will shape the mixture into a ball and place\nboth rings inside it.\nWe will wrap the ball in the rag.\nWe will place the wrapped preparation inside a\ncrevice in an earthen wall.\nWe will leave it there for seven days.\nWe will retrieve it after the seventh day.\nUSAGE\nThe rings are then designated for use as\nwrestling charms.\nThe text gives no further wearing instructions."},{"id":"baba-16","source":"baba","sourceName":"OOGUN BABA OGUN","number":16,"title":"ALUWO","subtitle":"(TRADITIONAL KNOCKDOWN CHARM)","preview":"TRADITIONAL KNOCKDOWN CHARM · OOGUN BABA OGUN","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (TRADITIONAL KNOCKDOWN CHARM)"},{"id":"baba-17","source":"baba","sourceName":"OOGUN BABA OGUN","number":17,"title":"OFO AYAJO","subtitle":"(INCANTATORY WORKING)","preview":"INCANTATORY WORKING · OOGUN BABA OGUN","restricted":false,"content":"This is a category of spoken ritual, not one fixed\npreparation.\nMaterials needed:\n- Depend on the particular ayajo and its\npurpose.\nPREPARATION AND USAGE\nA specific, documented ayajo must be selected\nbefore its materials and procedure can be listed.\nThere is no single complete formula attached to\nthis general title."},{"id":"baba-18","source":"baba","sourceName":"OOGUN BABA OGUN","number":18,"title":"KANAKO","subtitle":"(TRADITIONAL JOURNEY-SHORTENING CHARM)","preview":"TRADITIONAL JOURNEY-SHORTENING CHARM · OOGUN BABA OGUN","restricted":false,"content":"A complete formula was not verified.\nThe dedicated research paper on Kanako and\nEgbe explicitly reports that the participants did\nnot disclose complete ingredient lists.\nNo materials or preparation have been invented\nto fill that gap."},{"id":"baba-19","source":"baba","sourceName":"OOGUN BABA OGUN","number":19,"title":"EGBE","subtitle":"(TRADITIONAL ESCAPE / RELOCATION CHARM)","preview":"TRADITIONAL ESCAPE / RELOCATION CHARM · OOGUN BABA OGUN","restricted":false,"content":"Materials mentioned in the research:\n- A leaf lifted by a whirlwind — species\nwithheld\n- Water\n- A bush fowl is mentioned separately for one\nvariant\nPREPARATION AND USAGE\nThe complete preparation was not disclosed.\nThese mentions do not establish one combined\nrecipe and should not be treated as a full\nmaterials list."},{"id":"baba-20","source":"baba","sourceName":"OOGUN BABA OGUN","number":20,"title":"AYETA","subtitle":"(TRADITIONAL PROTECTIVE POCKET AMULET)","preview":"TRADITIONAL PROTECTIVE POCKET AMULET · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe sawerepepe\n- Ewe etiponla\n- Ewe koko\n- Ewe opolo\n- Ewe gbegi\n- Ewe egele\n- Ewe ajilekege\n- White cotton thread\n- Black cotton thread\nPREPARATION\nWe will burn sawerepepe, etiponla, koko and\nopolo together.\nWe will mark Iwori Oyeku using the\npreparation and recite the associated\ninvocation.\nWe will burn gbegi, egele and ajilekege into\nblack powder.\nWe will recite the invocation over this second\npreparation.\nWe will bind the prepared material with white\nand black cotton thread.\nUSAGE\nWe will keep the finished packet in a pocket as a\ntraditional ritual object.\nQuantities are not specified. The text does not\nclearly explain whether the two burned\npreparations are combined."},{"id":"baba-21","source":"baba","sourceName":"OOGUN BABA OGUN","number":21,"title":"EYONU (TRADITIONAL FAVOUR / ACCEPTANCE","subtitle":"","preview":"Traditional knowledge document · OOGUN BABA OGUN","restricted":false,"content":"PREPARATION)\nMaterials needed:\n- Ewe rerinkomi\n- Ori — shea butter\nPREPARATION\nWe will pound the rerinkomi leaves.\nWe will mix the pounded leaves thoroughly into\nthe shea butter.\nUSAGE\nWe will apply the mixture around the navel.\nNo quantities or application schedule are\nspecified."},{"id":"baba-22","source":"baba","sourceName":"OOGUN BABA OGUN","number":22,"title":"OOGUN AJE — OWO NINI VARIANT","subtitle":"(TRADITIONAL WEALTH-SEEKING SOAP)","preview":"TRADITIONAL WEALTH-SEEKING SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe disoke\n- Ewe wonjo\n- Ose dudu — black soap\nPREPARATION\nWe will pound both leaves together with the\nblack soap.\nUSAGE\nWe will use the prepared soap for bathing,\naccompanied by the formula’s invocation.\nNo quantities or bathing schedule are specified."},{"id":"baba-23","source":"baba","sourceName":"OOGUN BABA OGUN","number":23,"title":"APORO","subtitle":"(TRADITIONAL ANTIDOTE PREPARATIONS)","preview":"TRADITIONAL ANTIDOTE PREPARATIONS · OOGUN BABA OGUN","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (TRADITIONAL ANTIDOTE PREPARATIONS)"},{"id":"baba-24","source":"baba","sourceName":"OOGUN BABA OGUN","number":24,"title":"MAGUN","subtitle":"(HARMFUL CHARM ASSOCIATED WITH SEXUAL INFIDELITY)","preview":"HARMFUL CHARM ASSOCIATED WITH SEXUAL INFIDELITY · OOGUN BABA OGUN","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (HARMFUL CHARM ASSOCIATED WITH SEXUAL INFIDELITY)"},{"id":"baba-25","source":"baba","sourceName":"OOGUN BABA OGUN","number":25,"title":"AFOSE","subtitle":"(TRADITIONAL SPOKEN-AUTHORITY HORN)","preview":"TRADITIONAL SPOKEN-AUTHORITY HORN · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Egbo obi abata — kola-tree root\n- Egbo orogbo — bitter-kola root\n- Egbo akerejupon\n- Egbo ajeobale\n- Edun ara\n- Ose dudu — black soap\n- Iwo agbonrin — antelope horn\n- Ikoti ide\n- Ikoti baba\n- Aso egun — masquerade cloth\nPREPARATION\nWe will pound the roots and edun ara with the\nblack soap.\nWe will pack the preparation into the horn.\nWe will insert the ikoti ide and ikoti baba into\nthe top.\nWe will wrap the horn with the masquerade\ncloth.\nUSAGE\nThis particular entry does not specify its\nactivation procedure.\nThe two metal implements are retained under\ntheir Yoruba names because their exact\nidentification is unresolved."},{"id":"baba-26","source":"baba","sourceName":"OOGUN BABA OGUN","number":26,"title":"MAYEHUN (TRADITIONAL “REFUSE ME NOT”","subtitle":"","preview":"Traditional knowledge document · OOGUN BABA OGUN","restricted":false,"content":"PREPARATION)\nMaterials recorded:\n- Ewe amoniseni\n- Ewe jeminiho\n- Oyin igan — wild honey\nPREPARATION\nThe recorded method is pounding the two\nleaves together and mixing them with honey.\nUSAGE\nThe recorded administration is licking the\nmixture before making a request.\nReliable botanical identities, quantities and a\nsafe dose were not established, so this is\ndocumentation, not an instruction to swallow it."},{"id":"baba-27","source":"baba","sourceName":"OOGUN BABA OGUN","number":27,"title":"OLUGBOHUN","subtitle":"(TRADITIONAL COMMAND-RELATED HORN)","preview":"TRADITIONAL COMMAND-RELATED HORN · OOGUN BABA OGUN","restricted":false,"content":"Materials recorded:\n- Ewe ina pupa\n- Ewe esisi\n- Ewe aaragba\n- A crab\n- A chameleon\n- A frog\n- Ose dudu — black soap\n- A cow horn\n- Red cloth\nPREPARATION AND USAGE\nThe located version packs the animals into the\nhorn beneath a mixture of pounded leaves and\nsoap, covers it with red cloth and leaves it for\nseven days.\nIts administration involves tongue contact with\nthe contents.\nI cannot recommend licking this mixture of\nanimal material, irritating plants and soap."},{"id":"baba-28","source":"baba","sourceName":"OOGUN BABA OGUN","number":28,"title":"GBETUGBETU","subtitle":"(TRADITIONAL COWRIE CHARM)","preview":"TRADITIONAL COWRIE CHARM · OOGUN BABA OGUN","restricted":false,"content":"Materials recorded:\n- Owo eyo — 10 cowries without drilled holes\n- Ewe daiko\n- Ewe alupaida — 7 leaves\n- Ewe orira\n- Odidi atare — 1 whole fruit\n- A chick described as having strayed from its\nmother\n- Plastic wrapping\n- Cord\n- Aso ipa ode — the specified hunter’s cloth\nPREPARATION\nThe leaves and atare are ground together.\nThe preparation and cowries are placed inside\nthe chick’s opened body, with some mixture\nbeneath and some above the cowries.\nThe package is closed, wrapped in plastic and\ntied against water entry.\nIt is submerged in flowing water for seven days.\nThe cowries are then retrieved and placed in a\nsmall bag sewn from the hunter’s cloth.\nUSAGE\nThe recorded ritual involves holding one cowrie\nwhile speaking the invocation, then returning it\nto the bag.\nThe cowrie is not thrown away.\nQuantities for daiko and orira are unspecified."},{"id":"baba-29","source":"baba","sourceName":"OOGUN BABA OGUN","number":29,"title":"ABAMODA","subtitle":"(INCANTATION-ACTIVATED WORKING)","preview":"INCANTATION-ACTIVATED WORKING · OOGUN BABA OGUN","restricted":false,"content":"A complete, reliably identified formula remains\nunverified.\nAbamoda as a working must not be confused\nwith ewe abamoda as a plant ingredient.\nFinding a soap containing that leaf does not\nestablish the formula for this entry."},{"id":"baba-30","source":"baba","sourceName":"OOGUN BABA OGUN","number":30,"title":"AWURE ORIIRE — ORIRE VARIANT","subtitle":"(TRADITIONAL GOOD-FORTUNE SOAP)","preview":"TRADITIONAL GOOD-FORTUNE SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Ewe asawawa\n- Ewe ojuusaju\n- Ewe omini\n- Ewe orijin\n- Ose dudu — black soap\nPREPARATION\nWe will pound the four leaves together.\nWe will mix them thoroughly into the black\nsoap.\nUSAGE\nWe will use the preparation for bathing,\naccompanied by the formula’s invocation.\nNo ingredient quantities or bathing schedule\nare specified."},{"id":"baba-32","source":"baba","sourceName":"OOGUN BABA OGUN","number":32,"title":"IMUNLE AWON AGBA","subtitle":"(EBE / IMULE BATHING-SOAP VARIANT)","preview":"EBE / IMULE BATHING-SOAP VARIANT · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n- Alubosa elewe — leafy onion\n- Ose dudu — black soap\n- One fresh chicken egg\n- Igba olomori — a lidded calabash\nPREPARATION\nWe will pound the leafy onion thoroughly.\nWe will mix it into the black soap.\nWe will make a small opening in the egg,\nkeeping the rest of the shell intact.\nWe will pour the egg contents into the soap and\npound everything together.\nWe will transfer the preparation into the lidded\ncalabash.\nWe will make a small depression in the soap.\nWe will position the empty eggshell in that\ndepression, with its opening facing downward.\nUSAGE\nThe recorded use is bathing with the soap at\nany chosen time.\nThe publication gives no quantities for the\nonion or soap and no storage duration."},{"id":"baba-41","source":"baba","sourceName":"OOGUN BABA OGUN","number":41,"title":"APAJI","subtitle":"(PROTECTION / APAJI WORKING)","preview":"PROTECTION / APAJI WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Oruka baba - 4 rings\n-Ewe apada tutu - 9\n-Korofo eyin adie - eggshells\n-Aaye oga - 1\n-Ado ijamo\n***PREPARATION***\nThe source combines the four rings with the\nmaterials associated with the hen/chick\npreparation.\nThe eggshells, Aaye Oga and Ewe Apada are\nburnt together and ground thoroughly into a\nfine powder.\nThe powder is kept inside an Ado Ijamo, while\nthe rings are retained separately.\n***USAGE***\nThe source directs that a little of the powder be\ntaken with Eko Tutu and one of the prepared\nrings be worn on the middle finger of the left\nhand.\nSource:\nIwe Asiri Ogun Isenbaye, Volume 1 - \"Oruka\nEgbe Ati Apaji.\"\nTraditional claim only; it should not be tested\nagainst weapons or physical injury."},{"id":"baba-42","source":"baba","sourceName":"OOGUN BABA OGUN","number":42,"title":"OHUN ASASI","subtitle":"(ASASI WORKING)","preview":"ASASI WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-The complete materials under this exact title\nwere not recovered from the sources checked.\n***PREPARATION***\nThe contents list confirms OHUN ASASI as a\nnamed working, but the publicly accessible text\ndoes not disclose its complete preparation.\n***USAGE***\nNot stated in the accessible source.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI have deliberately not substituted an ordinary\nOogun Asasi formula because that would be a\ndifferent preparation."},{"id":"baba-43","source":"baba","sourceName":"OOGUN BABA OGUN","number":43,"title":"OOGUN EMI GIGUN","subtitle":"(LONG LIFE / LONGEVITY WORKING)","preview":"LONG LIFE / LONGEVITY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Eyinolobe tutu - fresh Eyinolobe leaves\n-Isu - yam\n-Obe Ila - okra soup\n***PREPARATION***\nWe will take a good quantity of fresh Ewe\nEyinolobe.\nWe will combine it with Isu and pound them\ntogether into Iyan.\nThe source describes dividing the prepared Iyan\nsymbolically according to the number of years\nbeing sought.\n***USAGE***\nWe will eat the prepared Iyan with Obe Ila.\nThe source associates the preparation with the\nsaying:\n\"Eyin eyin lolobe nso sii eyin eyin.\"\nSource:\nPractitioner collection indexed under \"Emi\nGigun Todaju.\"\nNOTE:\nThis is a traditional longevity belief and not a\nmedical method for extending lifespan."},{"id":"baba-44","source":"baba","sourceName":"OOGUN BABA OGUN","number":44,"title":"ERO EGBO ADAJINA","subtitle":"(REMEDY FOR A STUBBORN / LONG-STANDING WOUND)","preview":"REMEDY FOR A STUBBORN / LONG-STANDING WOUND · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Orogbo\n-Ekute ti a ba ri ni oju ona ti a ko mo nkan to pa\n- a dead mouse found outdoors of unknown\ncause\n***PREPARATION***\nThe source says the Ekute should be dried.\nIt is then ground together with Epo Orogbo until\nthoroughly combined.\n***USAGE***\nThe source directs that the preparation should\nbe applied to the wound.\nSource:\nA separate Egbo Adajina practitioner collection.\nIMPORTANT:\nThis is a newly located variant, not the Egungun\nErin / Egungun Malu / Karahun Igbin formula\npreviously used.\nDo not put material from a dead wild rodent on\nan open wound because of serious infection\nrisk."},{"id":"baba-45","source":"baba","sourceName":"OOGUN BABA OGUN","number":45,"title":"ERO ASASI","subtitle":"(NEUTRALISING ASASI)","preview":"NEUTRALISING ASASI · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Kileefimise\n-Oko Atare - 1\n***PREPARATION***\nWe will combine Ewe Kileefimise with one Oko\nAtare.\nWe will grind the two materials together\nthoroughly until they become a fine\npreparation.\n***USAGE***\nThe traditional source applies the preparation\nthrough seven marks around the chest area.\nSource:\nPractitioner compilation, No. 159 - \"Ogun Ero\nAsasi.\"\nNOTE:\nThis is a different formula from the earlier Asasi\npreparation containing Aworoosi and other\nmaterials.\nScarification carries infection and blood-borne\ndisease risks and should not be treated as\nmedically safe."},{"id":"baba-46","source":"baba","sourceName":"OOGUN BABA OGUN","number":46,"title":"AFORAN","subtitle":"(AFARAN / CASE OR TROUBLE REMOVAL WORKING)","preview":"AFARAN / CASE OR TROUBLE REMOVAL WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Iyerosun\n-Opon Ifa\n-Ose - soap\n***PREPARATION***\nWe will spread Iyerosun on the Opon Ifa.\nWe will mark Otura Meji on the Iyerosun.\nThe source's Ofo is spoken over the preparation.\nWe will then combine the prepared Iyerosun\nwith Ose and mix it thoroughly.\n***USAGE***\nWe will use the prepared Ose to bathe at night.\nSource:\nOgo Emi collection - \"Aforan Todaju.\"\nNOTE:\nThis is not the earlier Aforan formula using Ori\nOka, Awo Ekun and Akara Elepo."},{"id":"baba-47","source":"baba","sourceName":"OOGUN BABA OGUN","number":47,"title":"ISORA ASITA IBON","subtitle":"(PROTECTION AGAINST GUNSHOT)","preview":"PROTECTION AGAINST GUNSHOT · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Complete materials under this exact title were\nnot recovered.\n***PREPARATION***\nThe practitioner contents list records ISORA\nASITA IBON as a separate preparation, but its\ncomplete formula is not reproduced in the\naccessible text.\n***USAGE***\nThe title attributes it to traditional protection\nagainst gunshot.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI have not replaced it with Ayeta Ibon, Tira Ibon\nor another gun-protection formula because\nthose are separate named workings.\nTraditional gun-protection claims should never\nbe tested with a firearm."},{"id":"baba-48","source":"baba","sourceName":"OOGUN BABA OGUN","number":48,"title":"ORUKA AJANGBARA","subtitle":"(AJANGBARA RING)","preview":"AJANGBARA RING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Complete materials under this exact title were\nnot recovered.\n***PREPARATION***\nORUKA AJANGBARA TODAJU appears as a\ndistinct heading in the source, but the accessible\ncontents page does not reveal the formula itself.\n***USAGE***\nThe title identifies the preparation as an Oruka\nor ring-based Ajangbara working.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI found other Ajangbara and protective-ring\nworkings, but I have not inserted them here\nbecause they are not specifically titled ORUKA\nAJANGBARA."},{"id":"baba-49","source":"baba","sourceName":"OOGUN BABA OGUN","number":49,"title":"OWO ASITA IBON","subtitle":"(HAND WORKING AGAINST GUNSHOT)","preview":"HAND WORKING AGAINST GUNSHOT · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Complete materials under this exact title were\nnot recovered.\n***PREPARATION***\nThe source lists OWO ASITA IBON\nindependently but does not expose its complete\nrecipe in the publicly indexed material.\n***USAGE***\nBy its source title, it is a hand-based traditional\ngun-protection working.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI have not substituted Ayeta Ibon, Ogun Ibon or\nTira Ibon for it because those have different\nnames and preparations."},{"id":"baba-50","source":"baba","sourceName":"OOGUN BABA OGUN","number":50,"title":"OOGUN ILAYA","subtitle":"(COURAGE / FEAR-INDUCING WORKING)","preview":"COURAGE / FEAR-INDUCING WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe gathered from the right side of a farm\n-Ewe gathered from the left side of the farm\n-Koriko from the place where an Aparo flew\nfrom\n-Odidi Atare - 1\n-Ewe igi ti afefe ba ya lule - leaf/foliage brought\ndown by the wind\n***PREPARATION***\nWe will gather leaves from both the right and\nleft sides of the farm.\nWe will collect the Koriko from the particular\nspot where the Aparo flew from.\nWe will add one whole Atare and the leaf\nbrought down by the wind.\nWe will burn all the listed materials together.\nWe will grind the burnt preparation thoroughly\ninto powder.\n***USAGE***\nThe source says the powder is taken with Eko\nTutu while its Ofo is spoken.\nSource:\nPractitioner collection - \"Ogun Ilaya Todaju.\"\nNOTE:\nDo not ingest unidentified plant material or\nburnt plant ash merely because a traditional\ndocument prescribes it."},{"id":"baba-51","source":"baba","sourceName":"OOGUN BABA OGUN","number":51,"title":"ATUMO","subtitle":"(ATUMO / OVERCOMING OPPOSITION)","preview":"ATUMO / OVERCOMING OPPOSITION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ako Alangba - 6\n-Abo Alangba - 6\n-Opo lo Aaye - 6\n-Ewe Ewuro oojo\n-Eepo Obo - small quantity\n-Ose Dudu - black soap\n-Ike Funfun - white container\n***PREPARATION***\nWe will combine the listed materials and pound\nthem together thoroughly.\nWe will mix the preparation properly with Ose\nDudu.\nWe will put the prepared soap inside an Ike\nFunfun.\nWe will close the container and leave it\nundisturbed for six days.\n***USAGE***\nOn the seventh day, the preparation becomes a\nbathing soap according to the source.\nIt is traditionally used at night.\nSource:\nIda Awon Ogboni collection - \"Atumo Ati Isegun\nOta Todaju.\""},{"id":"baba-52","source":"baba","sourceName":"OOGUN BABA OGUN","number":52,"title":"AKIRA","subtitle":"(AKIRA)","preview":"AKIRA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nAKIRA is independently listed as a named\nworking in the source catalogue, but the\npublicly indexed source does not disclose its\ningredients or method.\n***USAGE***\nNot disclosed in the accessible source.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nAlso independently listed as \"AKIRA\" in another\npublicly indexed practitioner catalogue.\nNOTE:\nI did not rename Akoya, Akira-related\nprotection, or another working to fill this gap."},{"id":"baba-53","source":"baba","sourceName":"OOGUN BABA OGUN","number":53,"title":"IFUNPA AKOYA","subtitle":"(AKOYA ARM-BAND)","preview":"AKOYA ARM-BAND · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Adigbonoku - 1\n-Omo Atare - 1\n-Owu Tutu\n-Owu Dudu\n-Owu Funfun\n-Oje Igi Emi\n-Awo Dudu for making the Ifunpa\n***PREPARATION***\nWe will open the Adigbonoku and place one\nOmo Atare inside its cavity.\nWe will close it again.\nWe will wrap the preparation first with Owu\nTutu.\nWe will bind it firmly with Owu Dudu and Owu\nFunfun.\nThe source then treats it with Oje from Igi Emi.\nWe will finally sew the prepared object inside\nAwo Dudu to form an Ifunpa.\n***USAGE***\nThe source directs that the Ifunpa be worn on\nthe arm.\nSource:\nOgbon practitioner collection - \"Ogun Akoya\nAgberoku Todaju.\"\nNOTE:\nThe source attaches violent supernatural claims\nto this preparation. Those claims are traditional\nassertions and must not be tested by provoking\nviolence or using weapons."},{"id":"baba-54","source":"baba","sourceName":"OOGUN BABA OGUN","number":54,"title":"SIGIDI ISORA","subtitle":"(PROTECTIVE SIGIDI)","preview":"PROTECTIVE SIGIDI · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Isu Koko\n-Ori Oka - 1\n-Obi Alawe - 2\n-Erupe Amo ti Alakan wa sita\n-Oti Ibile\n-Small Sigidi figure\n-Owo Eyo - 1\n***PREPARATION***\nWe will take Isu Koko, Ori Oka and two Obi\nAlawe.\nWe will combine them with the Erupe Amo\nfrom an Alakan opening.\nWe will grind the materials together\nthoroughly.\nWe will mix the preparation with Oti Ibile until\nit can be moulded.\nWe will use it in preparing a small Sigidi.\nOne Owo Eyo is incorporated into the\npreparation as described by the source.\nThe Sigidi is then allowed to dry thoroughly.\n***USAGE***\nThe source keeps the prepared Sigidi inside a\nlarge covered container.\nWhen traditionally used, the Sigidi is brought\nout and ritually addressed.\nSource:\n7.pdf - \"Sigidi Agbara Isora.\"\nNOTE:\nNo claim of physical invulnerability should be\ntreated as real protection from weapons or\ninjury."},{"id":"baba-55","source":"baba","sourceName":"OOGUN BABA OGUN","number":55,"title":"AKOYA","subtitle":"(AKOYA ARM WORKING)","preview":"AKOYA ARM WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Okete oojo - 1\n-Pelepele\n-Omo Atare - 9\n-Awo Dudu\n-Materials for making an Ifunpa\n***PREPARATION***\nWe will cover the tail area of the Okete with\nPelepele as directed by the source.\nWe will place nine Omo Atare inside the\nprepared portion.\nWe will allow the preparation to dry\ncompletely.\nWhen it has dried, we will sew it securely inside\nAwo Dudu to form an Ifunpa.\n***USAGE***\nThe source directs that the Ifunpa be tied to the\narm.\nSource:\nIwe Asiri Odumosu Akoni - \"Akoya Todaju\nBiiku.\"\nNOTE:\nThe source attributes harmful effects against an\nattacker to it. I am recording the documented\ntraditional working, not presenting those claims\nas factual."},{"id":"baba-56","source":"baba","sourceName":"OOGUN BABA OGUN","number":56,"title":"BANTE GBETUGBETU","subtitle":"(GBETUGBETU WAIST-BAND)","preview":"GBETUGBETU WAIST-BAND · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-The exact BANTE GBETUGBETU materials were\nnot recovered under that full title.\nA closely related GBETUGBETU source gives:\n-Awo Ori Monamona\n-Ewe Keyinsorun\n-Isu Esuru\n-Isu Baara\n-Kuluso - 7\n-Owu for Ikobere\n***PREPARATION***\nThe related Gbetugbetu source directs that the\nlisted materials be ground thoroughly together.\nThe preparation is wrapped as an Ikobere.\nIt is then traditionally conditioned for seven\ndays.\n***USAGE***\nThe related source identifies Gbetugbetu as a\npreparation connected with speech and\ninfluence.\nSource:\nOgo Emi collection - \"Gbetugbetu.\"\nIMPORTANT:\nThe source catalogue separately names BANTE\nGBETUGBETU, but I have not found evidence\nproving that the above Gbetugbetu recipe is the\nexact Bante version."},{"id":"baba-57","source":"baba","sourceName":"OOGUN BABA OGUN","number":57,"title":"ASO AGBARA / ASO OGUN","subtitle":"(POWER / PROTECTIVE CLOTH)","preview":"POWER / PROTECTIVE CLOTH · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eso Ako Ibepe OR Ewe Bara\n-Omi - small quantity\n-Handkerchief or cloth pieces\n***PREPARATION***\nWe will grind Eso Ako Ibepe or Ewe Bara with a\nsmall quantity of water.\nWe will place the cloth or handkerchief pieces\ninto the preparation.\nThe source leaves the cloth in the preparation\nfor seven days.\nAfter the seventh day, we will remove and keep\nthe cloth.\n***USAGE***\nThe cloth is carried or worn traditionally as Aso\nAgbara.\nSource:\n7.pdf - cloth-based Ayeta/Aso Agbara passage.\nNOTE:\nThe source associates it with protection against\nweapons. A cloth cannot be relied upon as real\nballistic or weapon protection."},{"id":"baba-58","source":"baba","sourceName":"OOGUN BABA OGUN","number":58,"title":"SIGIDI APE","subtitle":"(CALLING / SUMMONING SIGIDI)","preview":"CALLING / SUMMONING SIGIDI · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials under the title SIGIDI APE were\nnot recovered.\n***PREPARATION***\nThe practitioner catalogue clearly lists SIGIDI\nAPE as its own working.\nHowever, the accessible contents page does not\nprovide its construction or activation formula.\n***USAGE***\nNot disclosed in the accessible source.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI found separate \"Ofo Ape\" and other Sigidi\npreparations, but I have not merged them here\nbecause that would create a formula that the\nsource itself does not give."},{"id":"baba-59","source":"baba","sourceName":"OOGUN BABA OGUN","number":59,"title":"EYONU TI MUN OTA DI ORE","subtitle":"(FAVOUR / TURNING HOSTILITY INTO FRIENDSHIP)","preview":"FAVOUR / TURNING HOSTILITY INTO FRIENDSHIP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact formula under this title was not\nrecovered.\nA separate source gives the closely matching:\nAWURE TIN MU OTA DI ORE\nMaterials:\n-Ikode - 3\n-Oloyunbere - 3\n-Odidi Atare - 3\n-Ose Dudu\n***PREPARATION***\nWe will combine the three Ikode, three\nOloyunbere and three Odidi Atare.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly.\nPart of the preparation is combined with Ose\nDudu.\n***USAGE***\nThe source uses the soap preparation for\nbathing.\nSource:\nIwulo Ewe collection - \"Awure Tin Mu Ota Di\nOre.\"\nIMPORTANT:\nThis is a separately sourced same-purpose\nformula.\nI am not claiming it is textually identical to the\ncatalogue's \"Eyonu Ti Mun Ota Di Ore.\""},{"id":"baba-60","source":"baba","sourceName":"OOGUN BABA OGUN","number":60,"title":"EYONU ABEGBEPE","subtitle":"(ABEGBEPE FAVOUR WORKING)","preview":"ABEGBEPE FAVOUR WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nEYONU ABEGBEPE is explicitly listed as a\nseparate named preparation in the practitioner\ncatalogue.\nThe publicly accessible catalogue does not\nexpose its actual formula.\n***USAGE***\nNot disclosed in the accessible source.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI have not filled this entry with a generic Eyonu\nformula because Eyonu Abegbepe is presented\nby the source as its own named working."},{"id":"baba-61","source":"baba","sourceName":"OOGUN BABA OGUN","number":61,"title":"EYONU IDARIJIN","subtitle":"(FAVOUR / FORGIVENESS / APPEASEMENT)","preview":"FAVOUR / FORGIVENESS / APPEASEMENT · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Orijin oojo - 16\n-Ewe Ewuro oojo - 16\n-Ewe Lapalapa Funfun oojo - 16\n-Eru Alamo - 16\n-Epo Obo - small quantity\n-Igi Nla - small quantity\n-Ose Dudu - black soap\n-Fitila Oloju 16\n***PREPARATION***\nWe will combine Ewe Orijin, Ewe Ewuro, Ewe\nLapalapa Funfun, Eru Alamo, Epo Obo and Igi\nNla.\nWe will pound all the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nDudu.\nWe will put the prepared soap inside Fitila\nOloju 16.\nAfter the preparation has been placed inside,\nthe bottom of the Fitila must not touch the\nground.\n***USAGE***\nWe will use the prepared soap for bathing in the\nmorning and at night.\nSource:\nOgbon practitioner collection — \"Ebe Awon\nAgba (Idarijin Awon Eleye).\""},{"id":"baba-62","source":"baba","sourceName":"OOGUN BABA OGUN","number":62,"title":"IRIN AJO EMI","subtitle":"(SPIRITUAL JOURNEY)","preview":"SPIRITUAL JOURNEY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-The complete source preparation involves an\nAdo, ritual bird/animal materials, cloth\nconnected with the dead, and a coffin/grave\nsetting.\n***PREPARATION***\nThe full formula I located requires opening a\ngrave, disturbing a coffin and handling\nmaterials associated with human remains.\nI am therefore not reproducing the grave￾opening or corpse-handling procedure.\n***USAGE***\nThe source specifically describes the prepared\nAdo as being used for what it calls \"Irin Ajo\nEmi.\"\nSource:\nIwe Asiri Odumosu Akoni — Irin Ajo Emi / Irin\nAjo Agbara Aiye section.\nNOTE:\nThis entry is documented as a traditional\nspiritual claim. I have not replaced it with Ebo\nIrin Ajo or the travelling charms previously sent\nto you."},{"id":"baba-63","source":"baba","sourceName":"OOGUN BABA OGUN","number":63,"title":"ATONA TI A FI SE IWADI","subtitle":"(ATONA FOR INVESTIGATION / ENQUIRY)","preview":"ATONA FOR INVESTIGATION / ENQUIRY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Obi Alawe - 3\n-Abere\n-Owu Dudu\n-Owu Funfun\n-Atare\n-Oti\n-Okun\n***PREPARATION***\nWe will insert the Abere through the Obi Alawe\nfrom the upper part to the bottom.\nWe will wrap the lower part of the Abere with\nOwu Dudu and Owu Funfun.\nWe will also bind the Obi and Abere securely\nwith the black and white threads.\nWe will attach an Okun to the prepared Abere.\nAtare is traditionally used while the preparation\nis being addressed.\nA little Oti is finally poured on the preparation.\n***USAGE***\nWe will hold the Okun attached to the Abere\nwithout deliberately moving the hand.\nWe will ask the particular question we want\ninvestigated.\nThe source interprets the movement or turning\nof the preparation as the answer.\nSource:\nOgo Emi collection — \"ATONA.\""},{"id":"baba-64","source":"baba","sourceName":"OOGUN BABA OGUN","number":64,"title":"ATONA ELEPONMETA","subtitle":"(ELEPONMETA ATONA)","preview":"ELEPONMETA ATONA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nATONA ELEPONMETA is listed independently in\nthe original practitioner contents list.\nI found several preparations involving a plant\ncalled Ewe Elepon Meta, but none could be\nverified as this specific ATONA ELEPONMETA\nformula.\n***USAGE***\nNot disclosed in the accessible source.\nSource:\nAsiri Ewe Ati Egbo, Volume One — contents\nentry.\nNOTE:\nI have not inserted an ordinary Atona or an Ewe\nElepon Meta medicine here because that would\nbe a different preparation."},{"id":"baba-65","source":"baba","sourceName":"OOGUN BABA OGUN","number":65,"title":"ISEGUN OTA","subtitle":"(VICTORY / OVERCOMING ENEMIES)","preview":"VICTORY / OVERCOMING ENEMIES · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Ako Emido\n-Eepo Igba\n-Ewe Enu Opire\n-Iyerosun / Ifa preparation\n-Eko Tutu\n***PREPARATION***\nWe will collect Ewe Ako Emido, Eepo Igba and\nEwe Enu Opire.\nWe will burn the three materials together.\nWe will grind the burnt materials thoroughly\ninto powder.\nThe source associates the preparation with\nEjiogbe and traditionally marks the Odu with\nthe preparation.\n***USAGE***\nThe historical source directs that a small\nquantity of the preparation be taken with Eko\nTutu.\nSource:\nVerger-derived ethnobotanical collection —\n\"Isegun Ota, Ejiogbe, No. 314 (1568).\"\nBotanical identifications given by the academic\nsource:\n-Ako Emido — Manilkara obovata\n-Igba — Lagenaria siceraria\n-Enu Opire — Euphorbia lateriflora\nNOTE:\nThis is different from the Isegun Ota / Aseta,\nAgunmona, Kasan, Elulu and other formulas\npreviously sent to you. The source's hostile Ofo\nis not reproduced here."},{"id":"baba-66","source":"baba","sourceName":"OOGUN BABA OGUN","number":66,"title":"EYONU OLOJO MESAN","subtitle":"(NINE-DAY EYONU)","preview":"NINE-DAY EYONU · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nThe title EYONU OLOJO MESAN is specifically\nlisted as an independent preparation in the\npractitioner catalogue, but its actual recipe was\nnot exposed in the accessible contents material.\n***USAGE***\nNot disclosed.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI found several Eyonu formulas containing nine\nitems or nine-day procedures, but I cannot\nprove that any of them is the exact EYONU\nOLOJO MESAN. I have therefore not substituted\none."},{"id":"baba-67","source":"baba","sourceName":"OOGUN BABA OGUN","number":67,"title":"ASEJE AWURE","subtitle":"(EDIBLE AWURE PREPARATION)","preview":"EDIBLE AWURE PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Igbayinrin\n-Iru\n-Ata Ijosin - 9\n-Iyere - 9\n-Eja Efolo Wewe - 9\n-Epo\n-Iyo\n-Isasun Tuntun\n-Omi Agbon\n***PREPARATION***\nWe will grind Ewe Igbayinrin, Iru, nine Ata\nIjosin and nine Iyere separately.\nWe will combine the ground materials inside a\nnew Isasun.\nWe will use the preparation to cook nine Eja\nEfolo Wewe with Epo and Iyo.\n***USAGE***\nThe traditional source says the Aseje is eaten\nand Omi Agbon is taken afterward.\nIt specifies taking it before the normal meal.\nSource:\nAsiri practitioner compilation — \"ASEJE\nAWURE.\""},{"id":"baba-68","source":"baba","sourceName":"OOGUN BABA OGUN","number":68,"title":"OSHOLE AJESINU","subtitle":"(OSHOLE AJESINU)","preview":"OSHOLE AJESINU · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nOSHOLE AJESINU appears as its own named\nworking in the original contents list.\nThe complete formula under this precise title\nwas not recovered from the accessible\ndocuments.\n***USAGE***\nNot disclosed.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI have not substituted an ordinary Oshole,\nOshole Owo, Oshole Asiri Bibo or Oshole Ajesara\nformula because those are separate workings."},{"id":"baba-69","source":"baba","sourceName":"OOGUN BABA OGUN","number":69,"title":"OWO JIJI","subtitle":"(OWO JIJI)","preview":"OWO JIJI · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nThe source lists OWO JIJI independently.\nAnother indexed contents list expands the title\nas \"Owo Jiji Ti Owo Koba Je Ogun Mo,\" but the\nfull ingredients and preparation were not\nrecovered.\n***USAGE***\nNot disclosed in the accessible source.\nSource:\nAsiri Ewe Ati Egbo, Volume One.\nNOTE:\nI have not replaced this with Awure Owo, Owo\nRespect, Owo Asina or another money\npreparation."},{"id":"baba-70","source":"baba","sourceName":"OOGUN BABA OGUN","number":70,"title":"AKESU","subtitle":"(AKESU)","preview":"AKESU · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eja Aro Aye - 1\n-Oga Aye - 1\n-Liili Aye - 1\n-Adaripon Aye - 1\n-Odidi Atare - 1\n-Epo Obo - small quantity\n-Akanse Ado Ide\n-Apoti Igi Iroko with cover\n-Ikoko Tuntun\n***PREPARATION***\nWe will combine Eja Aro, Oga, Liili, Adaripon,\none whole Atare and a small quantity of Epo\nObo.\nWe will burn the materials together inside a\nnew pot.\nWe will grind the burnt preparation thoroughly.\nWe will put the resulting preparation inside an\nAkanse Ado Ide.\nThe prepared Ado is then kept inside a covered\nIroko wooden box.\nThe source instructs that the bottom of the Ado\nshould not touch the ground.\n***USAGE***\nThe practitioner source associates this Akesu\nvariant with a money-working ritual involving\na new currency note placed with the prepared\nAdo.\nSource:\nOpele practitioner collection — \"AKESU ADAJO.\"\nNOTE:\nThis is specifically an AKESU-labelled formula\nfrom another collection; I am not claiming it is\nword-for-word identical to the hidden AKESU\nrecipe in Asiri Ewe Ati Egbo."},{"id":"baba-71","source":"baba","sourceName":"OOGUN BABA OGUN","number":71,"title":"IPESE TI A FI NGBA ASO AWON AGBA","subtitle":"(OFFERING / WORKING CONNECTED WITH AWON AGBA)","preview":"OFFERING / WORKING CONNECTED WITH AWON AGBA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eso Ibepe ti Eye jeku lori igi\n-Awo Ipese\n***PREPARATION***\nWe will collect Eso Ibepe that a bird has eaten\nfrom while it is still on the tree.\nWe will dry it properly.\nWe will burn it and grind it thoroughly into\npowder.\n***USAGE***\nWe will sprinkle a small quantity of the powder\nover the Ipese prepared for Awon Agba.\nSource:\nAgbara Tapa collection - \"Ipese Ebe Awon\nAgba.\"\nNOTE:\nThe original catalogue separately names \"Ipese\nTi A Fi Ngba Aso Awon Agba.\" Its exact hidden\nrecipe was not publicly recovered, so this is a\nseparately documented Ipese Awon Agba\npreparation and not falsely presented as the\nidentical formula."},{"id":"baba-72","source":"baba","sourceName":"OOGUN BABA OGUN","number":72,"title":"AWURE OBINRIN TABI OKUNRIN","subtitle":"(AWURE FOR ATTRACTION / FAVOUR)","preview":"AWURE FOR ATTRACTION / FAVOUR · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Sawerepepe oojo\n-Ori Alangba oojo\n-Odidi Atare - 1\n-Ewe Ewuro oojo\n-Ose\n-Lofinda Miss Paris\n-Ike Funfun\n***PREPARATION***\nWe will combine Ewe Sawerepepe, Ori Alangba,\none Odidi Atare and Ewe Ewuro.\nWe will pound the listed materials thoroughly.\nWe will mix them properly with Ose.\nWe will add Lofinda Miss Paris and mix\neverything thoroughly.\nWe will put the prepared soap inside an Ike\nFunfun.\n***USAGE***\nThe source directs that the preparation be used\nfor washing the head.\nSource:\nNew Asiri Aye practitioner collection - \"Awure\nObinrin.\"\nNOTE:\nThis is a newly sourced Awure variant and not\nthe previous Awure formulas already sent."},{"id":"baba-73","source":"baba","sourceName":"OOGUN BABA OGUN","number":73,"title":"ASEJE ADERA","subtitle":"(ADERA / RELEASE ASEJE)","preview":"ADERA / RELEASE ASEJE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Orijin\n-Eja Aro Gbigbe\n-Omunu Ewe Akoko - 9\n-Ata Ijosin - 9\n***PREPARATION***\nFIRST STAGE:\nWe will prepare Ewe Orijin together with Eja\nAro Gbigbe.\nWe will prepare enough for three consecutive\ndays.\nSECOND STAGE:\nAfter completing the first three days, we will\ncollect nine Omunu Ewe Akoko and nine Ata\nIjosin.\nWe will prepare another Eja Aro Gbigbe with\nthese materials.\nThis second preparation will also be made for\nthree days.\n***USAGE***\nThe first Aseje is traditionally eaten for three\ndays with prayer for Adéra and Itusile.\nAfterward, the second Akoko preparation is\neaten for another three days according to the\nsource.\nSource:\nIwe Agba Osugbo, Volume 1 - \"Aseje Adera Ati\nItusile.\""},{"id":"baba-74","source":"baba","sourceName":"OOGUN BABA OGUN","number":74,"title":"IPARA ATI OSE ITAJA","subtitle":"(SHOP / BUSINESS FAVOUR PREPARATION)","preview":"SHOP / BUSINESS FAVOUR PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Aduro Sasa\n-Ori Olongbo to ni irun\n-Ewe Orijin\n-Ori Olufa\n-Ase Oka\n-Ose Dudu\n-Ike Funfun\n***PREPARATION***\nWe will combine Ewe Aduro Sasa, Ori Olongbo,\nEwe Orijin, Ori Olufa and Ase Oka.\nWe will pound all the materials thoroughly.\nWe will mix the preparation properly with Ose\nDudu.\nWe will put the prepared soap inside an Ike\nFunfun.\n***USAGE***\nWe will take a little of the soap and bathe with it\nin the morning.\nThe source specifically associates the\npreparation with shop/business attraction and\nAworo Omo Ise.\nSource:\nIwe Agba Osugbo - \"Awure Itaja Ati Aworo Omo\nIse.\"\nNOTE:\nThe catalogue title is \"Ipara Ati Ose Itaja.\" This is\na separately documented shop-soap preparation\nof the same class, not a reconstructed hidden\nrecipe."},{"id":"baba-75","source":"baba","sourceName":"OOGUN BABA OGUN","number":75,"title":"OSE KI ONISE OWO LE MA RISE","subtitle":"(SOAP FOR STEADY BUSINESS / WORK)","preview":"SOAP FOR STEADY BUSINESS / WORK · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Ewuro oojo\n-Ewe Ajeobale oojo\n-Eepo Obo\n-Oronro Ako Maalu\n-Ose\n-Pooko Agbon\n***PREPARATION***\nWe will combine Ewe Ewuro, Ewe Ajeobale and\nEepo Obo.\nWe will pound the materials thoroughly\ntogether.\nWe will mix them properly with Ose.\nWe will add Oronro Ako Maalu as directed in\nthe source.\nWe will put the prepared soap inside a Pooko\nAgbon.\nWe will keep it for three days.\n***USAGE***\nAfter the third day, we will begin using the soap\nfor bathing.\nThe source attributes it to meeting helpers and\nimproving one's work/business circumstances.\nSource:\n7.pdf - \"Ose Ti A Fi N Pade Oluranlowo Gidi /\nAlaanu.\"\nNOTE:\nThe original source catalogue confirms the\nseparate title \"Ose Ki Onise Owo Le Ma Rise\nDada,\" but its exact formula was not publicly\nexposed. I have therefore identified this as a\nsame-purpose sourced preparation."},{"id":"baba-76","source":"baba","sourceName":"OOGUN BABA OGUN","number":76,"title":"IPARA EBE AWON AGBA","subtitle":"(BODY CREAM FOR EBE AWON AGBA)","preview":"BODY CREAM FOR EBE AWON AGBA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eepo Obo\n-Eepo Igi Nla\n-Ewe Rerinkomi\n-Ori OR Ipara OR Adi\n***PREPARATION***\nWe will combine Eepo Obo, Eepo Igi Nla and\nEwe Rerinkomi.\nWe will pound them together very thoroughly\nuntil the preparation becomes fine like powder.\nWe will dry the preparation properly.\nWe will burn the dried preparation.\nWe will grind the resulting material thoroughly.\nWe will mix it with Ori, Ipara or Adi.\n***USAGE***\nWe will use the prepared mixture as body\ncream.\nSource:\nPractitioner collection - \"Ipara Ebe Awon Agba.\""},{"id":"baba-77","source":"baba","sourceName":"OOGUN BABA OGUN","number":77,"title":"LOFINDA AWON AGBA","subtitle":"(PERFUME / FAVOUR PREPARATION)","preview":"PERFUME / FAVOUR PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Anu\n-Ewe Ola\n-Ewe Oriji\n-Ewe Aje\n-Lofinda of choice\n***PREPARATION***\nWe will dry Ewe Anu, Ewe Ola, Ewe Oriji and\nEwe Aje.\nWe will grind all the materials thoroughly\ntogether.\nWe will add the preparation into the Lofinda.\nWe will shake or mix it properly and keep it\nready for use.\n***USAGE***\nThe source directs that the prepared Lofinda be\napplied to the hands and body.\nSource:\nAgbara Tapa - \"Lofinda Anu.\"\nNOTE:\nThe catalogue specifically calls No. 77 \"Lofinda\nAwon Agba.\" The formula above is a separately\ndocumented Anu/Eyonu perfume preparation\nrather than an invented reconstruction of the\nunavailable exact recipe."},{"id":"baba-78","source":"baba","sourceName":"OOGUN BABA OGUN","number":78,"title":"EBU IPESE","subtitle":"(POWDER FOR IPESE)","preview":"POWDER FOR IPESE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eye Alapandede - 1\n-Odidi Atare - 1\n***PREPARATION***\nWe will combine one Eye Alapandede with one\nwhole Atare.\nWe will burn them together thoroughly.\nWe will grind the burnt materials into fine\npowder.\nWe will keep the powder dry for Ipese use.\n***USAGE***\nThe source uses the Ebu to accompany an Ipese\ncontaining:\n-Eko - 3\n-Orogbo - 3\n-Obi - 3\n-Epo\nA small quantity of the Ebu is added to or\nsprinkled over the Ipese.\nSource:\nNew Asiri Aye - \"Ebu Ipese.\""},{"id":"baba-79","source":"baba","sourceName":"OOGUN BABA OGUN","number":79,"title":"ETUTU AWON AGBA","subtitle":"(ETUTU FOR AWON AGBA)","preview":"ETUTU FOR AWON AGBA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Esuru Pupa\n-Ako Alangba\n-Iyerosun\n-Eko Elewe - 1\n***PREPARATION***\nWe will dry Esuru Pupa and Ako Alangba\nthoroughly.\nWe will grind them separately into fine powder.\nWe will combine the prepared materials with\nIyerosun.\nThe source then traditionally uses the\npreparation in connection with Ejiogbe.\n***USAGE***\nOne Eko Elewe is placed down.\nAfter the traditional prayers are completed, the\nprepared material is put on the Eko.\nThe source directs that the Etutu be carried to\nOrita Meta.\nSource:\nOgbon practitioner collection - \"Etutu Awon\nAgba.\""},{"id":"baba-80","source":"baba","sourceName":"OOGUN BABA OGUN","number":80,"title":"OOGUN EYONU AIYE","subtitle":"(GENERAL FAVOUR / EYONU AIYE)","preview":"GENERAL FAVOUR / EYONU AIYE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Odidi Opolo Gbigbe - 1\n-Epo Obo\n-Amunu Botuje Funfun\n-Eyin Togbo\n-Ose\n***PREPARATION***\nWe will combine one dried Opolo, Epo Obo,\nAmunu Botuje Funfun and Eyin Togbo.\nWe will pound all the materials together\nthoroughly.\nWe will mix the preparation properly with Ose.\n***USAGE***\nThe source directs that the prepared soap may\nbe used for bathing when needed.\nSource:\nNew Asiri Aye practitioner collection - \"Eyonu\nAye.\""},{"id":"baba-81","source":"baba","sourceName":"OOGUN BABA OGUN","number":81,"title":"OSE EYONU / ANU","subtitle":"(FAVOUR / MERCY SOAP)","preview":"FAVOUR / MERCY SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Ewuro oojo tikoluju\n-Adin\n-Oyin - honey\n-Ori\n-Epo Pupa\n-Ose Dudu - black soap\n***PREPARATION***\nWe will combine Ewe Ewuro, Adin, Oyin, Ori\nand Epo Pupa.\nWe will pound the materials together\nthoroughly.\nWe will mix the preparation properly with Ose\nDudu until everything is well incorporated.\n***USAGE***\nWe will use the prepared soap for bathing in the\nmorning.\nSource:\nPractitioner collection - \"Ose Eyonu.\"\nNOTE:\nThis is not the earlier Eyonu soap using Agogo\nIgun or the Ewe Rerinkomi preparation\npreviously sent."},{"id":"baba-82","source":"baba","sourceName":"OOGUN BABA OGUN","number":82,"title":"LOFINDA EYONU","subtitle":"(FAVOUR PERFUME)","preview":"FAVOUR PERFUME · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Omisinmisin Olokun\n-Omi Agbon - coconut water\n-Lofinda - perfume\n***PREPARATION***\nWe will collect Ewe Omisinmisin Olokun.\nWe will process the leaf with Omi Agbon as\nstated in the source.\nWe will put the prepared material into the\nLofinda.\nWe will mix the perfume thoroughly.\n***USAGE***\nWe will apply the prepared Lofinda to the body.\nSource:\nPractitioner compilation - \"Ogun Lofinda\nEyonu.\"\nNOTE:\nThis is a distinct Lofinda Eyonu formula and not\nthe perfume mixtures already used in earlier\nentries."},{"id":"baba-83","source":"baba","sourceName":"OOGUN BABA OGUN","number":83,"title":"OOGUN ANU","subtitle":"(MERCY / FAVOUR WORKING)","preview":"MERCY / FAVOUR WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eha Ide\n-Eha Oje\n-Eha Irin\n-Ado\n***PREPARATION***\nWe will combine Eha Ide, Eha Oje and Eha Irin.\nWe will grind the three materials together\nthoroughly.\nWe will put the preparation inside an Ado.\nWe will close the Ado securely.\n***USAGE***\nThe source directs that a little of the\npreparation be applied to the head before\nleaving the house in the morning.\nSource:\n7.pdf - \"Ogun Anu Todaju Gan.\"\nNOTE:\nI have retained the source material names\nexactly rather than guessing what \"Eha\" refers\nto."},{"id":"baba-84","source":"baba","sourceName":"OOGUN BABA OGUN","number":84,"title":"TURARI AWON AGBA","subtitle":"(INCENSE FOR AWON AGBA)","preview":"INCENSE FOR AWON AGBA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eru Alamo\n-Epo Obo\n-Ewe Ajeobale\n-Iginla\n***PREPARATION***\nWe will combine Eru Alamo, Epo Obo, Ewe\nAjeobale and Iginla.\nWe will pound all the materials thoroughly\ntogether.\nWe will spread the preparation out and allow it\nto dry properly.\n***USAGE***\nWe will burn a small quantity as Turari\nwhenever traditionally required.\nSource:\nOogun Yoruba - \"Turari Awon Agba.\""},{"id":"baba-85","source":"baba","sourceName":"OOGUN BABA OGUN","number":85,"title":"TURARI LILE AJE JINNA","subtitle":"(STRONG INCENSE FOR DRIVING AJE AWAY)","preview":"STRONG INCENSE FOR DRIVING AJE AWAY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eru Alamo\n-Epo Obo\n-Ata Ijosin\n***PREPARATION***\nWe will combine Eru Alamo, Epo Obo and Ata\nIjosin.\nWe will pound the materials thoroughly\ntogether until suitable for use as Turari.\n***USAGE***\nThe source directs that the preparation be\nburned as incense at night.\nSource:\nOogun Yoruba - \"Turari Lile Aje Jinna.\"\nNOTE:\nThis is recorded as a traditional spiritual￾protection working; the claimed supernatural\neffect is not independently verifiable."},{"id":"baba-86","source":"baba","sourceName":"OOGUN BABA OGUN","number":86,"title":"TURARI ASINA","subtitle":"(ASINA INCENSE)","preview":"ASINA INCENSE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Misinmisin Gogoro\n-Imi Ojo\n***PREPARATION***\nWe will collect Ewe Misinmisin Gogoro.\nWe will combine it with Imi Ojo.\nWe will pound the two materials together\nthoroughly until they form a suitable incense\npreparation.\n***USAGE***\nWe will burn the preparation as Turari.\nSource:\nOogun Yoruba - \"Turari Asina.\"\nNOTE:\nThis is different from the earlier Turari Asina\nformula using three types of Eku and three\nAtare."},{"id":"baba-87","source":"baba","sourceName":"OOGUN BABA OGUN","number":87,"title":"TURARI RIRISE","subtitle":"(INCENSE FOR FAVOUR / GETTING THINGS DONE)","preview":"INCENSE FOR FAVOUR / GETTING THINGS DONE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eru Alamo - plenty\n-Kerewu - plenty\n-Ikun Ojia - plenty\n-Imi Ojo - plenty\n***PREPARATION***\nWe will combine Eru Alamo, Kerewu, Ikun Ojia\nand Imi Ojo.\nWe will pound all the materials together very\nthoroughly until they become a fine incense\npreparation.\n***USAGE***\nThe source directs that the Turari may be\nburned whenever required.\nSource:\nOogun Yoruba - \"Turari Ririse Todaju Tabi\nAgbalagba Tiwon Dari Anu.\""},{"id":"baba-88","source":"baba","sourceName":"OOGUN BABA OGUN","number":88,"title":"TURARI FUN EMI KEMI","subtitle":"(INCENSE FOR REMOVING UNWANTED SPIRITUAL PRESENCE)","preview":"INCENSE FOR REMOVING UNWANTED SPIRITUAL PRESENCE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Imi Ojo\n***PREPARATION***\nWe will combine Epo Obo and Imi Ojo.\nWe will pound the two materials together\nthoroughly until they become suitable for\nTurari.\n***USAGE***\nWe will burn the prepared Turari in the\nmorning and at night according to the source.\nSource:\nOogun Yoruba - \"Turari Fun Emi Kemi.\"\nNOTE:\nThe source glosses this as a preparation for\nremoving an unwanted spiritual presence."},{"id":"baba-89","source":"baba","sourceName":"OOGUN BABA OGUN","number":89,"title":"TURARI ITAJA","subtitle":"(SHOP / BUSINESS INCENSE)","preview":"SHOP / BUSINESS INCENSE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Esinsin Funfun\n-Ewe Birana\n-Imi Ojo\n***PREPARATION***\nWe will combine Ewe Esinsin Funfun, Ewe\nBirana and Imi Ojo.\nWe will pound all the materials together\nthoroughly into an incense preparation.\n***USAGE***\nWe will burn the preparation as Turari in the\nshop.\nSource:\nOogun Yoruba - \"Turari Itaja.\"\nNOTE:\nA separate practitioner source also records\nanother Turari Itaja made from Ewe Eyinolobe\nand Imi Ojo Pupa, but I have not mixed the two\nformulas."},{"id":"baba-90","source":"baba","sourceName":"OOGUN BABA OGUN","number":90,"title":"TURARI TI ANFIN BA AJE WOYA IJA","subtitle":"(INCENSE ASSOCIATED WITH CONFRONTING AJE)","preview":"INCENSE ASSOCIATED WITH CONFRONTING AJE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Imi Ojo Pupa\n-Eru Alamo\n-Epo Obo\n-Asorin\n-Ewe Ajeobale\n-Ata Ijosin\n***PREPARATION***\nWe will combine Imi Ojo Pupa, Eru Alamo, Epo\nObo, Asorin, Ewe Ajeobale and Ata Ijosin.\nWe will pound all the listed materials\nthoroughly together until they become a fine\nincense preparation.\n***USAGE***\nThe source directs that a little of the\npreparation be put onto the fire or burning\npoint so that its smoke is released.\nSource:\nOogun Yoruba - \"Turari Ti Anfin Ba Aje Woya\nIja Todaju.\"\nNOTE:\nThis is presented only as a documented\ntraditional spiritual working, not as a factual\nmethod for harming or identifying another\nperson."},{"id":"baba-91","source":"baba","sourceName":"OOGUN BABA OGUN","number":91,"title":"TURARI ALUJONU","subtitle":"(ALUJONU INCENSE)","preview":"ALUJONU INCENSE · OOGUN BABA OGUN","restricted":true,"content":"CULTURAL DOCUMENTATION NOTICE\n\nThis source entry contains hazardous or harmful operational instructions.\n\nIts title, collection context and non-operational description are preserved here, but the step-by-step hazardous method is not published on the site.\n\nRecorded description: (ALUJONU INCENSE)"},{"id":"baba-92","source":"baba","sourceName":"OOGUN BABA OGUN","number":92,"title":"TURARI TI A FI YA OKO ORUN TABI AYA ORUN","subtitle":"(INCENSE FOR SEPARATING OKO ORUN / AYA ORUN)","preview":"INCENSE FOR SEPARATING OKO ORUN / AYA ORUN · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Aran Ope Gbigbe\n-Eru Alamo\n-Epo Obo\n-Ewe Rere\n***PREPARATION***\nWe will collect dried Aran Ope.\nWe will combine it with Eru Alamo, Epo Obo\nand Ewe Rere.\nWe will pound all the listed materials\nthoroughly together until they form the\ntraditional Turari preparation.\n***USAGE***\nThe source directs that the Turari be used inside\nthe sleeping area of the person concerned.\nIt is traditionally attributed to separating a\nperson from what the source calls Oko Orun or\nAya Orun.\nSource:\nOogun Yoruba - \"Turari Ti A Fi Ya Oko Orun\nTabi Aya Orun.\""},{"id":"baba-93","source":"baba","sourceName":"OOGUN BABA OGUN","number":93,"title":"OOGUN ATUDE","subtitle":"(ATUDE / RELEASE FROM OBSTRUCTION)","preview":"ATUDE / RELEASE FROM OBSTRUCTION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Ikun Ojia\n-Igi Nla\n-Ata Ijosin\n-Eru Alamo\n-Aidan\n-Ose Dudu\n***PREPARATION***\nWe will combine Epo Obo, Ikun Ojia, Igi Nla, Ata\nIjosin, Eru Alamo and Aidan.\nWe will pound all the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nDudu.\n***USAGE***\nWe will use the prepared soap for bathing at\nnight before going to sleep.\nSource:\nOogun Yoruba - \"Oogun Atude.\""},{"id":"baba-94","source":"baba","sourceName":"OOGUN BABA OGUN","number":94,"title":"ATUDE AWON AGBA","subtitle":"(ATUDE CONNECTED WITH AWON AGBA)","preview":"ATUDE CONNECTED WITH AWON AGBA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Ose Dudu\n-Omi for bathing\n-Epo Pupa\n***PREPARATION***\nWe will pound Epo Obo thoroughly into Ose\nDudu.\nWe will prepare the water to be used for\nbathing.\nWe will add a little Epo Pupa as described in the\nsource.\n***USAGE***\nThe source directs that Epo Pupa also be rubbed\nlightly on the body before using the prepared\nsoap and water to bathe.\nThe traditional intention is Atude connected\nwith Awon Agba.\nSource:\nOogun Yoruba - \"Atude Awon Agba.\""},{"id":"baba-95","source":"baba","sourceName":"OOGUN BABA OGUN","number":95,"title":"ATUDE ASINA","subtitle":"(ATUDE / OPENING BLOCKED WAYS)","preview":"ATUDE / OPENING BLOCKED WAYS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Aparo - 1\n-Eru Alamo - 7 portions\n-Epo Obo\n-Egbo Tude\n-Ose Dudu\n***PREPARATION***\nWe will combine Ori Aparo, Eru Alamo, Epo\nObo and Egbo Tude.\nWe will pound them thoroughly together.\nWe will mix the preparation with Ose Dudu.\nWe will divide the prepared soap into seven\nportions.\n***USAGE***\nThe source directs that all seven portions be\nused successively for bathing on one particular\nday.\nSource:\nOogun Yoruba - \"Atude Asina.\"\nNOTE:\nThis is different from the Asina/Atude formulas\nalready sent in previous batches."},{"id":"baba-96","source":"baba","sourceName":"OOGUN BABA OGUN","number":96,"title":"ATUDE ATI IDODO","subtitle":"(ATUDE AND REMOVAL OF IDODO / OBSTRUCTION)","preview":"ATUDE AND REMOVAL OF IDODO / OBSTRUCTION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Efun\n-Osun\n-Eedu\n-Ose Dudu\n***PREPARATION***\nWe will combine Efun and Osun.\nWe will add Eedu.\nWe will grind the three materials thoroughly\ntogether.\nWe will mix the resulting preparation properly\nwith Ose Dudu.\n***USAGE***\nWe will use the prepared soap for bathing\naccording to the source.\nSource:\nOogun Yoruba - \"Atude Ati Idodo.\"\nNOTE:\nThe source accompanies the mixing of Efun,\nOsun and Eedu with symbolic statements,\nwhich I have omitted as requested in your usual\nformula format."},{"id":"baba-97","source":"baba","sourceName":"OOGUN BABA OGUN","number":97,"title":"ITUWO AWON AGBA","subtitle":"(REMOVING / RELEASING AWON AGBA INFLUENCE)","preview":"REMOVING / RELEASING AWON AGBA INFLUENCE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Enu Opiye\n-Oju Ologbo / Eso Werenjeje\n-Epo Obo\n-Ewe Ajeobale\n-Ose Dudu\n***PREPARATION***\nWe will combine Enu Opiye, Eso Werenjeje, Epo\nObo and Ewe Ajeobale.\nWe will pound all the materials thoroughly in a\nmortar.\nWe will mix the preparation properly with Ose\nDudu.\n***USAGE***\nWe will use the prepared soap for bathing at\nnight or very early before dawn.\nSource:\nOogun Yoruba - \"Ituwo Awon Agba To Daju.\""},{"id":"baba-98","source":"baba","sourceName":"OOGUN BABA OGUN","number":98,"title":"OOGUN ASINA","subtitle":"(OPENING THE WAY / ASINA)","preview":"OPENING THE WAY / ASINA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ikun Ojia\n-Epo Obo\n-Ose Dudu\n***PREPARATION***\nWe will combine Ikun Ojia and Epo Obo.\nWe will pound the two materials thoroughly\ntogether.\nWe will mix them properly with Ose Dudu.\n***USAGE***\nWe will use the prepared soap for bathing in the\nmorning.\nSource:\nOogun Yoruba - \"Ose Asina\" under Oogun Asina."},{"id":"baba-99","source":"baba","sourceName":"OOGUN BABA OGUN","number":99,"title":"ASINA OWO","subtitle":"(OPENING THE WAY FOR MONEY / PROSPERITY)","preview":"OPENING THE WAY FOR MONEY / PROSPERITY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Ajeobale - 9\n-Ewe Iyalode Funfun - 9\n-Ewe Iyalode Pupa - 9\n-Ewe Akoko - 9\n-Ewe Ewuro - 9\n-Ose Dudu\n***PREPARATION***\nWe will collect nine portions each of Ewe\nAjeobale, Ewe Iyalode Funfun, Ewe Iyalode\nPupa, Ewe Akoko and Ewe Ewuro.\nWe will pound all the leaves thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nDudu.\n***USAGE***\nWe will use the prepared soap for bathing in the\nmorning.\nSource:\nOogun Yoruba - \"Asina Owo.\""},{"id":"baba-100","source":"baba","sourceName":"OOGUN BABA OGUN","number":100,"title":"OSE AWEBI","subtitle":"(AWEBI CLEANSING SOAP)","preview":"AWEBI CLEANSING SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Mafiowokan Omomi\n-Ewe Oparun - small quantity\n-Epo Obo\n-Ose Iwe Ekan Soso\n***PREPARATION***\nWe will combine Ewe Mafiowokan Omomi, Ewe\nOparun and Epo Obo.\nWe will pound all the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nIwe Ekan Soso.\n***USAGE***\nThe source directs that this particular Awebi\nsoap be used for bathing at a flowing river.\nIt is traditionally described as Awebi for\nwashing away Egun and Abilu Buruku.\nSource:\nOogun Yoruba - \"Ose Awebi We Egun Pelu Abilu\nBuruku Danu.\"\nNOTE:\nThis is specifically No. 100 OSE AWEBI.\nI have not used the separate No. 101 \"Ose Iwe\nOdo / Awebi Awese\" formula yet."},{"id":"baba-101","source":"baba","sourceName":"OOGUN BABA OGUN","number":101,"title":"OSE IWE ODO / AWEBI AWESE","subtitle":"(RIVER-BATH CLEANSING SOAP)","preview":"RIVER-BATH CLEANSING SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Oparun / Ewe Pabirun\n-Epo Obo\n-Eru Alamo\n-Ose\n-Iyo - salt\n***PREPARATION***\nWe will collect Ewe Oparun, which the source\ncalls Ewe Pabirun for this preparation.\nWe will combine the leaf with Epo Obo and Eru\nAlamo.\nWe will pound the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose.\n***USAGE***\nWe will take the prepared soap to a flowing\nriver.\nBefore bathing, the source directs that Iyo be\nput into the river.\nWe will then use the prepared soap to bathe.\nSource:\nOogun Yoruba - \"Ose Iwe Odo, Awebi Awese,\nAwe Osi Danu.\""},{"id":"baba-102","source":"baba","sourceName":"OOGUN BABA OGUN","number":102,"title":"AWEBI WEPE DANU","subtitle":"(CLEANSING / WASHING AWAY WEPE)","preview":"CLEANSING / WASHING AWAY WEPE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo - small quantity\n-Ewe Bomubomu\n-Ose Dudu\n***PREPARATION***\nWe will combine Epo Obo and Ewe Bomubomu.\nWe will pound them thoroughly together.\nWe will mix the preparation properly with Ose\nDudu.\n***USAGE***\nThe source directs that the prepared soap be\nused to bathe at a river once only.\nSource:\nOogun Yoruba - \"Awebi Wepe Danu.\""},{"id":"baba-103","source":"baba","sourceName":"OOGUN BABA OGUN","number":103,"title":"ERO OFA ARA / APETA","subtitle":"(TRADITIONAL ERO APETA PREPARATION)","preview":"TRADITIONAL ERO APETA PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Iyagbe Ayekoto\n-Eku Asin Gbigbe\n-Opolo Gbigbe\n-Eso Tagiri\n-Adi Eyan\n***PREPARATION***\nWe will combine Iyagbe Ayekoto, dried Eku\nAsin, dried Opolo and Eso Tagiri.\nThe source directs that they be ground together\ninto an Agunmu.\nAdi Eyan is then added to the preparation.\n***USAGE***\nThe historical source directs oral use morning\nand night and also application to the body.\nSource:\nOogun Yoruba - \"Ero Ofa Ara / Apeta Eyikeyi.\"\nIMPORTANT:\nDo not ingest this preparation. It contains\nunidentified traditional substances and dried\nanimal material that may carry serious\ninfection or toxicity risks."},{"id":"baba-104","source":"baba","sourceName":"OOGUN BABA OGUN","number":104,"title":"OOGUN ORINRIN","subtitle":"(TRADITIONAL PROTECTION AGAINST ORINRIN)","preview":"TRADITIONAL PROTECTION AGAINST ORINRIN · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Mafiowokan Omomi\n-Ewe Ajeobale\n-Epo Obo\n-Oko Atare - 1\n-Ose Dudu\n***PREPARATION***\nWe will combine Ewe Mafiowokan Omomi, Ewe\nAjeobale, Epo Obo and one Oko Atare.\nWe will pound all the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nDudu.\n***USAGE***\nThe source directs that the prepared soap be\nused for bathing.\nSource:\nOogun Yoruba - \"Oogun Orinrin.\"\nNOTE:\nA second version in the same source is prepared\nas Turari from Ata Wewe or Ata Ijosin with Epo\nObo. I have used only the soap version here."},{"id":"baba-105","source":"baba","sourceName":"OOGUN BABA OGUN","number":105,"title":"OOGUN ALAKALA","subtitle":"(TRADITIONAL PROTECTION AGAINST NIGHTMARES / ALAKALA)","preview":"TRADITIONAL PROTECTION AGAINST NIGHTMARES / ALAKALA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Bobo Awodi\n-Ewe Yanrin\n-Eru Alamo\n-Epo Obo\n-Ose\n***PREPARATION***\nWe will combine Ewe Bobo Awodi, Ewe Yanrin,\nEru Alamo and Epo Obo.\nWe will pound all the materials thoroughly\ntogether.\nWe will mix the resulting preparation properly\nwith Ose.\n***USAGE***\nWe will use the prepared soap for bathing.\nSource:\nOogun Yoruba - \"Oogun Alakala.\"\nNOTE:\nThis is the protective Alakala preparation, not\nan Abilu formula intended to send nightmares."},{"id":"baba-106","source":"baba","sourceName":"OOGUN BABA OGUN","number":106,"title":"OOGUN KO OHUNJE LOJU ALA","subtitle":"(TRADITIONAL WORKING AGAINST EATING IN DREAMS)","preview":"TRADITIONAL WORKING AGAINST EATING IN DREAMS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eso Bomubomu OR Oje Omu\n-Ifun Pepeye\n-Odidi Atare - 1\n-Iyerosun / Ifa preparation\n-Adin Ayan\n***PREPARATION***\nWe will combine Eso Bomubomu or Oje Omu\nwith Ifun Pepeye and one whole Atare.\nWe will burn the materials together.\nThe source then associates the preparation with\nEjiogbe.\nThe resulting preparation is traditionally mixed\nwith Adin Ayan.\n***USAGE***\nThe source describes taking a small quantity\norally.\nIt distinguishes Ifun Pepeye Ako for a man and\nIfun Pepeye Abo for a woman.\nSource:\nOogun Yoruba - \"Oogun Ko Ohunje Loju Ala.\"\nIMPORTANT:\nThis is recorded as traditional practice only. Do\nnot ingest burnt animal organs or unidentified\ntraditional substances because of infection and\ntoxicity risks."},{"id":"baba-107","source":"baba","sourceName":"OOGUN BABA OGUN","number":107,"title":"OOGUN FUN ENITON FARA KO OWUN ALANTAKUN","subtitle":"(WORKING FOR SOMEONE WHO KEEPS WALKING INTO SPIDER WEBS)","preview":"WORKING FOR SOMEONE WHO KEEPS WALKING INTO SPIDER WEBS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Tude\n-Egbo Tude\n-Epo Obo\n-Epo Igi Nla\n-Ewe Mafiowokan Omomi\n-Ose\n-Turari Bintu\n***PREPARATION***\nWe will combine Ewe Tude, Egbo Tude, Epo\nObo, Epo Igi Nla and Ewe Mafiowokan Omomi.\nWe will pound the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose.\nWe will add Turari Bintu and mix everything\nthoroughly.\n***USAGE***\nThe source directs that the resulting\npreparation be used as a bathing soap.\nSource:\nOogun Yoruba - \"Eniton Fara Ko Owun\nAlantakun.\"\nNOTE:\nA separate practitioner text gives other spider￾web formulas, but I have kept this exact Oogun\nYoruba version rather than mixing them."},{"id":"baba-108","source":"baba","sourceName":"OOGUN BABA OGUN","number":108,"title":"OOGUN ASETA","subtitle":"(TRADITIONAL ASETA WORKING)","preview":"TRADITIONAL ASETA WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Oka - 1\n-Epo Obo\n-Odidi Atare - 1\n***PREPARATION***\nWe will combine Ori Oka, Epo Obo and one\nwhole Atare.\nWe will grind the materials thoroughly together\nuntil they form a fine preparation.\n***USAGE***\nThe source traditionally applies this\npreparation through Gbere:\n-9 for a man\n-7 for a woman\nSource:\nOogun Yoruba - \"Ogun Aseta.\"\nIMPORTANT:\nGbere means making cuts/marks in the skin. I\nam preserving what the source says, but cutting\nthe skin can cause infection, scarring and\ntransmission of blood-borne disease."},{"id":"baba-109","source":"baba","sourceName":"OOGUN BABA OGUN","number":109,"title":"AROBI","subtitle":"(AROBI WORKING)","preview":"AROBI WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Etiponla\n-Ewe Alupaida\n-Oju Oro\n-Ose Dudu\n***PREPARATION***\nWe will combine Ewe Etiponla, Ewe Alupaida\nand Oju Oro.\nWe will pound all the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nDudu.\n***USAGE***\nThe source directs that the soap be used only\nfrom the head down to the neck area.\nIt specifically warns against using this\nparticular preparation over the entire body.\nSource:\nOogun Yoruba - \"Arobi.\""},{"id":"baba-110","source":"baba","sourceName":"OOGUN BABA OGUN","number":110,"title":"OOGUN ISORI OTA","subtitle":"(ISORI OTA)","preview":"ISORI OTA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Igbin Apinu - 1\n-Eru Oju Aro\n-Iyo Isebe\n-Ose Dudu\n-Igba\n***PREPARATION***\nWe will take one Igbin Apinu.\nWe will combine it with Eru Oju Aro and Iyo\nIsebe.\nWe will pound the materials thoroughly\ntogether with Ose Dudu.\nWe will put the prepared soap inside an Igba.\n***USAGE***\nThe source directs that the prepared soap be\nused for bathing one portion at a time.\nSource:\nOogun Yoruba - \"Ogun Isori Ota.\""},{"id":"baba-111","source":"baba","sourceName":"OOGUN BABA OGUN","number":111,"title":"MADARIKAN AJE TABI OSO","subtitle":"(TRADITIONAL MADARIKAN AGAINST AJE / OSO)","preview":"TRADITIONAL MADARIKAN AGAINST AJE / OSO · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Eyo Atare - 9\n***PREPARATION***\nWe will grind Epo Obo thoroughly.\nWe will combine it with nine Atare until the\npreparation is fine and properly mixed.\n***USAGE***\nThe source traditionally applies the preparation\nthrough one Gbere at the centre of the head.\nSource:\nOogun Yoruba - \"Madarikan Aje Tabi Oso.\"\nNOTE:\nThe source literally specifies Gbere. Cutting the\nskin carries infection and blood-borne disease\nrisks."},{"id":"baba-112","source":"baba","sourceName":"OOGUN BABA OGUN","number":112,"title":"OSE ILEKE","subtitle":"(ILEKE / PROMINENCE SOAP)","preview":"ILEKE / PROMINENCE SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Oju Oro\n-Osibata\n-Ose Dudu - black soap\n***PREPARATION***\nWe will combine Oju Oro and Osibata.\nWe will pound the two materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nDudu.\n***USAGE***\nWe will use the prepared soap for bathing in the\nmorning.\nSource:\nOogun Yoruba - \"Ose Ileke.\""},{"id":"baba-113","source":"baba","sourceName":"OOGUN BABA OGUN","number":113,"title":"OSE ISEGUN","subtitle":"(VICTORY SOAP)","preview":"VICTORY SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Ewe Ajeobale\n-Kafura Pelebe - 1\n-Ose\n-Ike\n***PREPARATION***\nWe will combine Epo Obo, Ewe Ajeobale and\none Kafura Pelebe.\nWe will grind the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose.\nWe will put the prepared soap inside an Ike.\n***USAGE***\nWe will use the prepared soap for bathing.\nSource:\nOogun Yoruba - \"Ose Isegun.\""},{"id":"baba-114","source":"baba","sourceName":"OOGUN BABA OGUN","number":114,"title":"OOGUN AJEGUN","subtitle":"(AJEGUN WORKING)","preview":"AJEGUN WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eso Akoko\n-Odidi Atare - 1\n***PREPARATION***\nWe will combine Eso Akoko with one whole\nAtare.\nWe will burn the two materials together.\nWe will grind the burnt preparation thoroughly\ninto fine powder.\n***USAGE***\nThe source traditionally applies the preparation\naround both wrists through Gbere.\nSource:\nNew Asiri Aye / Oogun Ajegun variant.\nNOTE:\nI selected this distinct Ajegun formula rather\nthan repeating the Ewe Ela / Atelewo Inaki\ncombination.\nDo not cut the skin to apply unidentified plant\nash."},{"id":"baba-115","source":"baba","sourceName":"OOGUN BABA OGUN","number":115,"title":"AFOSE OLUGBOHUN MAYEHUN","subtitle":"(COMMAND / SPOKEN-AUTHORITY WORKING)","preview":"COMMAND / SPOKEN-AUTHORITY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Oka ti oni Ase lenu - 1\n-Iru Oga\n-Ase Iru Okete\n-Egbo Akerejupon\n-Odidi Atare Aja - 1\n-Ose Dudu - small quantity\n-Iwo Eran Agbo - ram horn\n-Aso Pupa - red cloth\n***PREPARATION***\nWe will combine Ori Oka, Iru Oga, Ase Iru\nOkete, Egbo Akerejupon and one Atare Aja.\nWe will pound the materials thoroughly\ntogether.\nWe will mix the preparation with a small\nquantity of Ose Dudu.\nWe will put the preparation inside an Iwo Agbo.\nWe will cover the mouth of the horn with Aso\nPupa.\n***USAGE***\nWhen traditionally required, the red cloth is\nremoved.\nThe source directs touching the preparation\nwith the tongue before speaking the intended\nwords.\nAfterward, the horn is covered again with the\nred cloth.\nSource:\nOogun Yoruba - \"Afose Olugbohun Mayehun\nTodaju.\"\nNOTE:\nDo not put unidentified herbal/animal\npreparations in the mouth; this is recorded here\nas a traditional formula."},{"id":"baba-116","source":"baba","sourceName":"OOGUN BABA OGUN","number":116,"title":"IFA FAYAWO","subtitle":"(FAYAWO / TRADITIONAL PROTECTIVE WORKING)","preview":"FAYAWO / TRADITIONAL PROTECTIVE WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Abamoda - 201\n-Ewe Alupaida - 201\n-Eyo Atare - 201\n-Ibi Omo Aguntan Tuntun\n-Owo Eyo - 1\n-Oruka Irin - several\n***PREPARATION***\nWe will combine Ewe Abamoda, Ewe Alupaida,\nAtare and the source's Ibi Omo Aguntan.\nWe will add the coin and iron rings.\nThe source directs that the materials be burned\ntogether.\nThe burnt material is then ground thoroughly.\n***USAGE***\nThe source traditionally applies the preparation\nthrough Gbere on the hands and feet.\nA prepared iron ring is then worn on the hand.\nSource:\nIle Nla, Volume One - Page 68, \"Ifa Fayawo\nTodaju.\"\nNOTE:\nThe source includes animal birth material and\nskin cutting, both of which can carry infection\nrisks."},{"id":"baba-117","source":"baba","sourceName":"OOGUN BABA OGUN","number":117,"title":"IFA BESODE","subtitle":"(IFA BESODE / MONEY-ATTRACTION WORKING)","preview":"IFA BESODE / MONEY-ATTRACTION WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eran Ewure ti o ti bimo ri - 1\n-Ojuda / cord\n-Owo tuntun\n-Dollar tuntun\n-Atare - 10\n-Eru Awoka\n-Epo Pupa\n-Akerengbe\n-Iyerosun / Ifa preparation\n***PREPARATION***\nWe will place the cord, new money and the\nlisted materials inside a new Ape as described\nby the source.\nThe source uses blood from the Ewure in\npreparing the materials.\nThe preparation is then burned and ground\nthoroughly.\nIt is transferred into an Akerengbe.\nThe source associates the finished preparation\nwith Ifa Ogundabede.\n***USAGE***\nA small quantity is traditionally used while the\nIfa Besode prayer is spoken.\nThe source associates the working specifically\nwith opening the way for substantial money.\nSource:\nIle Nla, Volume One - Pages 61–62, \"Ifa Besode.\"\nNOTE:\nThis source involves animal blood and fire. It\nshould be treated as documentation of\npractitioner tradition, not as a guaranteed\nfinancial method."},{"id":"baba-118","source":"baba","sourceName":"OOGUN BABA OGUN","number":118,"title":"DIGI IWOSE BABALAWO","subtitle":"(DIVINATION / CONSULTATION MIRROR)","preview":"DIVINATION / CONSULTATION MIRROR · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Digi - mirror\n-Afomo Igikigi - plenty\n-Eyin Ope to pon - 9\n-Mumunin - 9\n-Oju Otun Ako Aja\n-Oju Otun Abo Aja\n-Aloku Igba from farmland\n-Ikode - 9\n-Eyo Atare - 201\n-Okan Akuko Adie\n-Aso Funfun\n***PREPARATION***\nWe will combine the listed plant and animal\nmaterials.\nThe source burns the prepared materials and\ngrinds them thoroughly.\nA small amount is ritually associated with the\nsurface of the mirror.\nThe mirror is then wrapped with Aso Funfun.\nThe source describes a period of ritual\nconsecration before the mirror is finally kept\ninside an Aso Asunwon Funfun.\n***USAGE***\nThe practitioner traditionally places the mirror\nbefore himself at night and uses it during\nconsultation to seek information about a client's\nproblem and possible solution.\nSource:\nIle Nla, Volume One - Page 1,\n\"Digi Ti A Fi Nwose Lati Fi Mo Isoro Awon\nOnibara Wa Ati Ona Abayo.\"\nNOTE:\nThe original text includes blood and cemetery￾related ritual steps. I have preserved the\nstructure without encouraging unsafe handling\nof biological material or disturbance of graves."},{"id":"baba-119","source":"baba","sourceName":"OOGUN BABA OGUN","number":119,"title":"AJAKUNMEKUN","subtitle":"(AJAKUNMEKUN / ELERU WORKING)","preview":"AJAKUNMEKUN / ELERU WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Odidi Igun - 1\n-Odidi Akala - 1\n-Odidi Kanakanna - 1\n-Odidi Ologbo - 1\n-Odidi Apata Abalaye - 1\n-Oko Oju Omi ti won ti fi ko eru ri - small\nquantity\n-Ose\n-Oti Dry Gin\n-Igba Olomori nla\n-Oyin - 1 bottle\n-Eiyele Funfun - 2\n***PREPARATION***\nWe will combine Igun, Akala, Kanakanna,\nOlogbo, Apata Abalaye and a small amount of\nthe specified Oko Oju Omi material.\nWe will process the materials together as\ndirected by the source.\nThe preparation is associated with Osetura.\nWe will mix it with Ose and Oti Dry Gin.\nWe will put it inside a large Igba Olomori.\nWe will pour Oyin over the preparation.\nThe source then gives an additional\nconsecration involving two white pigeons.\nThe preparation is kept for seven days.\n***USAGE***\nAfter the seven-day period, the source identifies\nit as a bathing preparation.\nIt also gives particular behavioural restrictions\nfor the person using it.\nSource:\nIle Nla, Volume One - Page 57.\nThe page heading reads \"AJAKUNMEKU ELERU.\"\nNOTE:\nThis is the closest direct source text for\ncatalogue No. 119 AJAKUNMEKUN."},{"id":"baba-120","source":"baba","sourceName":"OOGUN BABA OGUN","number":120,"title":"ELERU SONDO","subtitle":"(SONDO / EYONU WORKING)","preview":"SONDO / EYONU WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ileke Itun\n-Ileke Ifa\n-Irun Abe Obinrin\n-Ewe Eeyo\n-Ewe Ata Ijosin\n-Iye Agbe\n-Iye Aluko\n-Iko Odidere\n-Egungun Agbari Ologbo - small quantity\n-Awo Ijimere\n-Awo Ewure\n-Ori\n-Epo\n-Lofinda Bintu OR Miss Paris\n-Iyerosun\n***PREPARATION***\nWe will combine Ileke Itun, Ileke Ifa, Irun Abe\nObinrin, Ewe Eeyo, Ewe Ata Ijosin, Iye Agbe, Iye\nAluko, Iko Odidere, Egungun Agbari Ologbo and\nAwo Ijimere.\nThe source directs that the materials be burned\ntogether.\nAwo Ewure is also burned and a little of its\ncharcoal is added.\nWe will grind all the prepared materials\nthoroughly together.\nWe will put the preparation inside a small\nKonjo.\nWe will add Ori, Epo and Lofinda Bintu or Miss\nParis.\nThe source then associates the preparation with\nIyerosun and Ifa Ogbe Wonrin.\n***USAGE***\nThe source treats it as an Eyonu working and\ndirects the practitioner to make personal\nprayers or requests over it.\nSource:\nIle Nla, Volume One - Page 56.\nSOURCE SPELLING NOTE:\nThe actual page heading reads \"OGUNSONDO\nIYONU.\"\nThe table of contents separately lists \"ELERU\nSONDO.\"\nI have linked them because of their position and\nwording in the same source, but I am not\nclaiming the two spellings are independently\nverified names."},{"id":"baba-121","source":"baba","sourceName":"OOGUN BABA OGUN","number":121,"title":"ONMO IWOSE","subtitle":"(IWOSE / DIVINATORY DISCERNMENT WORKING)","preview":"IWOSE / DIVINATORY DISCERNMENT WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Ikun\n-Odidi Atare - 1\n-Epa Tutu - fresh Epa; the source glosses it as\n\"coconut\"\n-Ape\n***PREPARATION***\nWe will place Ori Ikun inside an Ape.\nWe will add one whole Atare.\nWe will place the fresh Epa over the materials.\nWe will burn the materials together thoroughly.\nWe will grind the burnt preparation until it\nbecomes a fine powder.\n***USAGE***\nThe source traditionally uses a small quantity\nwith Eko while carrying out the Iwose working.\nIts accompanying prayer/Psalm is said at the\ntime of use.\nSource:\nIwe Eto Agbara - \"Eto Ohnmo Iwose.\"\nNOTE:\nThis is NOT the Digi Iwose formula sent as No.\n118.\nThis is a separate Onmo Iwose preparation.\nIMPORTANT:\nDo not ingest burnt unidentified animal or plant\nmaterial merely because a traditional source\nprescribes it."},{"id":"baba-122","source":"baba","sourceName":"OOGUN BABA OGUN","number":122,"title":"ONIPASAN OWERE","subtitle":"(ONIPASAN OWERE / AJE-RELATED WORKING)","preview":"ONIPASAN OWERE / AJE-RELATED WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Panduku Ako - 1\n-Eye Ologesa - 1\n-Oga Gbigbe - 1\n-Ewe Opoto - plenty\n-Odidi Atare - 1\n-Epo Pupa\n-Ape / ritual container\n***PREPARATION***\nWe will combine Ori Panduku Ako, Eye Ologesa,\nOga Gbigbe, Ewe Opoto and one whole Atare.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly.\nThe source then associates the powder with Ifa\nEjiogbe.\nA small portion is separated for the traditional\nIpese.\nThe second part of the source includes an\nanimal offering and Epo Pupa, but the publicly\nindexed text is corrupted in that section, so I\nwill not invent the missing wording.\n***USAGE***\nThe source uses a small quantity of the\nprepared Ebu for Ipese.\nThe Ipese is traditionally taken to Orita or Ori\nAkitan.\nSource:\nOluweri Mama Ojo practitioner collection -\n\"Nipasan Owere.\""},{"id":"baba-123","source":"baba","sourceName":"OOGUN BABA OGUN","number":123,"title":"OSHOLE ALARO META","subtitle":"(THREE-CORNER OSHOLE)","preview":"THREE-CORNER OSHOLE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Odidi Panduku - 1\n-Ori Ijimere - 1\n-Ori Ofafa - 1\n-Owo representing three different types/places\n-Ewe Ejinrin - plenty\n-Ewe Ola - plenty\n-Atare Nla\n-Ape\n-Sere\n***PREPARATION***\nWe will arrange the three sets of Owo inside the\nApe in the form of Aro Meta so that the three\ncorners correspond with one another.\nThe source directs that the user's name be\nassociated with the Owo.\nWe will arrange Ori Panduku, Ori Ijimere and\nOri Ofafa inside the Ape so that they face one\nanother.\nWe will place Atare over the preparation.\nWe will add Ewe Ejinrin and Ewe Ola.\nWe will burn everything together.\nWe will grind the burnt preparation thoroughly.\nWe will put the powder inside a Sere.\n***USAGE***\nWe will keep the Sere at a corner of the room.\nThe source directs that a small quantity\ntraditionally be used with Oti in the morning.\nSource:\nIwe Asiri Awon Agba Igbaani - \"Oshole Alaro\nMeta.\""},{"id":"baba-124","source":"baba","sourceName":"OOGUN BABA OGUN","number":124,"title":"MOBA ILE MULE","subtitle":"(COVENANT / IMULE WITH EGBE)","preview":"COVENANT / IMULE WITH EGBE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-The accessible source does not give a separate\ningredient list for the Ebo.\n-Eku and Eja occur repeatedly within the Ese Ifa\nconnected with the covenant.\n***PREPARATION***\nThe working appears under Ofun Meji.\nThe source describes Orunmila going to make a\ncovenant with Egbe.\nIfa instructed him to perform Ebo, and the text\nstates that he completed the Ebo.\nAfterward, the Moba Yin Mule recitation is used\nas the covenant prayer.\n***USAGE***\nThe source directs the covenant toward\nrequests including:\n-Aje - prosperity\n-Omo - children\n-Ile - a house/home\n-Ire Gbogbo - general good fortune\nSource:\nOfun Meji corpus - \"Aji ni roro / Moba Yin\nMule.\"\nNOTE:\nThe verse is well documented, but the accessible\nversion does NOT identify the complete Ebo\nmaterials. I have therefore not manufactured\nan ingredient list."},{"id":"baba-125","source":"baba","sourceName":"OOGUN BABA OGUN","number":125,"title":"OSHOLE ARINMOLE","subtitle":"(BURIED OSHOLE WORKING)","preview":"BURIED OSHOLE WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials under the title OSHOLE\nARINMOLE were not recovered from the\nsources checked.\n***PREPARATION***\nThe title OSHOLE ARINMOLE is explicitly listed\nin Agbara Igbaani as its own preparation.\nHowever, the complete recipe is not exposed in\nthe publicly accessible pages.\n***USAGE***\nBy the term Arinmole, the working belongs to\nthe class of preparations traditionally placed or\nburied in the ground.\nSource:\nAgbara Igbaani - contents list.\nNOTE:\nI located a different preparation titled AWORO\nARINMOLE using an Ikoko Olomori, Akara\nElepo, Olongbo and Epo Pupa.\nI have NOT substituted that formula here\nbecause AWORO ARINMOLE and OSHOLE\nARINMOLE are not the same title."},{"id":"baba-126","source":"baba","sourceName":"OOGUN BABA OGUN","number":126,"title":"AWURE OLA TI A FI NKOLE","subtitle":"(AWURE OLA / PROSPERITY ASSOCIATED WITH BUILDING)","preview":"AWURE OLA / PROSPERITY ASSOCIATED WITH BUILDING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\nFor the soap:\n-Ewe Orijin\n-Omonigedegede Tutu\n-Yanrin Okun - sea sand\n-Yanrin Osa - lagoon sand\n-Ose Dudu\n-Eje Ako Maalu\nFor the Abusari:\n-Owo Eyo ti ko lu - 201\n-Omonigedegede Tutu\n-Iseta\n-Eegun Ori Esin - small quantity\n***PREPARATION***\nFIRST PART:\nWe will combine Ewe Orijin, Omonigedegede\nTutu, Yanrin Okun and Yanrin Osa.\nWe will pound them thoroughly with Ose Dudu.\nThe source adds Eje Ako Maalu while mixing\nthe soap.\nWe will put the prepared soap inside an Ike\nFunfun.\nSECOND PART - ABUSARI:\nWe will combine 201 Owo Eyo, Omonigedegede,\nIseta and a small quantity of Eegun Ori Esin.\nWe will grind the materials thoroughly until\nthey become powder.\n***USAGE***\nWe will use the prepared Awure Ola soap for\nbathing.\nAfter bathing, the source directs that a small\nquantity of the Abusari be applied to the head.\nSource:\nPractitioner collection - \"Awure Ola.\"\nSOURCE NOTE:\nAgbara Igbaani gives the fuller catalogue title\n\"Awure Ola Ti A Fi Nkole.\"\nThe detailed source I recovered calls its formula\nsimply AWURE OLA, so I am identifying that\ndistinction instead of claiming the wording is\nidentical.\nIMPORTANT:\nAnimal blood and bone can transmit infection.\nThis is documentation of the traditional\nformula, not a hygiene-safe recommendation."},{"id":"baba-127","source":"baba","sourceName":"OOGUN BABA OGUN","number":127,"title":"AGBAKO TUDE TODAJU","subtitle":"(AGBAKO-TUDE WORKING)","preview":"AGBAKO-TUDE WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Complete materials under the exact title were\nnot recovered.\n***PREPARATION***\nAGBAKO TUDE TODAJU is explicitly listed as a\nseparate preparation in Agbara Igbaani.\nI found several Tude and Agbako preparations,\nbut none could be verified as the exact recipe\nbelonging to this combined title.\n***USAGE***\nNot disclosed in the accessible portion of the\noriginal source.\nSource:\nAgbara Igbaani - \"Agbako Tude Todaju.\"\nNOTE:\nI have deliberately not inserted an ordinary\nTude, Asina Tude or Agbako formula because\nthose are different workings and several have\nalready appeared in our earlier batches."},{"id":"baba-128","source":"baba","sourceName":"OOGUN BABA OGUN","number":128,"title":"AJALA ELERU","subtitle":"(AJALA ELERU)","preview":"AJALA ELERU · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-NOT REPEATED.\n***PREPARATION***\nThe exact AJALA ELERU formula I located uses:\nIgun, Akala, Kanakanna, Ologbo, Apata Abalaye,\nOko Oju Omi, Ose, Dry Gin, Oyin and two Eyele\nFunfun.\nThat is the SAME material set and procedure\nalready sent to you under No. 119\nAJAKUNMEKUN / ELERU.\n***USAGE***\nI am intentionally not reproducing the\npreparation again because you requested NO\nREPETITION of formulas already sent.\nSource:\nEto Adura Todaju - \"Ajala Eleru.\"\nNOTE:\nThis source confirms that the apparent\ncatalogue distinction does not give us a\ngenuinely new formula in this case."},{"id":"baba-129","source":"baba","sourceName":"OOGUN BABA OGUN","number":129,"title":"IFA APATAPITI","subtitle":"(ODI KA / APATAPITI)","preview":"ODI KA / APATAPITI · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eyele - pigeon\n-Agbebo Adie - hen\n***PREPARATION***\nThis preparation belongs to Odi Ka.\nThe Ese Ifa begins with the divination made for\nApatapiti when he was going on an\nIfa/divination journey to Ilu Ilaje.\nThe source prescribes Ebo rather than a\ncompounded herbal medicine.\nThe prescribed Ebo is:\n-Eyele\n-Agbebo Adie\nNo additional herbal compound is specified in\nthe recovered version.\n***USAGE***\nThe Ebo is traditionally connected with the\nauthority and accuracy of the Awo's\npronouncements and divination.\nThe verse states that what Ifa and the Awo say\nwill come to pass for Apatapiti.\nSource:\nOdi Ka corpus - \"Tubu Niyan Rin / Kere Niyangi /\nAdifa fun Apatapiti.\""},{"id":"baba-130","source":"baba","sourceName":"OOGUN BABA OGUN","number":130,"title":"AROTUTU","subtitle":"(AROTUTU)","preview":"AROTUTU · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nAROTUTU is specifically listed as its own\nworking in Agbara Igbaani and also appears\namong the named preparations advertised in\nanother practitioner collection.\nNeither accessible source exposes the actual\nArotutu recipe.\n***USAGE***\nNot disclosed in the accessible material.\nSource:\nAgbara Igbaani - \"Arotutu.\"\nNOTE:\nI searched the title separately and did not find a\ncomplete formula that could be confidently tied\nto this exact name.\nI will not rename an unrelated Atude, Arobi or\ncooling medicine as Arotutu simply to fill the\nentry."},{"id":"baba-131","source":"baba","sourceName":"OOGUN BABA OGUN","number":131,"title":"ONMO ISOYE BABALAWO","subtitle":"(ISOYE / MEMORY AND UNDERSTANDING FOR A PRACTITIONER)","preview":"ISOYE / MEMORY AND UNDERSTANDING FOR A PRACTITIONER · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Isawuru - 9\n-Ewe Oniyemeye\n-Ewe Amunimuye\n-Ewe Iyeye\n-Odidi Atare - 1\n-Oyin Gidi - pure honey\n***PREPARATION***\nWe will combine the nine Isawuru, Ewe\nOniyemeye, Ewe Amunimuye, Ewe Iyeye and\none whole Atare.\nWe will burn all the materials together.\nWe will grind the burnt preparation thoroughly\nuntil it becomes fine.\nWe will put the preparation into Oyin Gidi and\nmix it properly.\n***USAGE***\nThe source directs that a small quantity\ntraditionally be licked when needed for Isoye.\nSource:\nIwe Akoni Oduduwa - \"Ogun Isoye.\"\nSOURCE NOTE:\nThe catalogue title is ONMO ISOYE BABALAWO.\nThe detailed formula recovered is\nindependently titled OGUN ISOYE, so I am not\nclaiming the wording is identical."},{"id":"baba-132","source":"baba","sourceName":"OOGUN BABA OGUN","number":132,"title":"OBA TUDE TO GBONA","subtitle":"(STRONG TUDE / RELEASE WORKING)","preview":"STRONG TUDE / RELEASE WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-The exact materials under OBA TUDE TO\nGBONA were not recovered.\nA separately documented Tude-Asina\npreparation gives:\n-Baka Epa\n-Ikun\n-Kahun Bilala\n-Ose Dudu - black soap\n***PREPARATION***\nFor the related Tude-Asina version:\nWe will grind Baka Epa, Ikun and Kahun Bilala\nthoroughly together.\nWe will combine the preparation properly with\nOse Dudu.\n***USAGE***\nThe related source directs that it be used for\nbathing at night before sleeping.\nSource:\nIle Nla / Agbara Igbaani confirms the exact\nheading \"OBA TUDE TO GBONA.\"\nSeparate practitioner source - \"Ogun Tude\nAshina.\"\nNOTE:\nI have not falsely claimed the related Tude\nrecipe is the exact hidden Oba Tude formula."},{"id":"baba-133","source":"baba","sourceName":"OOGUN BABA OGUN","number":133,"title":"ADO ATONA","subtitle":"(ATONA DIVINATION / DIRECTION ADO)","preview":"ATONA DIVINATION / DIRECTION ADO · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Okuta Idaro\n-Ado Ijamo - 1\n-Eyin Ibile oojo\n-Efun\n-Osun\n***PREPARATION***\nWe will grind Okuta Idaro thoroughly until it\nbecomes fine.\nWe will put the prepared material inside an Ado\nIjamo.\nWe will break the Eyin Ibile and add its\ncontents to the Ado.\nWe will draw one circle with Efun.\nWe will draw another circle with Osun.\nWe will place the prepared Ado between the\ncircles.\nWe will leave it there for seven days.\n***USAGE***\nAfter the seventh day, the source says the Ado is\nready for traditional Atona use.\nIt is traditionally consulted when asking for\ndirection or an answer concerning a matter.\nSource:\nIda Oloju Meji - \"ADO ATONA.\""},{"id":"baba-134","source":"baba","sourceName":"OOGUN BABA OGUN","number":134,"title":"IBIYEMI OMO OBINRIN AKURE","subtitle":"(SOURCE-SPECIFIC NAMED WORKING)","preview":"SOURCE-SPECIFIC NAMED WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nIBIYEMI OMO OBINRIN AKURE appears as a\ndistinct heading in the original Ile Nla / Agbara\nIgbaani contents.\nThe available indexed version does not expose\nthe recipe attached to this title.\n***USAGE***\nNot recovered.\nSource:\nIle Nla / Agbara Igbaani contents list.\nNOTE:\nThis title appears to be source-specific, possibly\npreserving the name or origin of a particular\npreparation.\nI have not attached an unrelated Obinrin, Iferan\nor Oshole formula to it."},{"id":"baba-135","source":"baba","sourceName":"OOGUN BABA OGUN","number":135,"title":"OSHO GBEMIPADE OLOORE","subtitle":"(OSHO FOR MEETING A BENEFACTOR / HELPER)","preview":"OSHO FOR MEETING A BENEFACTOR / HELPER · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials under this precise title were\nnot recovered.\n***PREPARATION***\nThe title OSHO GBEMIPADE OLOORE is clearly\nlisted in the original source.\nHowever, the accessible indexed pages do not\nprovide its ingredient list or preparation.\n***USAGE***\nBy the wording of the title, the source associates\nit with meeting an Oloore - a benefactor or\nperson who brings favour.\nSource:\nIle Nla / Agbara Igbaani.\nNOTE:\nI found several Alaanu, Oloore and Eyonu\nformulas, but I have not substituted them\nbecause they carry different names."},{"id":"baba-136","source":"baba","sourceName":"OOGUN BABA OGUN","number":136,"title":"GBEWA OWO","subtitle":"(GBEWA / MONEY-ATTRACTION WORKING)","preview":"GBEWA / MONEY-ATTRACTION WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Okan Akile Ojuda\n-Okan Malu Dudu\n-Okan Esin Funfun\n-Abo Adie Funfun\n-Eyele Funfun\n-Ose Dudu\n-Awo Tanganran Funfun Olomori\n***PREPARATION***\nWe will combine Okan Akile Ojuda, Okan Malu\nDudu, Okan Esin Funfun, Abo Adie Funfun and\nEyele Funfun.\nWe will process the listed materials together.\nWe will mix the preparation thoroughly with\nOse Dudu.\nWe will put the prepared soap inside an Awo\nTanganran Funfun Olomori.\nThe source then directs that Ifa be consulted\nconcerning the appropriate Etutu connected\nwith the working.\n***USAGE***\nThe source directs that the prepared soap\ntraditionally be used for bathing at about one\no'clock at night.\nIt associates the working with GBEWA OWO.\nSource:\nPractitioner collection - \"GBEWA OWO TODAJU\nPA.\"\nNOTE:\nThe financial claims made by the source are\ntraditional practitioner claims, not guarantees."},{"id":"baba-137","source":"baba","sourceName":"OOGUN BABA OGUN","number":137,"title":"OSHO SOMI DOLOWO","subtitle":"(SOMI DOLOWO / PROSPERITY OSHOLE)","preview":"SOMI DOLOWO / PROSPERITY OSHOLE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Ewure ti o ti bimo ri, with hair\n-Eye Kowe - 1\n-Ape Tuntun\n-Odidi Atare Nla - 1\n-Ado\n-Awo Ekun\n-Aso Funfun for an Osuwo Apo\n***PREPARATION***\nWe will place the Ori Ewure and Eye Kowe\ninside a new Ape.\nWe will add one large whole Atare.\nWe will burn the materials together thoroughly.\nWhen they have burnt completely, we will grind\nthem until fine.\nWe will put the preparation inside an Ado.\nThe source directs that the Ado be completely\ncovered with Awo Ekun so that the Ado itself is\nno longer visible.\nWe will sew an Osuwo Apo from Aso Funfun.\nWe will place the prepared Ado inside the white\ncloth bag.\nWe will hang it so that its base does not touch\nthe ground.\n***USAGE***\nThe source traditionally places money with the\npreparation while making the desired\nprosperity request.\nSource:\nIda Awon Ogboni - \"OSOLE SOMI DOLOWO.\"\nA second practitioner compilation also records\n\"SOMIDOLOWO, SOMIDOLORO.\""},{"id":"baba-138","source":"baba","sourceName":"OOGUN BABA OGUN","number":138,"title":"OSO OWO ATUIPINYAN","subtitle":"(ATUIPINYAN MONEY WORKING)","preview":"ATUIPINYAN MONEY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nOSO OWO ATUIPINYAN is explicitly listed as an\nindependent heading in Ile Nla.\nI searched Atuipinyan / Atunpiyan variants\nseparately, but I did not find a complete\nformula that could be confidently tied to this\nexact Oso Owo title.\n***USAGE***\nNot disclosed in the accessible version.\nSource:\nIle Nla / Agbara Igbaani.\nNOTE:\nI have not substituted one of the Atunpiyan\nmedicines from our earlier work because you\nasked me not to repeat old formulas."},{"id":"baba-139","source":"baba","sourceName":"OOGUN BABA OGUN","number":139,"title":"SIRERE","subtitle":"(SIRERE)","preview":"SIRERE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials not recovered.\n***PREPARATION***\nSIRERE appears as a standalone title in the Ile\nNla contents list.\nThe actual preparation under this heading was\nnot exposed in the accessible indexed text.\n***USAGE***\nNot recovered.\nSource:\nIle Nla / Agbara Igbaani.\nNOTE:\nI found linguistic references to \"Sirere/Sirere,\"\nbut those do not establish the ingredients of this\npractitioner preparation, so I have not invented\nthem."},{"id":"baba-140","source":"baba","sourceName":"OOGUN BABA OGUN","number":140,"title":"OSHOLE CONNECTION","subtitle":"(CONNECTION / MEETING USEFUL PEOPLE)","preview":"CONNECTION / MEETING USEFUL PEOPLE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ako Eye Ega - 1\n-Abo Eye Ega - 1\n-Owo Eyo ti ko luju - 9\n-Ewe Ola\n-Ewe Sawerepepe\n-Odidi Atare - 1\n-Fitila Oloju Merindinlogun\n-Milk Olope\n***PREPARATION***\nWe will combine the male and female Eye Ega,\nnine Owo Eyo, Ewe Ola, Ewe Sawerepepe and\none whole Atare.\nWe will put all the materials inside a Fitila Oloju\nMerindinlogun.\nWe will burn the preparation together.\nWe will grind the resulting material thoroughly.\n***USAGE***\nThe traditional source directs that a small\nquantity be used with Milk Olope.\nThe practitioner specifically associates the\npreparation with money, prominence and\nuseful connections.\nSource:\nPublic practitioner formula - \"Asina Owo /\nConnection Gidi.\"\nSOURCE NOTE:\nIle Nla lists the title OSHOLE CONNECTION.\nThe detailed formula above comes from a\nseparate practitioner source explicitly\ndescribing it as CONNECTION, so I am treating it\nas a same-purpose sourced variant rather than\nclaiming it is the hidden Ile Nla recipe."},{"id":"baba-141","source":"baba","sourceName":"OOGUN BABA OGUN","number":141,"title":"IPARA EBE","subtitle":"(BODY APPLICATION FOR EBE)","preview":"BODY APPLICATION FOR EBE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Ebe / Ewe Gegemu\n-Ori - shea butter\n-Epo Pupa - palm oil\n***PREPARATION***\nWe will collect Ewe Ebe, which the source also\ncalls Ewe Gegemu.\nWe will dry/burn the leaf as directed by the\nsource until it can be ground finely.\nWe will grind the preparation thoroughly.\nWe will mix it properly with Ori and Epo Pupa.\n***USAGE***\nWe will apply the prepared mixture to the body.\nThe source states that both adults and children\ntraditionally use this preparation.\nSource:\nAsiri Nla - \"Ipara Ebe.\""},{"id":"baba-142","source":"baba","sourceName":"OOGUN BABA OGUN","number":142,"title":"BIBO ASIRI OWO","subtitle":"(MONEY / FINANCIAL FAVOUR WORKING)","preview":"MONEY / FINANCIAL FAVOUR WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Alukerese\n-Iyere - small quantity\n-Eran Malu - 9 pieces\n-Omi Agbon from 2 coconuts\n-Epo Pupa\n-Iyo\n-Ori - small quantity\n***PREPARATION***\nWe will grind Ewe Alukerese together with\nIyere.\nWe will put the preparation and nine pieces of\nEran Malu inside a small cooking pot.\nWe will add the water from two coconuts.\nWe will cook it with Epo and Iyo.\nWhen the preparation is almost done, we will\nadd a small quantity of Ori.\nThe source specifies beginning the cooking at\nabout 4:00pm.\nWe will allow it to remain until approximately\n6:00pm.\n***USAGE***\nThe source directs that the preparation be eaten\nafter the traditional prayer for Bibo Asiri Owo.\nSource:\nAsiri Nla - \"Bibo Asiri Owo.\"\nNOTE:\nThe source scan is damaged around the\ndescription of the meat, but \"Eran Malu\" and\nthe number nine are readable. I have not\ninvented a more specific cut of meat.\nDo not eat unidentified herbs unless their\nidentity and food safety are certain."},{"id":"baba-143","source":"baba","sourceName":"OOGUN BABA OGUN","number":143,"title":"EYONU ASIRI BIBO","subtitle":"(FAVOUR + COVERING ONE'S ASIRI)","preview":"FAVOUR + COVERING ONE'S ASIRI · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Ologbo - 1\n-Oga Gbigbe to pe - 1\n-Ewe Orijin oojo\n-Odidi Atare - 1\n-Oyin Igan - pure honey\n***PREPARATION***\nWe will combine Ori Ologbo, Oga Gbigbe, Ewe\nOrijin and one whole Atare.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly\nuntil it becomes fine.\nWe will put the resulting powder inside Oyin\nIgan.\nWe will mix it thoroughly.\n***USAGE***\nThe source directs taking a small quantity from\nthe honey preparation in the morning.\nSource:\nAsiri Nla - \"Eyonu Asiri Bibo Bibo.\"\nNOTE:\nThis is a traditional source record. Animal\nremains or unidentified burnt material should\nnot be eaten because of infection/toxicity risk."},{"id":"baba-144","source":"baba","sourceName":"OOGUN BABA OGUN","number":144,"title":"AWORO ITAJA TODAJU","subtitle":"(SHOP / BUSINESS ATTRACTION)","preview":"SHOP / BUSINESS ATTRACTION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Oka to ni Ase - 1\n-Ewe Aje / Ewe Sefunsefun\n-Ewe Sawerepepe\n-Ewe Tannapowo\n-Ewe Sinkimidin\n-Ewe Awoyoyo / Ewe Inabo\n-Ewe Orijin\n-Ewe Ajeobale\n-Ose Abuwe\n-Ike\n***PREPARATION***\nWe will collect the listed leaves fresh.\nWe will pound all the leaves together\nthoroughly with Ose Abuwe.\nWe will place the Ori Oka at the bottom of the\nIke that will contain the soap.\nWe will put the prepared soap over it.\nWe will keep the preparation properly covered\nfor use.\n***USAGE***\nThe source gives three traditional methods:\n-We may use the soap for bathing.\n-We may wash our hands with it.\n-We may use the preparation in connection with\nthe shop or place of business.\nSource:\nAsiri Nla - \"Aworo Itaja Ti O Daju.\"\nNOTE:\nAwoyoyo and Inabo are alternative names for\nthe same leaf in Yoruba plant references."},{"id":"baba-145","source":"baba","sourceName":"OOGUN BABA OGUN","number":145,"title":"OMI ASINA TODAMILOJU","subtitle":"(ASINA WATER / OPENING THE WAY)","preview":"ASINA WATER / OPENING THE WAY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Ajarere Pupa\n-Omi extracted from the leaf\n-Alubosa Elewe\n-Kafura\n-Ike or Igo Olomori\n***PREPARATION***\nWe will pound Ewe Ajarere Pupa thoroughly\ninside a mortar.\nWe will squeeze and collect its liquid.\nWe will put the prepared liquid inside an Ike or\nIgo that has a cover.\nWe will add Alubosa Elewe.\nWe will add Kafura.\nWe will close the container.\nWe will keep the preparation undisturbed for\nnine days.\n***USAGE***\nAfter the ninth day, we will add a small quantity\nof the prepared Omi into our bathing water\nwhenever traditionally required.\nSource:\nAsiri Nla - \"Omi Asina Todamiloju Biku.\""},{"id":"baba-146","source":"baba","sourceName":"OOGUN BABA OGUN","number":146,"title":"ORUKA ANASARE","subtitle":"(ANASARE RING)","preview":"ANASARE RING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eku Asin - 1\n-Oruka - 1\n-Eyo Atare - 2\n-Ori - shea butter\n***PREPARATION***\nWe will place the Oruka inside the mouth of the\nEku Asin as stated in the source.\nWe will add two Atare.\nThe source directs that the preparation be\nkept/buried for three days.\nAfter the third day, we will recover the Oruka.\n***USAGE***\nBefore putting the Oruka on the hand, the\nsource directs that Ori be rubbed on the hand.\nWe will then wear the prepared Oruka.\nSource:\nAsiri Nla - \"Oruka Anasare.\"\nNOTE:\nThis is different from the Anasare/Anosare\npreparations already associated with other\nrings in earlier sources."},{"id":"baba-147","source":"baba","sourceName":"OOGUN BABA OGUN","number":147,"title":"OSE ASIRI BIBO OSHOLE","subtitle":"(OSHOLE / ASIRI-BIBO SOAP)","preview":"OSHOLE / ASIRI-BIBO SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Odidi Ori Igun to pe dada - 1\n-Epo Obo\n-Ose Dudu\n-Igba Olomori\n-Obe Esu - 1\n***PREPARATION***\nWe will grind the Ori Igun thoroughly.\nWe will separately grind Epo Obo until fine.\nWe will combine the two preparations.\nWe will mix them thoroughly with Ose Dudu.\nWe will put the prepared soap inside an Igba\nOlomori.\nThe source directs placing one Obe Esu into/on\ntop of the prepared soap.\nWe will leave the preparation arranged in the\ncontainer as described.\n***USAGE***\nWe will take a small quantity of the soap and\nuse it for bathing in the morning.\nSource:\nAsiri Nla - \"Ose Asiri Bibo Oshole.\"\nNOTE:\nI have not replaced Igun with another bird. The\nsource specifically says Igun. Wildlife laws and\nhygiene should be observed."},{"id":"baba-148","source":"baba","sourceName":"OOGUN BABA OGUN","number":148,"title":"AWURE OKIKI","subtitle":"(FAME / RECOGNITION / PROMINENCE)","preview":"FAME / RECOGNITION / PROMINENCE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eyin Ororo - 1\n-Omi Agbon\n-Eepo Eyin from the cooked egg\n-Ipara\n-Lofinda\n***PREPARATION***\nWe will cook one Eyin Ororo using Omi Agbon.\nWhen the egg is completely cooked, we will eat\nthe egg.\nWe will retain its shell.\nWe will dry the shell properly.\nWe will grind the shell until it becomes a fine\npowder.\nWe will put part of the powder into Ipara.\nWe will put part into Lofinda.\nWe will mix both preparations thoroughly.\n***USAGE***\nWe will use the prepared Ipara on the body.\nWe will also apply the prepared Lofinda when\ngoing out.\nSource:\nAsiri Nla - \"Awure Okiki.\""},{"id":"baba-149","source":"baba","sourceName":"OOGUN BABA OGUN","number":149,"title":"AWORO ASORO","subtitle":"(AWORO ASORO WORKING)","preview":"AWORO ASORO WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ado Ato - 1\n-Afatan Irun Ori Wa - clipping of one's own hair\n-Iyo\n-Omi\n***PREPARATION***\nWe will take an Ado Ato.\nWe will collect a small clipping of our own hair.\nWe will put the hair inside the Ado.\nWe will add Iyo.\nWe will add a small quantity of Omi.\nWe will close the Ado securely.\n***USAGE***\nThe source identifies the prepared Ado as\nAWORO ASORO but does not clearly state a\nseparate carrying or placement instruction for\nthis first version.\nSource:\nAsiri Nla - \"Aworo Asoro.\"\nSOURCE NOTE:\nThe same source gives a second Aworo Asoro\nvariant immediately afterward, but several\nwords in that version are corrupted in the scan.\nI have not guessed the missing material names."},{"id":"baba-150","source":"baba","sourceName":"OOGUN BABA OGUN","number":150,"title":"AFERO","subtitle":"(AFERO / ATTRACTION TO A PLACE)","preview":"AFERO / ATTRACTION TO A PLACE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Fitila Oloju Kan - 2\n-Eran Elede Tutu\n-Ojulowo Oyin Gidi\n-Iyepe\n***PREPARATION***\nWe will prepare the place at the entrance where\npeople enter.\nWe will place one Fitila there.\nWe will place the fresh Eran Elede with it.\nWe will pour Ojulowo Oyin Gidi over the\npreparation.\nWe will place the second Fitila over/with the\nfirst preparation as stated in the source.\nWe will cover the arrangement with Iyepe.\nThe source specifies that the faces/openings of\nthe Fitila should face toward the inside of the\npremises.\n***USAGE***\nThe preparation is traditionally positioned at\nthe entrance of the house, shop or other\npremises as Afero.\nSource:\nAsiri Nla - \"Afero.\"\nNOTE:\nThe source describes placement/burial; it does\nnot instruct lighting the two Fitila in this\nformula."},{"id":"baba-151","source":"baba","sourceName":"OOGUN BABA OGUN","number":151,"title":"AFORAN ATIMOLE","subtitle":"(AFARAN / SETTLING A TROUBLESOME MATTER)","preview":"AFARAN / SETTLING A TROUBLESOME MATTER · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Ewe Iyalode\n-Ewe Ajeobale\n-Ose\n-Ori Ako Okuta\n***PREPARATION***\nWe will grind Epo Obo thoroughly.\nWe will mix it into the Ose.\nWe will separately prepare Ewe Iyalode and\nadd it to the same soap.\nWe will then prepare Ewe Ajeobale and mix it\ninto the soap.\nWe will mix everything thoroughly until the\npreparation is uniform.\n***USAGE***\nWe will place the prepared soap on Ori Ako\nOkuta when traditionally using it for bathing.\nThe source associates the working with\npleading for a troublesome matter or Aforan to\nbe settled.\nSource:\nPractitioner compilation - \"Aforan Eyonu Aye.\"\nSOURCE NOTE:\nThe catalogue title is AFORAN ATIMOLE.\nI did not recover the exact Atimole version, so\nthis is a separately documented Aforan formula\nand not claimed to be word-for-word identical."},{"id":"baba-152","source":"baba","sourceName":"OOGUN BABA OGUN","number":152,"title":"OOGUN TA FI MU ENI TO JI NKAN WA","subtitle":"(WORKING FOR RETURN OF STOLEN PROPERTY)","preview":"WORKING FOR RETURN OF STOLEN PROPERTY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Egele\n-Omonile - 1\n-Atare Aja - 1\n***PREPARATION***\nWe will combine Ewe Egele, one Omonile and\none Atare Aja.\nWe will prepare the three materials together as\nstated in the source.\n***USAGE***\nWe will place the prepared working at the\nparticular place from which the property was\ntaken.\nThe source attributes the preparation to making\nthe stolen item be returned.\nSource:\n7.pdf - \"Ti Won Ba Gbe Nkan Eyan Ti Won Fi\nNgbe Pada.\"\nNOTE:\nI selected this simpler return-property variant\ninstead of the other source that attempts to\ncause illness to the suspected thief."},{"id":"baba-153","source":"baba","sourceName":"OOGUN BABA OGUN","number":153,"title":"EYONU GBAYE GBORUN","subtitle":"(GENERAL / UNIVERSAL FAVOUR)","preview":"GENERAL / UNIVERSAL FAVOUR · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Rerinkomi\n-Odidi Atare - 1\n-Oyin Gidi - pure honey\n***PREPARATION***\nWe will combine Ewe Rerinkomi with one\nwhole Atare.\nWe will prepare the two materials thoroughly\ntogether.\nWe will put the resulting preparation into Oyin\nGidi.\nWe will mix it properly.\n***USAGE***\nThe source directs taking a small quantity of the\nhoney preparation early in the morning.\nSource:\nNew Asiri Aye - \"Eyonu Omo Araye.\"\nSOURCE NOTE:\nThe exact recipe under EYONU GBAYE GBORUN\nwas not recovered.\nThis is a separately documented Eyonu Omo\nAraye formula of the same general-favour class,\nnot a reconstructed hidden formula."},{"id":"baba-154","source":"baba","sourceName":"OOGUN BABA OGUN","number":154,"title":"OSO INU LUKUDI","subtitle":"(LUKUDI MONEY WORKING)","preview":"LUKUDI MONEY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Akuko Adie Asa - 1\n-Eyele Funfun - 1\n-Eyele Pupa - 1\n-Eyele Dudu - 1\n-Igba Olomori Nla - 1\n-Owo Eyo ti ko lu - 201\n-Eyin Pepeye - 16\n-Aso Funfun\n-Owu Funfun\n-Ekuru Funfun\n***PREPARATION***\nWe will put the Akuko Adie, three Eyele, 201\nOwo Eyo and sixteen Eyin Pepeye into the large\nIgba Olomori.\nWe will close the Igba securely.\nWe will wrap it with Aso Funfun.\nWe will bind the preparation firmly with Owu\nFunfun.\nThe source directs burying/placing it at Orita for\nnine days.\nOn the ninth day, we will recover the\npreparation.\nThe materials are then processed further as\ndescribed in the source until the preparation\nbecomes fine.\n***USAGE***\nThe source associates the finished preparation\nwith Ekuru Funfun and with its traditional Oso\nOwo purpose.\nSource:\nIda Oloju Meji - \"OSO INU LUKUDI TO DAJU.\"\nNOTE:\nIts claims of extraordinary wealth are\npractitioner claims, not independently\nestablished facts."},{"id":"baba-155","source":"baba","sourceName":"OOGUN BABA OGUN","number":155,"title":"ASIRI TI A FI BERE ORO LOJU ALA","subtitle":"(WORKING FOR ASKING A QUESTION IN A DREAM)","preview":"WORKING FOR ASKING A QUESTION IN A DREAM · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Oga Aye - 1\n-Iyo - small quantity\n-Ape Tuntun\n-Owu Akese\n-Owu Funfun\n-Lofinda Bintu\n***PREPARATION***\nThe source directs taking a small portion from\nthe tongue area of the Oga Aye.\nWe will put it inside a new Ape.\nWe will add a small quantity of Iyo.\nWe will process the material as stated by the\nsource.\nWe will put the resulting preparation inside\nOwu Akese.\nWe will wrap it securely with Owu Funfun.\nThe source says the Oga Aye is then returned to\nthe bush.\nLofinda Bintu is subsequently applied to the\nprepared working.\n***USAGE***\nWhen there is a particular matter we want\ntraditionally revealed in a dream, the source\ndirects placing the preparation beneath the\npillow before sleeping.\nIt is removed from under the pillow the\nfollowing morning.\nSource:\n7.pdf - \"ASIRI TI A FI BERE ORO LOJU ALA.\"\nNOTE:\nThis is recorded as a traditional dream-working\nclaim, not a reliable factual method of obtaining\ninformation."},{"id":"baba-156","source":"baba","sourceName":"OOGUN BABA OGUN","number":156,"title":"ASEJE OWO KIAKIA","subtitle":"(QUICK-MONEY ASEJE)","preview":"QUICK-MONEY ASEJE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Atewogba\n-Ata Ijosin - 7 for woman / 9 for man in the\nsource\n-Ponmo Kika\n-Isasun Aseje Tuntun\n-Epo\n-Iyo\n***PREPARATION***\nWe will grind Ewe Atewogba together with the\nAta Ijosin.\nWe will place the ground preparation inside a\nnew Isasun Aseje.\nWe will cut the Ponmo into the corresponding\nnumber of portions.\nWe will place the Ponmo over the herbal\npreparation.\nWe will cook everything together with Epo and\nIyo.\nWhen it is properly cooked, we will remove it\nfrom the fire.\nWe will place the pot on an Osuka and allow the\nfood to cool.\n***USAGE***\nThe source directs making the desired money\nprayer over the preparation and then eating it.\nSource:\n\"Aseje Owo Kiakia\" practitioner\ndocument. :contentReference[oaicite:0]\n{index=0}"},{"id":"baba-157","source":"baba","sourceName":"OOGUN BABA OGUN","number":157,"title":"EYONU OWO KIAKIA","subtitle":"(MONEY FAVOUR)","preview":"MONEY FAVOUR · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Lapalapa Funfun\n-Ewe Iyeye\n-Ewe Akoko\n-Ewe Ewuro\n-Omi - about 5 litres in the source\n-Lofinda St. Paris\n***PREPARATION***\nWe will combine Ewe Lapalapa Funfun, Ewe\nIyeye, Ewe Akoko and Ewe Ewuro.\nWe will boil/soak the leaves together in the\nstated quantity of water.\nWe will strain the liquid so that no dirt remains.\nWe will add Lofinda St. Paris.\nWe will keep the prepared liquid inside a clean\ncontainer.\n***USAGE***\nWe will add a small quantity of the preparation\nto bathing water when traditionally required.\nSource:\nNew Asiri Aye - \"EYONU OWO.\"\nSOURCE NOTE:\nThe accessible formula is titled EYONU OWO\nrather than EYONU OWO KIAKIA.\nI have therefore retained that distinction\ninstead of inventing the word \"Kiakia\" into the\nsource."},{"id":"baba-158","source":"baba","sourceName":"OOGUN BABA OGUN","number":158,"title":"ATUDE OWO KIAKIA","subtitle":"(ATUDE / OPENING THE WAY FOR MONEY)","preview":"ATUDE / OPENING THE WAY FOR MONEY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Exact materials under this complete title were\nnot recovered.\n***PREPARATION***\nATUDE OWO KIAKIA appears in the catalogue\nas a distinct named preparation.\nI searched Atude Owo, Atude Asina and Owo\nKiakia variants, but none could be securely\nidentified as this precise formula.\n***USAGE***\nNot disclosed in the source available to me.\nSource:\nAsiri Nla contents list.\nNOTE:\nI am deliberately not repeating one of the many\nAtude / Asina formulas already sent in Nos. 93-\n97, 127 and elsewhere simply to fill this entry."},{"id":"baba-159","source":"baba","sourceName":"OOGUN BABA OGUN","number":159,"title":"ABAMODA OWO KIAKIA","subtitle":"(ABAMODA QUICK-MONEY WORKING)","preview":"ABAMODA QUICK-MONEY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ako Alangba to pon dada - 3\n-Odidi Atare Nla - 1\n-Ape Ijogun\n-Emu\n-Schnapps\n***PREPARATION***\nWe will remove the heads of the three Ako\nAlangba.\nWe will arrange the three heads inside an Ape\nIjogun.\nWe will put one large whole Atare over them.\nWe will process the materials together as\ndescribed in the source.\nWhen completely prepared, we will grind the\nresulting material thoroughly into a fine\npowder.\n***USAGE***\nThe practitioner source describes putting the\npowder on the left palm at night while making\nthe money request.\nIt subsequently directs putting the material into\nEmu and taking Schnapps afterward.\nSource:\n\"Ogun Owo Kiakia: Ewe ati Asiri\" - \"ABAMODA\nOWO KIAKIA.\" :contentReference[oaicite:1]\n{index=1}\nIMPORTANT:\nDo not ingest burnt lizard remains or\nunidentified ritual powders. This is presented as\ndocumentation of the traditional source, not as\na safe consumable preparation."},{"id":"baba-160","source":"baba","sourceName":"OOGUN BABA OGUN","number":160,"title":"ASEJE BIBO ASIRI","subtitle":"(EDIBLE ASIRI-BIBO WORKING)","preview":"EDIBLE ASIRI-BIBO WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Abamoda\n-Ata Ijosin\n-Oju Malu Mejeji - both cow eyes\n-Isasun Aseje Tuntun\n-Epo\n-Iyo\n***PREPARATION***\nWe will grind Ewe Abamoda together with Ata\nIjosin.\nWe will place the prepared materials inside a\nnew Isasun Aseje.\nWe will add both Oju Malu.\nWe will add Epo and Iyo.\nWe will cook the preparation thoroughly as an\nAseje.\n***USAGE***\nThe source directs that the prepared Aseje\ntraditionally be eaten for Bibo Asiri.\nSource:\nNew Asiri Aye - \"ASEJE ASIRI BIBO FUN\nOHUNKOHUN.\""},{"id":"baba-161","source":"baba","sourceName":"OOGUN BABA OGUN","number":161,"title":"OOGUN ARISIKI PATAKI","subtitle":"(PROSPECT / PROSPERITY WORKING)","preview":"PROSPECT / PROSPERITY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eye Ega - 1\n-Ikode - 1\n-Odidi Atare - 1\n***PREPARATION***\nWe will take one Eye Ega.\nWe will place the Ikode with it as described in\nthe source.\nWe will add one whole Atare.\nWe will put all three materials inside an\nAgbada.\nWe will burn them together.\nWe will grind the burnt preparation thoroughly\nuntil it becomes fine.\n***USAGE***\nThe source directs that the preparation\ntraditionally be taken once with Eko.\nSource:\nNew Asiri Aye - \"Ogun Arisiki.\"\nSOURCE NOTE:\nThe catalogue title is OOGUN ARISIKI PATAKI.\nThis is a separately documented Ogun Arisiki\nformula rather than an invented reconstruction\nof the unavailable exact \"Pataki\" version.\nIMPORTANT:\nDo not ingest unidentified burnt animal or plant\nmaterial."},{"id":"baba-162","source":"baba","sourceName":"OOGUN BABA OGUN","number":162,"title":"EBU ISORA","subtitle":"(PROTECTIVE POWDER)","preview":"PROTECTIVE POWDER · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Korofo Eyin Adiye Ibile ti o pa omo fun ara re\n-Ewe Patanmo - plenty\n-Odidi Atare - 1\n-Epo Pupa - palm oil\n***PREPARATION***\nWe will combine the Korofo Eyin Adiye, plenty\nof Ewe Patanmo and one whole Atare.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly\nuntil it becomes a fine Ebu.\n***USAGE***\nThe source directs putting a small quantity of\nthe Ebu into Epo Pupa.\nIt is traditionally licked in a small quantity as an\nIsora preparation.\nSource:\nIwe Asiri Ti Ogun Nfi Je, Volume One - \"Ebu\nIsora.\"\nIMPORTANT:\nThis is documentation of a traditional formula.\nDo not ingest burnt unidentified herbs or\ncontaminated eggshell preparations."},{"id":"baba-163","source":"baba","sourceName":"OOGUN BABA OGUN","number":163,"title":"OOGUN AROBI DAN","subtitle":"(AROBI / REMOVING AROBI)","preview":"AROBI / REMOVING AROBI · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Eedu Oju Aro\n-Eeru Oju Aro\n-Ose Dudu - black soap\n***PREPARATION***\nWe will grind Epo Obo together with Eedu Oju\nAro until it becomes fine.\nWe will add Eeru Oju Aro.\nWe will combine the preparation thoroughly\nwith Ose Dudu.\n***USAGE***\nThe source directs using the soap for bathing at\nnight.\nIt specifies using warm/hot water for the bath.\nSource:\nOogun Yoruba - \"Arobi Danu Togbona Dada.\"\nSOURCE NOTE:\nThis is distinct from the Ewe Etiponla / Alupaida\nArobi formula previously sent as No. 109."},{"id":"baba-164","source":"baba","sourceName":"OOGUN BABA OGUN","number":164,"title":"OOGUN KI AJE MA WOLE","subtitle":"(TRADITIONAL HOUSE PROTECTION)","preview":"TRADITIONAL HOUSE PROTECTION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Epo Obo\n-Ekuru\n-Ikarahun Igbin - snail shell\n-Nylon\n***PREPARATION***\nWe will combine Epo Obo with Ekuru.\nWe will put the preparation inside an Ikarahun\nIgbin.\nWe will wrap or protect the prepared shell with\nNylon.\n***USAGE***\nThe source directs placing/burying the prepared\nshell at the entrance of the house.\nSource:\n7.pdf - \"Ki Emi Buruku Ma Wo Inu Ile.\"\nSOURCE NOTE:\nThe exact Asiri Nla title is OOGUN KI AJE MA\nWOLE.\nThe detailed source I recovered calls this\nversion \"Ki Emi Buruku Ma Wo Inu Ile,\" so I am\npresenting it as a closely related house￾protection formula rather than falsely claiming\nthe two headings are identical."},{"id":"baba-165","source":"baba","sourceName":"OOGUN BABA OGUN","number":165,"title":"ASEJE ASINA EYONU","subtitle":"(EDIBLE ASINA / EYONU PREPARATION)","preview":"EDIBLE ASINA / EYONU PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Tangiri\n-Iyere\n-Eran Malu\n***PREPARATION***\nWe will grind Ewe Tangiri and Iyere thoroughly\ntogether.\nWe will cut the Eran Malu into suitable pieces.\nWe will use the ground herbal preparation in\npreparing the Eran Malu as Aseje.\n***USAGE***\nThe source directs eating the prepared Aseje\ntraditionally for Eyonu.\nSource:\nNew Asiri Aye - \"Aseje Eyonu.\"\nSOURCE NOTE:\nThe catalogue calls No. 165 ASEJE ASINA\nEYONU.\nThe recovered preparation is headed ASEJE\nEYONU, so I have not added ingredients that are\nnot in the source.\nIMPORTANT:\nOnly edible, correctly identified plants should\never be used in food."},{"id":"baba-166","source":"baba","sourceName":"OOGUN BABA OGUN","number":166,"title":"OBE OSOLE ASIRI BIBO","subtitle":"(EDIBLE OSOLE / ASIRI-BIBO PREPARATION)","preview":"EDIBLE OSOLE / ASIRI-BIBO PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Tannaposo Tutu\n-Ewe Etiponola Tutu\n-Iyere - 16 or more\n-Igbin Apinu - 2\n-Epo\n-Iyo\n-Iyerosun\n***PREPARATION***\nWe will grind Ewe Tannaposo, Ewe Etiponola\nand Iyere thoroughly together.\nWe will prepare two Igbin Apinu whole as\ndirected by the source.\nWe will cook the preparation together with Epo\nand Iyo.\nWhen it is cooked, we will place the preparation\non an Osuka.\nThe source then associates the preparation with\nEjiogbe using Iyerosun.\n***USAGE***\nThe source directs that the prepared food\ntraditionally be eaten after the associated\nprayer.\nSource:\nNew Asiri Aye - \"Obe Osole Asiri Bibo.\"\nNOTE:\nI have kept the plant name Tannaposo exactly\nas it appears in the source rather than guessing\nits botanical identity."},{"id":"baba-167","source":"baba","sourceName":"OOGUN BABA OGUN","number":167,"title":"APASE ASEJE","subtitle":"(APASE EDIBLE PREPARATION)","preview":"APASE EDIBLE PREPARATION · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Oka - 1\n-Itaku Akese\n-Ata\n***PREPARATION***\nWe will combine Ori Oka and Itaku Akese.\nWe will grind the two materials thoroughly\ntogether.\nWe will add Ata.\nWe will use the preparation in making an Aseje.\n***USAGE***\nThe source directs eating the prepared Aseje.\nIt traditionally attributes Apase qualities to the\npreparation.\nSource:\nNew Asiri Aye - \"Apase Aseje.\"\nIMPORTANT:\nOri Oka and Itaku Akese are source terms\nwhose safe edible identity is not established\nhere. Do not consume unidentified animal or\nplant materials."},{"id":"baba-168","source":"baba","sourceName":"OOGUN BABA OGUN","number":168,"title":"AWURE APEFIJI","subtitle":"(AWURE / FAVOUR WORKING)","preview":"AWURE / FAVOUR WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Ako Ologbo\n-Ewe Oriji\n-Odidi Atare - 1\n-Iye Agbe - 1\n-Iye Aluko - 1\n-Ikode - 1\n-Owo Paper\n-Ileke Itun\n-Ileke Ifa\n-Abere\n-Irun Abe Obirin\n-Ose\n-Igba\n***PREPARATION***\nWe will first combine Ori Ako Ologbo, Ewe Oriji\nand one whole Atare.\nWe will burn the three materials and grind\nthem thoroughly.\nWe will separately prepare Iye Agbe, Iye Aluko,\nIkode, Owo Paper, Ileke Itun, Ileke Ifa, Abere\nand Irun Abe Obirin.\nWe will combine this second set with the first\nburnt preparation.\nWe will mix the resulting preparation\nthoroughly with Ose.\nWe will put the prepared soap inside an Igba.\n***USAGE***\nThe source directs using the prepared soap for\nbathing.\nSource:\nNew Asiri Aye - \"Awure Apefiji.\"\nNOTE:\nHuman hair and animal remains can carry\ncontaminants; this is recorded as a traditional\nformula, not a hygiene-safe recommendation."},{"id":"baba-169","source":"baba","sourceName":"OOGUN BABA OGUN","number":169,"title":"OSO ADERA","subtitle":"(ADERA / PROSPERITY OSO)","preview":"ADERA / PROSPERITY OSO · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eran Elede - large piece\n-Omunu Ewe Ewuro oojo\n-Oyin Igan - pure honey\n-Ose\n-Lofinda Bintu\n-Apo Asunwon Aso Funfun\n***PREPARATION***\nWe will combine the Eran Elede and Omunu\nEwe Ewuro.\nWe will process the materials until they become\nfine as described in the source.\nWe will mix the preparation thoroughly with\nOse.\nWe will use Oyin Igan in mixing the soap.\nWe will add Lofinda Bintu.\nWe will put the finished preparation inside an\nApo Asunwon made from Aso Funfun.\nWe will hang/store the bag so that it does not\ntouch the ground.\n***USAGE***\nThe source directs bathing with the preparation\non the last Thursday of the month.\nSource:\nNew Asiri Aye - \"Oso Adera.\""},{"id":"baba-170","source":"baba","sourceName":"OOGUN BABA OGUN","number":170,"title":"EBU EYONU","subtitle":"(EYONU POWDER)","preview":"EYONU POWDER · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Itanna Imi Esu - plenty\n-Odidi Atare - 1\n-Isu - yam\n-Ikoko\n***PREPARATION***\nWe will collect plenty of Itanna Imi Esu.\nWe will burn it together with one whole Atare.\nWe will grind the burnt materials thoroughly\ninto a fine Ebu.\nWe will keep the prepared Ebu dry for use.\n***USAGE***\nWhen traditionally required, we will put a small\nquantity of the Ebu at the bottom of an Ikoko.\nWe will cut Isu into nine small slices.\nWe will add the yam to the pot with water and\ncook it.\nThe source then directs eating the cooked yam.\nSource:\nNew Asiri Aye - \"Ebu Eyonu.\"\nIMPORTANT:\nDo not contaminate food with unidentified\nburnt plant ash unless the material has been\npositively identified as food-safe."},{"id":"baba-171","source":"baba","sourceName":"OOGUN BABA OGUN","number":171,"title":"OSOLE","subtitle":"(OSOLE / MONEY WORKING)","preview":"OSOLE / MONEY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Opolo Gbigbe - 3\n-Alakan Gbigbe - 3\n-Oga Gbigbe - 3\n-Odidi Atare - 1\n-Oti Oyinbo\n***PREPARATION***\nWe will combine the three Opolo Gbigbe, three\nAlakan Gbigbe, three Oga Gbigbe and one whole\nAtare.\nWe will grind all the materials together\nthoroughly until the preparation becomes fine.\n***USAGE***\nWe will put approximately one spoonful of the\npreparation into Oti Oyinbo when traditionally\nusing it.\nSource:\nNew Asiri Aye - \"Osole.\"\nNOTE:\nThe web OCR renders Atare as \"estate\"; I have\ncorrected the obvious OCR spelling without\nchanging the ingredient."},{"id":"baba-172","source":"baba","sourceName":"OOGUN BABA OGUN","number":172,"title":"AFOSE MAYEHUN","subtitle":"(SPOKEN-AUTHORITY / MAYEHUN WORKING)","preview":"SPOKEN-AUTHORITY / MAYEHUN WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Irun Were\n-Aso Were\n-Yerepe\n-Materials for Ikobere\n***PREPARATION***\nWe will combine Irun Were and Aso Were.\nWe will grind them thoroughly together.\nWe will add Yerepe to the preparation.\nWe will wrap and prepare the resulting\nmaterial as an Ikobere.\n***USAGE***\nThe prepared Ikobere is traditionally used\nwhen speaking the matter or request for which\nthe Afose Mayehun is intended.\nSource:\nNew Asiri Aye - \"Afose Mayehun.\""},{"id":"baba-173","source":"baba","sourceName":"OOGUN BABA OGUN","number":173,"title":"OSO OWO","subtitle":"(MONEY / PROSPERITY WORKING)","preview":"MONEY / PROSPERITY WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Pali Oti Schnapps - empty Schnapps container\n-Ewe Etiponla\n-Odidi Atare - 1\n-Oti\n***PREPARATION***\nWe will take an empty Pali Oti Schnapps.\nWe will put Ewe Etiponla into it until\napproximately halfway filled.\nWe will add one whole Atare.\nWe will add more Ewe Etiponla until the\ncontainer is filled.\nWe will close the preparation securely.\n***USAGE***\nThe source associates the finished preparation\nwith Oti when traditionally used for Oso Owo.\nSource:\nNew Asiri Aye - \"Oso Owo.\""},{"id":"baba-174","source":"baba","sourceName":"OOGUN BABA OGUN","number":174,"title":"EYONU ASINA","subtitle":"(FAVOUR + OPENING OF THE WAY)","preview":"FAVOUR + OPENING OF THE WAY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eye Kowe Dudu - 1\n-Oga Gbigbe - 1\n-Opolo Gbigbe - 1\n-Asin Gbigbe - 1\n-Obi Abata Oloju Merin - 1\n-Orogbo - 1\n-Odidi Atare - 1\n-Epo Pupa\n***PREPARATION***\nWe will combine Eye Kowe Dudu, Oga Gbigbe,\nOpolo Gbigbe, Asin Gbigbe, Obi Abata, Orogbo\nand one whole Atare.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly\ninto fine powder.\n***USAGE***\nThe source directs taking a small quantity\ntraditionally with Epo Pupa at night before\nsleeping.\nSource:\nNew Asiri Aye - \"Eyonu Asina To Daju.\""},{"id":"baba-175","source":"baba","sourceName":"OOGUN BABA OGUN","number":175,"title":"AJEGUN KI OWO DURO LOWO","subtitle":"(AJEGUN / RETAINING MONEY)","preview":"AJEGUN / RETAINING MONEY · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ase Oga\n-Ewe Alupaida - 9\n-Eyo Atare - 9\n***PREPARATION***\nWe will combine Ase Oga, nine Ewe Alupaida\nand nine Atare.\nWe will grind all the materials thoroughly\ntogether until they become fine.\n***USAGE***\nThe source directs applying the preparation\nthrough traditional Gbere around both wrists.\nSource:\nNew Asiri Aye -\n\"Ajegun Totun Man Sise Ki Owo Le Duro Lowo\nWa.\"\nNOTE:\nGbere means cutting/marking the skin. Skin\ncutting carries infection and blood-borne\ndisease risks."},{"id":"baba-176","source":"baba","sourceName":"OOGUN BABA OGUN","number":176,"title":"EYONU TI A NFI RI ALANU","subtitle":"(FAVOUR FOR MEETING A HELPER / BENEFACTOR)","preview":"FAVOUR FOR MEETING A HELPER / BENEFACTOR · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ewe Ewuro oojo\n-Epo Obo - small quantity\n-Imi Orun\n-Ose Dudu OR Ose Ghana\n-Owo Eyo - 1\n***PREPARATION***\nWe will prepare Ewe Ewuro, Epo Obo and Imi\nOrun separately until fine.\nWe will combine the three materials.\nWe will mix the preparation thoroughly into\neither Ose Dudu or Ose Ghana.\nWe will place one Owo Eyo on the prepared\nsoap.\n***USAGE***\nWe will use the prepared soap for bathing in the\nmorning.\nThe source traditionally associates it with\nmeeting an Alaanu who can assist with one's\nneeds.\nSource:\nNew Asiri Aye -\n\"Ise Iyonu Ti A Nfi Pade Alaanu Tiyio Hiya\nBukata Wa.\""},{"id":"baba-177","source":"baba","sourceName":"OOGUN BABA OGUN","number":177,"title":"IMULE TI NSI ONA OWO NLA","subtitle":"(IMULE FOR OPENING THE WAY TO LARGE MONEY / CONNECTIONS)","preview":"IMULE FOR OPENING THE WAY TO LARGE MONEY / CONNECTIONS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Iyere Osun\n-Isasun Nla Tuntun\n-Eye Kowe Dudu - 3\n-Oga Gbigbe Nla - 3\n-Eku Asin - 3\n-Opolo Nla - 3\n-Odidi Atare - 3\n-Epo Pupa\n-Oti\n***PREPARATION***\nWe will use Iyere Osun to mark Osa Meji inside\na new large Isasun.\nWe will place three Eye Kowe Dudu inside.\nWe will add three Oga Gbigbe Nla.\nWe will add three Eku Asin.\nWe will add three Opolo Nla.\nWe will add three whole Atare.\nWe will burn the materials together.\nWe will grind the resulting preparation\nthoroughly.\n***USAGE***\nThe source describes using a small quantity\ntraditionally with Epo Pupa at night.\nIt also describes Oti as part of its early-morning\nuse.\nSource:\nNew Asiri Aye -\n\"Imule Toma Nsina Owo Nla, Yio Tun Ma\nConnect Wa Mo Awon Eyan Nlanla.\""},{"id":"baba-178","source":"baba","sourceName":"OOGUN BABA OGUN","number":178,"title":"OSE AJEGUN","subtitle":"(AJEGUN SOAP)","preview":"AJEGUN SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eja Ojiji Aye - 1\n-Ewe Owu Akese Pupa oojo\n-Ose Dudu\n-Ike Olomori Funfun Nla\n***PREPARATION***\nWe will collect fresh Ewe Owu Akese Pupa.\nWe will pound the leaves thoroughly until they\nbecome fine.\nWe will mix them properly with Ose Dudu.\nWe will place the Eja Ojiji inside a large white\ncovered container.\nWe will put the prepared soap over the Eja Ojiji.\nWe will close the container.\nWe will keep the preparation undisturbed for\nseven days.\n***USAGE***\nAfter the seventh day, the source directs using\nthe prepared soap for bathing.\nSource:\nNew Asiri Aye - \"Ose Ajegun Todaju Pa.\""},{"id":"baba-179","source":"baba","sourceName":"OOGUN BABA OGUN","number":179,"title":"EYONU OBA AWON AGBALAGBA","subtitle":"(EYONU / EBE AWON AGBALAGBA)","preview":"EYONU / EBE AWON AGBALAGBA · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Eepo Obo\n-Eso Lahaa Funfun\n-Ewe Ajeobale oojo\n-Odidi Atare - 1\n-Iyere Osun\n-Paper Funfun\n-Eko\n***PREPARATION***\nWe will put Eepo Obo inside an Ape.\nWe will place Eso Lahaa Funfun over it.\nWe will add fresh Ewe Ajeobale.\nWe will add one whole Atare.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly.\n***USAGE***\nWe will put a small quantity of the preparation\ninside white paper.\nThe source associates it with Osa Meji.\nIt traditionally directs taking a small quantity\nwith Eko at night.\nSource:\nNew Asiri Aye -\n\"Eyonu Ebe Awon Agbalagba Todaju.\""},{"id":"baba-180","source":"baba","sourceName":"OOGUN BABA OGUN","number":180,"title":"MOTULE KAN OSE ASIRI BIBO","subtitle":"(ANU / ASIRI-BIBO SOAP)","preview":"ANU / ASIRI-BIBO SOAP · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Agbon - 1\n-Eepo Obo\n-Ose Dudu\n-Omi Agbon\n-Ikarahun Agbon / the coconut shell\n-Ike\n***PREPARATION***\nWe will take one Agbon and divide it into two.\nWe will grind Eepo Obo thoroughly.\nWe will mix the Eepo Obo properly with Ose\nDudu.\nWe will use the Omi Agbon to mix the soap.\nWe will put the prepared soap back inside the\ncoconut shell.\nWe will close the shell with its other half.\nWe will place the prepared coconut inside an\nIke because the shell will continue to release\nmoisture.\n***USAGE***\nThe source directs taking a portion of the\nprepared soap for bathing in the morning.\nSource:\nNew Asiri Aye -\n\"Ose Anu Bibo Asiri / Motule Kan Ose Asiri\nBibo.\""},{"id":"baba-181","source":"baba","sourceName":"OOGUN BABA OGUN","number":181,"title":"IWE ASINA AWON AGBA","subtitle":"(ASINA AWON AGBA / OPENING BLOCKED WAYS)","preview":"ASINA AWON AGBA / OPENING BLOCKED WAYS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Ologbo ti o ni irun - 2\n-Ewe Orijin\n-Ewe Ajeobale\n-Owo Tuntun Nla - 1\n-Odidi Atare - 1\n-Ape\n***PREPARATION***\nWe will place one new currency note at the\nbottom of the Ape.\nWe will arrange the two Ori Ologbo inside the\nApe.\nWe will put one whole Atare beside them.\nWe will cover the preparation with Ewe Orijin\nand Ewe Ajeobale.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly\ninto a fine preparation.\n***USAGE***\nThe source says a small quantity is traditionally\nused very early in the morning before speaking\nto anybody.\nSource:\nEji-Ogbe Ewe Nje - \"ASINA AWON AGBA GIDI.\"\nSOURCE NOTE:\nThe catalogue says IWE ASINA AWON AGBA.\nThe independently recovered internet formula\nis headed ASINA AWON AGBA GIDI, so I am not\npretending the titles are word-for-word\nidentical."},{"id":"baba-182","source":"baba","sourceName":"OOGUN BABA OGUN","number":182,"title":"EGUN EPE","subtitle":"(WASHING AWAY EGUN / EPE)","preview":"WASHING AWAY EGUN / EPE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Omi Agbon - plenty\n-Ogun / piece of iron\n-Ose Dudu - black soap\n-Kanrinkan Tuntun - new sponge\n***PREPARATION***\nWe will collect enough Omi Agbon.\nThe traditional source heats a piece of iron\nstrongly and quenches it in the liquid.\nThe material associated with the quenching is\nprocessed on a grinding stone.\nWe will combine the resulting preparation with\nOse Dudu.\nWe will use Omi Agbon to mix the soap\nthoroughly.\n***USAGE***\nThe source directs taking a new sponge and\nbathing with the prepared soap at a flowing\nriver.\nAfter the bath, the sponge is traditionally\nallowed to go away with the flowing water.\nSource:\nPublic Yoruba practitioner discussion -\n\"OMI APEGUNRUN / pa egun, epe ati ise run.\"\nSOURCE NOTE:\nThis is not taken from New Asiri Aye.\nThe source specifically describes the\npreparation as being for removing EGUN and\nEPE.\nSAFETY:\nDo not handle red-hot metal with bare hands;\nthe old source describes an unsafe practice that\ncan cause severe burns."},{"id":"baba-183","source":"baba","sourceName":"OOGUN BABA OGUN","number":183,"title":"ASETA ARE EPE AROBI","subtitle":"(AROBI / ASETA AGAINST HOSTILE WORKINGS)","preview":"AROBI / ASETA AGAINST HOSTILE WORKINGS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ori Aparo - 11\n-Orogbo - 11\n-Obi Ipa Oloju Merin - 11\n-Obi Ifin Oloju Merin - 11\n-Atare - 11\n-Seere\n-Iyerosun / Ifa preparation\n***PREPARATION***\nWe will combine the eleven Ori Aparo, eleven\nOrogbo, eleven Obi Ipa, eleven Obi Ifin and\neleven Atare.\nWe will burn the materials together.\nWe will grind the resulting preparation\nthoroughly.\nThe source associates it with Ejiogbe.\nWe will put the finished preparation inside a\nSeere.\nThe source states that the Seere should\nthereafter not touch the ground.\n***USAGE***\nThe traditional source says a small quantity is\ntaken with Eko Tutu or Omi Tutu.\nSource:\nPublic Yoruba practitioner discussion -\n\"AROBI / ASETA / HUNT-THE-HUNTERS.\"\nSOURCE NOTE:\nThis is a separately documented Arobi/Aseta\nformula outside New Asiri Aye.\nIt is the closest independently published\nformula I found for catalogue No. 183.\nSAFETY:\nDo not ingest unidentified burnt animal or plant\nmaterials."},{"id":"baba-184","source":"baba","sourceName":"OOGUN BABA OGUN","number":184,"title":"IMULE ELEYE","subtitle":"(IMULE ELEYE / AWON ELEYE WORKING)","preview":"IMULE ELEYE / AWON ELEYE WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Apa Osi Aguntan\n-Eku Asin - 16\n-Oga - 16\n-Opolo - 16\n-Eso Ego / Eso Ori Langbodo - plenty\n-Ewe Aluki - plenty\n-Odidi Atare - 16\n-Ape Tuntun\n-Iyerosun\n***PREPARATION***\nWe will place Apa Osi Aguntan at the bottom of\na new Ape.\nWe will add sixteen Eku Asin.\nWe will add sixteen Oga.\nWe will add sixteen Opolo.\nWe will add plenty of Eso Ego / Eso Ori\nLangbodo.\nWe will add Ewe Aluki.\nWe will add sixteen whole Atare.\nWe will burn the preparation together.\nWe will grind it thoroughly.\nThe source associates the preparation with Osa\nMeji.\n***USAGE***\nThe source traditionally directs taking a small\nquantity with Eko Tutu.\nSource:\nYara Asiri Worldwide -\n\"OSO IMULE ELEIYE NLA.\"\nNOTE:\nThis is traditional spiritual documentation only.\nThe claimed effect is not independently\nestablished, and the preparation should not be\ningested because it contains unidentified animal\nand plant material."},{"id":"baba-185","source":"baba","sourceName":"OOGUN BABA OGUN","number":185,"title":"PEGUNRE / PEGUNRUN","subtitle":"(REMOVING ISE, OSI AND BAD CONDITIONS)","preview":"REMOVING ISE, OSI AND BAD CONDITIONS · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Egbo Akoko\n-Ewe Akoko\n-Epo Akoko\n-Ikode - 1\n-Ose Dudu\n***PREPARATION***\nWe will collect the root, leaves and bark from\nthe same Igi Akoko.\nWe will combine them with one Ikode.\nWe will pound the materials thoroughly\ntogether.\nWe will mix the preparation properly with Ose\nDudu.\nWhen traditionally preparing a portion for use,\nthe source associates it with Obara Dagise Nu.\n***USAGE***\nWe will use the prepared soap for bathing.\nThe source associates it with washing away Ise,\nOsi and unwanted conditions.\nSource:\nPublic Yoruba practitioner thread -\n\"IFA IWE ISE ATI OSI DANU / OBARA DAGISE\nNU.\"\nSOURCE NOTE:\nA discussion in the same source specifically\nexplains that Igi Akoko is also called PEGUNRUN\nin this working.\nThis provides a direct link to catalogue No. 185\nPEGUNRE."},{"id":"baba-186","source":"baba","sourceName":"OOGUN BABA OGUN","number":186,"title":"ETIAGBEKO","subtitle":"(HANGING / ENTRY-PROTECTION WORKING)","preview":"HANGING / ENTRY-PROTECTION WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Owo Eyo - 1\n-Atare - 3\n-Ori Pepeye\n-Ese Pepeye Mejeji\n-Odidi Atare - 2 additional\n-Ewe Iyalode\n-Aso Dudu\n-Isasun Tuntun\n-Ado Ijamo\n-Irun Ori - small quantity\n***PREPARATION***\nWe will prepare a new Isasun.\nWe will arrange the Ori Pepeye and its two legs\ninside.\nWe will add the Atare.\nWe will cover the materials with Ewe Iyalode.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly\ninto powder.\nWe will prepare the Owo Eyo with the\nremaining Atare.\nWe will put a little Irun Ori inside an Ado Ijamo.\nWe will add the prepared Owo Eyo and the\nburnt powder.\nWe will seal the mouth of the Ado with Aso\nDudu.\n***USAGE***\nThe related source keeps/places the completed\nAdo as a protective Igbeko preparation for a\nhouse or office.\nSource:\nIgbo Dudu Herbal Practice Guide -\n\"ADO IGBEKO AGBARA.\"\nIMPORTANT SOURCE NOTE:\nThe academic source defines ETIAGBEKO\nspecifically as a charm that is HUNG to hinder\nentry.\nThe detailed formula above is independently\ntitled ADO IGBEKO AGBARA.\nI have therefore treated it as a related Igbeko\npreparation, NOT claimed that it is the exact\nhidden Etiagbeko formula."},{"id":"baba-187","source":"baba","sourceName":"OOGUN BABA OGUN","number":187,"title":"ETIAKANMOLE","subtitle":"(BURIED ENTRY-PROTECTION WORKING)","preview":"BURIED ENTRY-PROTECTION WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Ado Ijamo - 1\n-Ewe Iyalode Funfun\n-Epo Obo - small quantity\n-Iyepe Orita Meta - small quantity\n-Iyepe Ago Kan Oru\n-Iyepe Ori Oro\n-Eedu Ina - small quantity\n-Epo Pupa - small quantity\n-Igi Ajeobale OR Egbo Ajeobale\n-Aso Dudu / Awo Dudu\n***PREPARATION***\nWe will put a small quantity of Iyepe Ago Kan\nOru inside the Ado.\nWe will add Iyepe Orita Meta.\nWe will add Iyepe Ori Oro.\nWe will add a little Epo Obo.\nWe will add Eedu Ina.\nWe will put Ewe Iyalode Funfun inside.\nWe will add a small quantity of Epo Pupa.\nWe will close the Ado with Igi Ajeobale or Egbo\nAjeobale.\nWe will wrap the completed Ado with Aso Dudu\nor Awo Dudu.\n***USAGE***\nThe related source directs placing/burying the\ncompleted preparation at the entrance of the\nhouse.\nSource:\nIgbo Dudu Herbal Practice Guide -\nburied entrance-protection Ado.\nIMPORTANT SOURCE NOTE:\nAcademic research defines ETIAKANMOLE as a\ncharm BURIED UNDERGROUND to hinder\ncriminal entry.\nThe formula above is the closest independently\nsourced buried-entry preparation I found.\nI am not claiming that its original heading was\nliterally ETIAKANMOLE."},{"id":"baba-188","source":"baba","sourceName":"OOGUN BABA OGUN","number":188,"title":"IJAYA","subtitle":"(DREAD / FEAR WORKING)","preview":"DREAD / FEAR WORKING · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Etu - composition not disclosed by the source\n-Ikobere - composition not disclosed by the\nsource\n***PREPARATION***\nThe independent source lists a preparation\ncalled ERU IJAYA and states that it consists of\nEtu and Ikobere.\nIt does not reveal how either component is\nmanufactured.\n***USAGE***\nThe source classifies it as a traditional working\nassociated with causing fear or dread.\nSource:\nAkose/Ogun practitioner compilation - \"ERU\nIJAYA.\"\nAcademic crime-prevention research\nindependently records IJAYA as a traditional\nworking associated with frightening.\nNOTE:\nI did not invent ingredients for IJAYA because\nthe public source does not disclose the contents\nof its Etu or Ikobere."},{"id":"baba-189","source":"baba","sourceName":"OOGUN BABA OGUN","number":189,"title":"ERU","subtitle":"(FEAR)","preview":"FEAR · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Etu - exact composition not disclosed\n-Ikobere - exact composition not disclosed\n***PREPARATION***\nThe public formula source combines ERU and\nIJAYA under the heading ERU IJAYA.\nIt identifies Etu and Ikobere but does not give\nthe formula used to prepare either one.\n***USAGE***\nERU is independently recorded in academic\nresearch as a traditional category associated\nwith fear.\nThe practitioner source treats ERU IJAYA as one\ncombined working.\nSource:\nAssessment of Faith-Based Crime Preventive\nMeasures in Ifo, Ogun State.\nAkose/Ogun practitioner compilation - \"ERU\nIJAYA.\"\nNOTE:\nI found no reliable public source outside New\nAsiri Aye giving a separate complete ERU-only\nrecipe, so I have not manufactured one."},{"id":"baba-190","source":"baba","sourceName":"OOGUN BABA OGUN","number":190,"title":"AGBEFUYE","subtitle":"(AGBEFUYE)","preview":"AGBEFUYE · OOGUN BABA OGUN","restricted":false,"content":"Materials needed:\n-Igba to ti fo - small piece from a broken\ncalabash\n-Esinsin - 7\n-Eyo Atare - 7\n***PREPARATION***\nWe will take a small piece from the broken Igba.\nWe will combine it with seven Esinsin and\nseven Atare.\nWe will burn the materials together.\nWe will grind the burnt preparation thoroughly\ninto powder.\n***USAGE***\nThe historical practitioner source prescribes\napplying the powder through seven Gbere\naround the back/wrist area of each hand.\nSource:\nPublic practitioner compilation - \"AGBEFUYE.\"\nIMPORTANT:\nThe source literally prescribes Gbere, meaning\ncuts or scarification.\nCutting the skin can cause infection, scarring\nand transmission of blood-borne disease, so I\nam documenting the source rather than\nrecommending that method.\nSOURCE NOTE:\nSources disagree about the claimed meaning of\nAGBEFUYE:\n-one popular practitioner list calls it a\n\"lightening charm\";\n-the academic Ifo crime-prevention study\nglosses it differently as \"body weight loser.\"\nThe formula above is included because it is\nactually published under the exact heading\nAGBEFUYE."}];
const byId=new Map(ENTRIES.map(x=>[x.id,x]));
function verifyAdmin(pass){
  try{
    const admin=String(process.env.OOGUN_ADMIN_KEY||"");
    const supplied=String(pass||"");
    if(!admin||!supplied) return false;
    const a=Buffer.from(supplied);
    const b=Buffer.from(admin);
    return a.length===b.length&&crypto.timingSafeEqual(a,b);
  }catch{return false}
}
function verifyPass(pass,id){
  try{
    if(!pass||!pass.startsWith("OG1.")) return false;
    const parts=pass.split(".");
    if(parts.length!==3) return false;
    const payload64=parts[1], sig=parts[2];
    const secret=process.env.OOGUN_ACCESS_SECRET;
    if(!secret) return false;
    const expected=crypto.createHmac("sha256",secret).update(payload64).digest("base64url").slice(0,22);
    const a=Buffer.from(sig),b=Buffer.from(expected);
    if(a.length!==b.length||!crypto.timingSafeEqual(a,b)) return false;
    const data=JSON.parse(Buffer.from(payload64,"base64url").toString("utf8"));
    if(!data.e||Date.now()>data.e) return false;
    if(data.s!=="all"&&data.s!==id) return false;
    return true;
  }catch{return false}
}
module.exports=(req,res)=>{
  res.setHeader("Cache-Control","no-store");
  if(req.method!=="POST") return res.status(405).json({error:"Method not allowed"});
  const {id,password}=req.body||{};
  const item=byId.get(String(id||""));
  if(!item) return res.status(404).json({error:"Document not found"});
  const supplied=String(password||"");
  if(!verifyAdmin(supplied)&&!verifyPass(supplied,item.id)) return res.status(401).json({error:"Invalid or expired access password"});
  return res.status(200).json({document:item});
};
